window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0201", [{"word":"kinetic","ipa_uk":"/kɪˈnetɪk/","ipa_us":"/kɪˈnetɪk/","definition_zh":"运动的；由运动产生的；动能的；动态的","definition_en":"relating to, caused by, or producing motion","core_image":"台球桌上，一颗静止的球被另一颗撞开，滑过绿呢台面，力在相触的一瞬传了过去","scene":"台球桌上，一颗静止的球被另一颗撞开，滑过绿呢台面，力在相触的一瞬传了过去。The kinetic energy of the moving ball is passed on the moment they touch.","sceneCN":"这里 kinetic 指与运动有关的（第 1 个义项：属于或关于运动）；句意：运动球体的动能就在两球相触的一瞬传了过去。图中可辨识物件：绿呢台面、两颗球、球杆、袋口。","pos":[{"tag":"adj.","zh":"运动的；由运动产生的；动力学的"}],"collocations":[{"phrase":"kinetic energy","zh":"动能"},{"phrase":"kinetic theory","zh":"分子运动论"},{"phrase":"kinetic art","zh":"动态艺术"},{"phrase":"kinetic sculpture","zh":"动态雕塑"},{"phrase":"kinetic friction","zh":"动摩擦"},{"phrase":"kinetic molecular theory","zh":"分子运动理论"}],"forms":[{"label":"原级","form":"kinetic"},{"label":"比较级","form":"more kinetic"},{"label":"最高级","form":"most kinetic"},{"label":"副词","form":"kinetically"},{"label":"名词（动力学）","form":"kinetics"}],"derivatives":[{"word":"kinetics","pos":"n.","zh":"动力学；运动学分支"},{"word":"kinetically","pos":"adv.","zh":"在运动方面；从运动角度"},{"word":"kinematic","pos":"adj.","zh":"运动学的"},{"word":"kinesis","pos":"n.","zh":"运动；（生物）应激性运动"},{"word":"kinesiology","pos":"n.","zh":"运动机能学"}],"senses":[{"no":"01","title":"Relating to motion","titleCN":"与运动有关的","definition":"relating to or involving movement","definitionCN":"与移动、运动有关的","example":"Kinetic energy grows with the square of the speed.","exampleCN":"动能随速度的平方增长。","why":"kinetic is simply the adjective built on the Greek noun for movement, so its plainest job is to mark anything that has to do with motion.","whyCN":"kinetic 就是由希腊语「运动」这一名词派生的形容词，因此最基本的作用是给一切与运动有关的事物作标记。"},{"no":"02","title":"Produced by movement","titleCN":"由运动产生的","definition":"caused by or resulting from movement, often as heat or force","definitionCN":"由移动引起的，常表现为热或力","example":"The friction of the brake pads turns kinetic energy into heat.","exampleCN":"刹车片的摩擦把动能变成热。","why":"when a moving body is stopped, its motion does not vanish but appears as heat or wear, so the adjective also describes effects that motion produces.","whyCN":"运动物体被拦住时，运动并未消失，而是以热或磨损的形式出现，因此这个词也描述运动所产生的结果。"},{"no":"03","title":"Of the energy carried by motion","titleCN":"指运动所携带的能量","definition":"describing the energy a body has because it is moving, as opposed to energy stored in its position","definitionCN":"指物体因正在运动而具有的能量，与储存在位置中的能量相对","example":"A falling stone turns its kinetic energy into sound and heat on impact.","exampleCN":"下落的石块在落地时把动能变成声与热。","why":"physics needed a short label for one quantity, the energy of motion, and fixed the pair kinetic energy against potential energy.","whyCN":"物理学需要给一个量一个短标签，即运动的能量，于是固定下「动能」与「势能」这对说法。"},{"no":"04","title":"Explaining matter by moving particles","titleCN":"用运动粒子解释物质性质","definition":"describing the model in which pressure, temperature and diffusion are explained by particles in constant motion","definitionCN":"指用不断运动的粒子来解释压强、温度与扩散的模型","example":"The kinetic theory treats gas pressure as collisions of moving molecules.","exampleCN":"分子运动论把气体压强看作运动分子碰撞的结果。","why":"once heat and pressure were traced to particles in motion, the adjective came to name the whole explanatory model, not just one body.","whyCN":"一旦热与压强被归结为运动中的粒子，这个词就用来命名整套解释模型，而不只是单个物体。"},{"no":"05","title":"Art whose parts actually move","titleCN":"零件真正会动的艺术","definition":"describing a work of art driven by motors, wind or water so that its parts move","definitionCN":"指由马达、风或水驱动、部件真的会动的艺术品","example":"The gallery mounted a kinetic sculpture that turned with the draft.","exampleCN":"美术馆展出了一件随气流转动的动态雕塑。","why":"twentieth-century artists borrowed the physics word to insist that the object itself moves, rather than merely showing movement.","whyCN":"二十世纪艺术家借用了物理学的这个词，强调作品本身在动，而不只是描绘运动。"},{"no":"06","title":"Lively and quick","titleCN":"精力旺盛、动作轻快的","definition":"full of energy and quick in movement, used of people, music or an atmosphere","definitionCN":"指人或音乐、气氛充满精力、动作轻快","example":"Her kinetic stage presence kept the audience awake.","exampleCN":"她在台上那股灵动的气场让观众一直清醒。","why":"what moves fast reads as energetic, so the physical adjective slid easily into praise for liveliness.","whyCN":"动得快的东西看上去就有劲，因此这个物理形容词很自然地滑向对「有活力」的称赞。"},{"no":"07","title":"Relating to human movement","titleCN":"与人体运动有关的","definition":"relating to the analysis or therapy of the way the body moves","definitionCN":"指对人体运动方式的分析或治疗","example":"The clinic uses kinetic analysis to correct a runner's stride.","exampleCN":"诊所通过运动分析来纠正跑者的步态。","why":"medicine took the word for the mechanics of a moving body, especially when measuring gait and treating movement faults.","whyCN":"医学借这个词指运动身体的力学，尤其在测量步态、治疗动作障碍时。"},{"no":"08","title":"Physical force in military use","titleCN":"军事用语中的实体打击","definition":"describing a weapon or action that uses physical force rather than cyber or electronic means","definitionCN":"指使用实体武力而非网络或电子手段的武器或行动","example":"Commanders weighed a kinetic response against a cyber one.","exampleCN":"指挥官在实体打击与网络手段之间权衡。","why":"modern military writing divides actions into physical hits and non-physical ones, and calls the physical kind kinetic.","whyCN":"现代军事写作把行动分为实体打击与非实体手段，并把实体那一类称为 kinetic。"}],"etymology":{"intro":{"en":"Kinetic comes from Greek kinētikos, an adjective meaning of or for moving, built on kinein, to move. It reached English through French in the nineteenth century. Dates are approximate.","cn":"kinetic 来自希腊语形容词 kinētikos「关于运动的」，其词根为 kinein「移动」。这个词在 19 世纪经法语进入英语。年代均为约数。"},"items":[{"era":"GREEK KINEIN","en":"Kinein meant to move, to set in motion, to stir. Its deeper origin is not established; the Indo-European forms sometimes offered for it are reconstructions, not attested words.","cn":"kinein 意为「移动、使动、搅动」。其更深来源未得到证明；有人为它给出的印欧语形式属于重构形式，并非有记录的词。"},{"era":"GREEK KINETIKOS","en":"From kinētos, movable, plus the adjective ending -ikos, Greek formed kinētikos, of or for moving. The word described anything able to cause or receive motion.","cn":"由 kinētos「可动的」加形容词词尾 -ikos，希腊语构成 kinētikos「关于运动的」。这个词可形容一切能引起或接受运动的事物。"},{"era":"GREEK KINEMA AND KINESIS","en":"The same root gave kinēma, a movement, and kinēsis, the act of moving. These two nouns later supplied cinema and kinesis, which is why the family looks wider than the adjective alone.","cn":"同一词根还给出 kinēma「运动、移动之物」与 kinēsis「运动（行为）」。这两个名词后来提供了 cinema 与 kinesis，所以这个词族看起来比单个形容词更宽。"},{"era":"FRENCH CINETIQUE","en":"French cinétique, used by physicists in the 1830s, supplied the model for the English adjective; English kinetic is recorded from the 1840s.","cn":"法国物理学家在 1830 年代使用的 cinétique 为英语形容词提供了样板；英语 kinetic 自 1840 年代起有记录。"},{"era":"KINETIC ENERGY","en":"William Thomson and Peter Guthrie Tait fixed the phrase kinetic energy in the 1860s, setting it beside potential energy in the teaching of mechanics.","cn":"威廉·汤姆森与彼得·古思里·泰特在 1860 年代固定下 kinetic energy 这一说法，在力学的教学中把它与势能并置。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (pre-Greek origin): the earlier history of kinein is unsettled, and any single Indo-European root proposed for it is a reconstruction rather than a demonstrated derivation.","cn":"来源不确定（希腊语之前的源头）：kinein 更早的历史没有定论，凡为它提出的单一印欧词根均属重构形式，而非已证实的派生。"}]},"similar":{"note":{"en":"The first group shares the Greek root for movement; the second group names neighbouring ideas of motion and energy with different emphasis.","cn":"第一组共享希腊语「运动」词根；第二组是意思相邻的「运动、能量」说法，侧重点各不相同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"kinetics","ipa":"/kɪˈnetɪks/","tag":"same root, noun","definition":"The branch of mechanics that studies motion and the forces producing it; the noun looks like the plural of kinetic but names a science.","definitionCN":"研究运动及产生运动的力的力学分支；形似 kinetic 的复数，实际是一门学科名。"},{"word":"kinematic","ipa":"/ˌkɪnəˈmætɪk/","tag":"same root, different suffix","definition":"Built on kinēma, a movement, and describing motion without asking what forces cause it, whereas kinetic belongs to the study of forces and energy.","definitionCN":"由 kinēma「运动」构成，描述运动而不问其成因；kinetic 则属于力与能量的研究。"},{"word":"kinesis","ipa":"/kɪˈniːsɪs/","tag":"same root, noun","definition":"The Greek noun for movement; in biology it names a movement response of an organism to a stimulus.","definitionCN":"希腊语「运动」这一名词；在生物学中指生物对刺激作出的运动反应。"},{"word":"cinema","ipa":"/ˈsɪnəmə/","tag":"same root, different field","definition":"Shortened from cinematograph, which was built on kinēma, a movement: pictures that move.","definitionCN":"由 cinematograph 缩略而来，后者由 kinēma「运动」构成，意即「会动的画面」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dynamic","ipa":"/daɪˈnæmɪk/","tag":"force and energy","definition":"From Greek dynamis, power: it stresses force and energy, and in physics it belongs to the study of forces rather than of motion alone.","definitionCN":"出自希腊语 dynamis「力量」：强调力与能量，在物理中属于力的研究，而不只是运动。"},{"word":"moving","ipa":"/ˈmuːvɪŋ/","tag":"plain participle","definition":"The everyday participle saying that something is in motion; kinetic is its technical and abstract counterpart.","definitionCN":"日常分词，直接说某物正在移动；kinetic 是它技术化、抽象化的对应词。"},{"word":"mobile","ipa":"/ˈməʊbaɪl/","tag":"able to move","definition":"Able to move or be moved, said of phones, people and machinery; it describes capacity, not energy.","definitionCN":"指能够移动或可被移动，用于电话、人与机械；说的是能力，不是能量。"},{"word":"mechanical","ipa":"/məˈkænɪkl/","tag":"machines","definition":"Relating to machines and their parts; it overlaps with kinetic in mechanics but says nothing about motion itself.","definitionCN":"与机器及其部件有关的；在力学中与 kinetic 有交集，但并不直接说「运动」。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root, the real word family and real fixed phrases, not invented rhymes.","cn":"正常联想：真实的希腊词根、真实的同族词与真实的固定搭配，而非编造的顺口溜。"},"normal":[{"en":"Kinein is Greek for to move, so kinetic means having to do with movement.","cn":"kinein 是希腊语「移动」，所以 kinetic 就是「与运动有关」。"},{"en":"The family runs kinetic, kinetics, kinetically, kinematic, kinesis and kinesiology.","cn":"同族词有 kinetic、kinetics、kinetically、kinematic、kinesis 与 kinesiology。"},{"en":"Fixed phrases mark the physical sense: kinetic energy, kinetic theory, kinetic friction.","cn":"固定搭配标出物理义：动能、分子运动论、动摩擦。"},{"en":"The same root hides inside cinema, because early films were pictures that move.","cn":"同一词根藏在 cinema 里，因为早期电影就是「会动的画面」。"},{"en":"Energy of motion sits opposite energy of position, so kinetic energy and potential energy are learned as a pair.","cn":"运动的能量与位置的能量相对，因此动能与势能总是成对学习。"}],"abstract":[{"en":"Picture a struck bell whose rim is still trembling after the hammer is gone.","cn":"想象一口被敲过的钟，锤子已经离开，钟沿还在颤。"},{"en":"Picture a relay racer who has already stopped but hands the baton to legs still running.","cn":"想象一位已经停下的接力手，把接力棒交给还在跑的腿。"},{"en":"Picture a mobile hanging over a cot, turning because the room itself is breathing.","cn":"想象婴儿床上方悬挂的风铃，因为房间本身在呼吸而转动。"}]},"examples":[{"en":"Kinetic energy is passed from one billiard ball to the next on contact.","cn":"动能就在两球相触时从一颗台球传到另一颗。"},{"en":"The kinetic theory explains gas pressure without naming any single molecule.","cn":"分子运动论解释气体压强，却不需要指名任何单个分子。"},{"en":"A kinetic installation in the hall turned slowly with the ventilation draft.","cn":"大厅里一件动态装置随着通风气流缓慢转动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「开（ki）了引擎（netic）」——引擎一开，车就动起来 → 运动的、动能的","word":"kinetic"},"root":"希腊 kinein「移动」→ kinētikos「关于运动的」→ 法语 cinétique → 英语 kinetic；更早的印欧词根无定论，相关形式均属重构。","sensesIntro":{"en":"Eight senses follow one gesture: something is moving, and the word tracks that motion into energy, into particles, into art, into a lively body and finally into physical force.","cn":"八个义项沿同一个动作展开：某物在动，这个词便沿着运动追到能量、粒子、艺术、有活力的身体，最后追到实体武力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cue ball set in motion by a strike, passing its motion to another ball on contact.","cn":"核心意象：被球杆击中的母球带着运动前进，在相触的一瞬把运动传给另一颗球。"},"chain":["MOTION","MOVING BODY","ENERGY CARRIED","PARTICLES IN MOTION","MOVING ART","PHYSICAL FORCE"],"branches":[{"senses":"01","en":"PLAIN MOTION: whatever the subject, the adjective first says that motion is involved.","cn":"单纯的运动：无论修饰什么，这个词首先说明与运动有关。"},{"senses":"02 · 03","en":"ENERGY OF MOVEMENT: motion can be handed on or turned into heat, and physics gives it a fixed name.","cn":"运动的能量：运动可以传递或变成热，物理学因此给它一个固定名称。"},{"senses":"04","en":"PARTICLES: the adjective explains pressure and temperature by particles that never stop moving.","cn":"粒子：这个词用永不停歇的粒子来解释压强与温度。"},{"senses":"05 · 07","en":"MOTION SEEN OR MEASURED: art makes parts turn visibly, medicine measures how a body actually moves.","cn":"被看见或被测量的运动：艺术让部件明显地转动，医学则测量身体实际的活动方式。"},{"senses":"06 · 08","en":"INTENSITY: liveliness and physical force are both motion raised to a high pitch.","cn":"强度：有活力与实体武力都是被推到高位的运动。"}]},"affixes":{"intro":{"en":"Kinetic is Greek from start to finish: a verb root, two noun forms and an adjective ending. Latin supplied only the shape of the adjective ending.","cn":"kinetic 从头到尾都是希腊语：一个动词词根、两个名词形式与一个形容词词尾。拉丁语只提供了形容词词尾的形式。"},"latinIntro":{"en":"No Latin noun stands behind this word, so the Latin entry list is empty; the ending -icus is the Latinised form of Greek -ikos.","cn":"这个词背后没有拉丁名词，因此拉丁词条列表留空；词尾 -icus 只是希腊语 -ikos 的拉丁化写法。"},"items":[{"word":"kinein","structure":"kinein (Greek verb, to move)","meaning":"to move, set in motion","meaningCN":"移动；使动","example":"The root carries the bare act of moving.","exampleCN":"这个词根带着「移动」这个最单纯的动作。"},{"word":"kinēsis","structure":"kinēsis (Greek noun, movement)","meaning":"movement; a moving","meaningCN":"运动；移动","example":"Biology borrowed this noun for stimulus-driven movement.","exampleCN":"生物学借这个名词指由刺激驱动的运动。"},{"word":"kinēma","structure":"kinēma (Greek noun, that which moves)","meaning":"a movement; a moving thing","meaningCN":"运动；移动之物","example":"Films were named from this noun because the pictures move.","exampleCN":"电影由这个名词得名，因为画面在动。"},{"word":"kinētikos","structure":"kinētos plus -ikos (Greek adjective)","meaning":"of or for moving","meaningCN":"关于运动的","example":"The adjective entered physics through French.","exampleCN":"这个形容词经法语进入物理学。"},{"word":"-ic","structure":"-ikos through Latin -icus (adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending turns a noun of movement into a describing word.","exampleCN":"这个词尾把「运动」的名词变成描述性的词。"},{"word":"kinetic","structure":"Greek kinētikos through French cinétique","meaning":"relating to motion","meaningCN":"与运动有关的","example":"Kinetic energy is the energy of a moving body.","exampleCN":"动能就是运动物体具有的能量。"},{"word":"kinetics","structure":"kinetic plus -ics (field of study)","meaning":"the study of motion and its causes","meaningCN":"研究运动及其成因的学科","example":"Kinetics asks how fast a reaction proceeds.","exampleCN":"动力学研究反应进行得有多快。"},{"word":"kinetically","structure":"kinetic plus -ally (adverb)","meaning":"in terms of motion","meaningCN":"从运动角度；在运动方面","example":"The two states differ kinetically, not in shape.","exampleCN":"这两种状态在运动方面不同，而非形状不同。"},{"word":"kinematic","structure":"Greek kinēma plus -ic","meaning":"describing motion without regard to force","meaningCN":"描述运动而不论其力的","example":"A kinematic model ignores what pushes the parts.","exampleCN":"运动学模型不考虑是什么推动这些部件。"},{"word":"kinesiology","structure":"kinesis plus -logy (study of)","meaning":"the study of human movement","meaningCN":"研究人体运动的学科","example":"Kinesiology maps how joints move under load.","exampleCN":"运动机能学描绘关节在受力时如何活动。"}],"latinEntries":[],"derivatives":[{"word":"kinetics","pos":"n.","zh":"动力学"},{"word":"kinetically","pos":"adv.","zh":"在运动方面"},{"word":"kinematic","pos":"adj.","zh":"运动学的"},{"word":"kinesis","pos":"n.","zh":"运动；应激性运动"},{"word":"kinesiology","pos":"n.","zh":"运动机能学"}]}},{"word":"chemistry","ipa_uk":"/ˈkemɪstri/","ipa_us":"/ˈkemɪstri/","definition_zh":"化学；物质的化学成分与性质；人与人之间的默契与吸引；（旧义）炼金术","definition_en":"the science that studies substances, their composition and the changes they undergo","core_image":"长桌上排着贴了手写标签的玻璃瓶，两种无色液体倒进同一只烧杯后立刻变成深蓝","scene":"长桌上排着贴了手写标签的玻璃瓶，两种无色液体倒进同一只烧杯后立刻变成深蓝。Chemistry explains why the two clear liquids turn deep blue when they meet.","sceneCN":"这里 chemistry 指研究物质组成与变化的学科（第 1 个义项：以物质及其变化为对象的科学）；句意：化学解释了两种清澈液体相遇后为何变成深蓝。图中可辨识物件：玻璃瓶、标签、烧杯、颜色骤变的液体。","pos":[{"tag":"n.","zh":"化学；化学成分；默契；吸引力"}],"collocations":[{"phrase":"organic chemistry","zh":"有机化学"},{"phrase":"physical chemistry","zh":"物理化学"},{"phrase":"analytical chemistry","zh":"分析化学"},{"phrase":"chemistry lab","zh":"化学实验室"},{"phrase":"chemistry set","zh":"化学实验套件"},{"phrase":"team chemistry","zh":"团队默契"}],"forms":[{"label":"复数","form":"chemistries"},{"label":"形容词（化学的）","form":"chemical"},{"label":"副词（化学上）","form":"chemically"},{"label":"名词（化学家）","form":"chemist"},{"label":"名词（生物化学）","form":"biochemistry"}],"derivatives":[{"word":"chemical","pos":"adj./n.","zh":"化学的 / 化学制品"},{"word":"chemically","pos":"adv.","zh":"化学上；用化学方法"},{"word":"chemist","pos":"n.","zh":"化学家；药剂师"},{"word":"biochemistry","pos":"n.","zh":"生物化学"},{"word":"petrochemistry","pos":"n.","zh":"石油化学"}],"senses":[{"no":"01","title":"The science of substances","titleCN":"研究物质的学科","definition":"the branch of science that studies what substances are made of and how they change","definitionCN":"研究物质由什么构成、如何变化的科学分支","example":"Chemistry explains why the two clear liquids turn deep blue when they meet.","exampleCN":"化学解释了两种清澈液体相遇后为何变成深蓝。","why":"the word names the discipline itself, the organised body of knowledge about substances and their changes.","whyCN":"这个词指学科本身，即关于物质及其变化的有组织知识体系。"},{"no":"02","title":"The makeup of a particular substance","titleCN":"某一具体物质的成分与性质","definition":"the composition and behaviour of a specific material, as in the chemistry of glass or of soil","definitionCN":"某一具体材料的组成与行为，如玻璃或土壤的化学成分","example":"The chemistry of the local clay makes it useless for fine pottery.","exampleCN":"本地黏土的化学成分使它不适合做精细陶器。","why":"from the discipline the word was transferred to the object it studies: a material has a chemistry, meaning its own makeup.","whyCN":"这个词从学科转到了它所研究的对象：一种材料「有化学成分」，指的是它自身的组成。"},{"no":"03","title":"A course or subject at school","titleCN":"学校里的化学课程或专业","definition":"the subject as it is taught or taken as a course or degree","definitionCN":"作为课程或学位来教授、修读的这门科目","example":"She took chemistry in the morning and biology in the afternoon.","exampleCN":"她上午上化学，下午上生物。","why":"school timetables turn every discipline into a slot, so the name of the science also names the class in it.","whyCN":"学校的课表把每门学科变成一个时段，因此这门学科的名字也指上这门课。"},{"no":"04","title":"Mutual attraction between people","titleCN":"人与人之间的吸引","definition":"a feeling of attraction or rapport between two people","definitionCN":"两个人之间产生的吸引或默契","example":"There was an obvious chemistry between the two leads on screen.","exampleCN":"屏幕上两位主角之间有一种明显的默契。","why":"the metaphor treats attraction as a reaction between two substances: either they combine or nothing happens.","whyCN":"这个比喻把吸引当作两种物质之间的反应：要么结合，要么什么也不发生。"},{"no":"05","title":"How a group works together","titleCN":"团队协作产生的默契","definition":"the way members of a team combine, especially when the combination produces more than the parts","definitionCN":"团队成员组合的方式，尤指组合后效果大于各部分之和","example":"The coach spent the season building team chemistry.","exampleCN":"教练用整个赛季来培养团队默契。","why":"the same metaphor widened from two people to a whole group, whose mixing either works or does not.","whyCN":"同样的比喻从两个人扩大到整个群体：他们的混合要么成功，要么失败。"},{"no":"06","title":"Alchemy, the older art","titleCN":"旧义：炼金术","definition":"the older art of trying to turn base metals into gold, before the modern science separated from it","definitionCN":"在现代科学分离出来之前，试图把贱金属变为黄金的旧技艺","example":"Medieval chemistry was half experiment and half transmutation lore.","exampleCN":"中世纪的炼金术一半是实验，一半是变金的传说。","why":"the modern word descends from the Arabic name of alchemy, and until the seventeenth century the two were one activity.","whyCN":"现代这个词源自阿拉伯语对炼金术的称呼，直到 17 世纪，两者仍是同一项活动。"},{"no":"07","title":"Chemical processes inside a body","titleCN":"生物体内的化学过程","definition":"the chemical activity of a living body, as in body chemistry or brain chemistry","definitionCN":"生物体内的化学活动，如身体化学、大脑化学","example":"Regular sleep keeps the brain chemistry in balance.","exampleCN":"规律睡眠让大脑的化学活动保持平衡。","why":"medicine speaks of a patient's chemistry when it means the chemical processes running inside, not a science course.","whyCN":"医学说某人的「化学成分」时，指的是体内运转的化学过程，而不是一门课。"},{"no":"08","title":"Chemistry of a setting or field","titleCN":"某一环境或领域中的化学","definition":"the chemical processes characteristic of a particular environment, as in ocean chemistry or atmospheric chemistry","definitionCN":"某一特定环境所特有的化学过程，如海洋化学、大气化学","example":"Ocean chemistry is shifting as the water absorbs more carbon dioxide.","exampleCN":"随着海水吸收更多二氧化碳，海洋的化学过程正在改变。","why":"each setting has its own mixture of reactions, so the discipline name attaches to the setting and becomes a subfield.","whyCN":"每个环境都有自己的一套反应，于是学科名附着于环境，成为一门分支。"}],"etymology":{"intro":{"en":"Chemistry reaches English through alchemy, Medieval Latin and Arabic al-kīmiyā, and probably from a Greek term for the metal-working art. The pre-Greek origin is unsettled; the competing explanations are listed below as hypotheses. Dates are approximate.","cn":"chemistry 经炼金术、中世纪拉丁语与阿拉伯语 al-kīmiyā 进入英语，更早可能出自希腊语中表示冶金技艺的词。希腊语之前的来源没有定论，下列竞争性解释均作为假说列出。年代均为约数。"},"items":[{"era":"GREEK KHEMEIA","en":"Greek had a term for the art of working metals, recorded in several spellings such as khēmeia and khymeia. What the Greek word itself meant, and how it was formed, is disputed.","cn":"希腊语有一个指冶金技艺的词，见于 khēmeia、khymeia 等多种拼写。这个希腊词本身是什么意思、如何构成，仍有争议。"},{"era":"ARABIC AL-KIMIYA","en":"Arabic al-kīmiyā took over the art and its name, keeping the definite article al-, which survives in the English alchemy.","cn":"阿拉伯语 al-kīmiyā 承接了这门技艺及其名称，并保留定冠词 al-，这一冠词残留在英语 alchemy 中。"},{"era":"MEDIEVAL LATIN","en":"Medieval Latin alchimia and alchemia named both the practice and the books about it, and from Latin the word passed into the European languages.","cn":"中世纪拉丁语 alchimia 与 alchemia 既指这门实践，也指关于它的书；这个词从拉丁语传入欧洲各语言。"},{"era":"ENGLISH ALCHEMY","en":"English alchemy is recorded from the fourteenth century. The spelling with ch reflects the Greek term and displaced older forms with c or k.","cn":"英语 alchemy 自 14 世纪有记录。带 ch 的拼写反映希腊语原词，并取代了更早的 c 或 k 拼写。"},{"era":"CHEMISTRY SPLITS OFF","en":"In the seventeenth century chemistry was used for the experimental study of substances, while alchemy was left to the older quest for transmutation.","cn":"17 世纪，chemistry 用于指对物质的实验研究，而 alchemy 则留给更古老的变金追求。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (pre-Greek origin): three explanations are current. One derives the Greek word from khein, to pour, through a noun for fluid; one connects it with Khēmia, a Greek name for Egypt; one takes it from a word for casting or fusing metal. None is demonstrated, and any reconstructed older form is a hypothesis.","cn":"来源不确定（希腊语之前的源头）：目前有三种解释。一说希腊词出自 khein「倾倒」，经一个表示流体的名词而来；一说与 Khēmia（希腊语对埃及的称呼）有关；一说出自表示「铸造、熔合金属」的词。三者均未被证实，凡重构的更早形式都只是假说。"}]},"similar":{"note":{"en":"The first group is the same word family and the same historical line; the second group names neighbouring sciences and the older art that chemistry grew out of.","cn":"第一组是同一词族、同一条历史线；第二组是相邻学科，以及化学由之生长出来的那门旧技艺。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"alchemy","ipa":"/ˈælkəmi/","tag":"same source, older art","definition":"The medieval art of transmuting metals, which shares the Arabic name but kept the goal that chemistry abandoned.","definitionCN":"中世纪试图转变金属的技艺，与 chemistry 共享阿拉伯语名称，却保留了化学后来放弃的目标。"},{"word":"chemist","ipa":"/ˈkemɪst/","tag":"same family, person","definition":"The person who practises the science, or in British English the person who dispenses medicines; it is not the science itself.","definitionCN":"从事这门科学的人，在英式英语中也指配药的人；它不是这门科学本身。"},{"word":"chemical","ipa":"/ˈkemɪkl/","tag":"same family, adjective","definition":"The adjective and noun built on the same stem: relating to chemistry, or a substance produced by it.","definitionCN":"同词干构成的形容词与名词：与化学有关的，或由化学产生的物质。"},{"word":"chemically","ipa":"/ˈkemɪkli/","tag":"same family, adverb","definition":"The adverb saying in chemical terms or by chemical means; it modifies the action rather than naming the field.","definitionCN":"副词，表示「从化学角度」或「用化学方法」；它修饰动作，而不命名领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"physics","ipa":"/ˈfɪzɪks/","tag":"neighbouring science","definition":"The science of matter, energy and their interactions; chemistry overlaps with it at the scale of atoms but is defined by substances and reactions.","definitionCN":"研究物质、能量及其相互作用的科学；化学在原子尺度与它重叠，但以物质与反应为界定。"},{"word":"biochemistry","ipa":"/ˌbaɪəʊˈkemɪstri/","tag":"subfield","definition":"The chemistry of living things, a branch that takes the methods of chemistry into biology.","definitionCN":"生物的化学，是把化学方法带进生物学的一门分支。"},{"word":"materials science","ipa":"/məˈtɪəriəlz ˈsaɪəns/","tag":"applied neighbour","definition":"The study of how the structure of a material determines its properties, close to chemistry but aimed at engineering.","definitionCN":"研究材料结构如何决定其性质，接近化学，但面向工程。"},{"word":"pharmacology","ipa":"/ˌfɑːməˈkɒlədʒi/","tag":"applied neighbour","definition":"The study of how drugs act on the body, which relies on chemistry but asks a medical question.","definitionCN":"研究药物如何作用于身体，依赖化学方法，但提出的是医学问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Arabic and Greek lineage, the real word family and real fixed phrases.","cn":"正常联想：真实的阿拉伯语与希腊语源流、真实的同族词与真实的固定搭配。"},"normal":[{"en":"The Arabic article al- still sits at the front of alchemy, the older name of the same art.","cn":"阿拉伯语冠词 al- 仍留在 alchemy 的开头，那是同一门技艺的旧名。"},{"en":"The family runs chemistry, chemical, chemically, chemist and biochemistry.","cn":"同族词有 chemistry、chemical、chemically、chemist 与 biochemistry。"},{"en":"Fixed phrases name its branches: organic chemistry, physical chemistry, analytical chemistry.","cn":"固定搭配标出它的分支：有机化学、物理化学、分析化学。"},{"en":"The same stem serves the science, the substance and the person, which is why chemical appears everywhere.","cn":"同一词干同时服务学科、物质与人，所以 chemical 到处出现。"},{"en":"Laboratory vocabulary makes the core picture concrete: beaker, reagent, reaction, precipitate.","cn":"实验室词汇把核心画面落到实处：烧杯、试剂、反应、沉淀。"}],"abstract":[{"en":"Picture two liquids that look identical and turn blue only when they touch.","cn":"想象两种看起来一模一样的液体，只有相触时才变成蓝色。"},{"en":"Picture a conversation where nothing is said aloud but the two people already agree.","cn":"想象一场对话，没有人出声，两个人却已经达成一致。"},{"en":"Picture an old furnace still standing beside a modern glass wall, sharing one name.","cn":"想象一座旧炉子立在现代玻璃幕墙旁，两者共用一个名字。"}]},"examples":[{"en":"Green chemistry aims to design reactions that produce less waste.","cn":"绿色化学旨在设计产生更少废料的反应。"},{"en":"The chemistry between the two actors made the film easy to believe.","cn":"两位演员之间的默契让这部电影容易令人信服。"},{"en":"Soil chemistry decides which crops can be grown on a field.","cn":"土壤的化学成分决定一块地能种什么作物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chemi（ chemo 化疗）+ stry」——与药物、反应打交道的那门学问 → 化学","word":"chemistry"},"root":"阿拉伯 al-kīmiyā「炼金术」→ 中世纪拉丁 alchimia → 英语 alchemy → chemistry；希腊语之前的源头无定论，倾倒说、埃及说、铸造说三者并列。","sensesIntro":{"en":"Eight senses follow one discipline: the science of substances, then the makeup of one material, then the class where it is taught, then two kinds of human attraction, the old art, the chemistry inside a body and the chemistry of a whole environment.","cn":"八个义项沿一门学科展开：先是研究物质的科学，再是某一种材料的成分，再是教授它的课程，随后是两种人与人之间的吸引、那门旧技艺、体内的化学，以及整个环境的化学。"},"semanticMap":{"core":{"en":"CORE IMAGE: two clear liquids meeting in one beaker and turning deep blue, a change nobody can see coming.","cn":"核心意象：两种清澈液体在一只烧杯里相遇，变成深蓝，变化在发生前无人看得见。"},"chain":["SCIENCE OF SUBSTANCES","MAKEUP OF A MATERIAL","SCHOOL SUBJECT","ATTRACTION","ALCHEMY","CHEMISTRY OF A SETTING"],"branches":[{"senses":"01","en":"THE DISCIPLINE: the organised knowledge of what substances are and how they change.","cn":"学科本身：关于物质是什么、如何变化的有组织知识。"},{"senses":"02 · 08","en":"A MATERIAL'S OWN MIX: glass, soil, an ocean each has a chemistry, and naming the setting makes a subfield.","cn":"材料自身的配比：玻璃、土壤、海洋各有一套化学，命名环境便形成分支。"},{"senses":"03","en":"THE TIMETABLE SLOT: a discipline becomes a course with a room and an hour.","cn":"课表上的格子：一门学科变成有教室、有课时的一门课。"},{"senses":"04 · 05","en":"REACTION BETWEEN PEOPLE: two people or a whole team combine as substances do.","cn":"人与人之间的反应：两个人或整个团队像物质一样混合。"},{"senses":"06 · 07","en":"OLD ART AND INNER PROCESSES: the furnace of transmutation and the chemistry running inside a living body.","cn":"旧技艺与体内过程：变金的炉子，与活体内部运转的化学。"}]},"affixes":{"intro":{"en":"Chemistry is a whole-word borrowing rather than a prefix-plus-root construction, but its ending and its family can still be read piece by piece, and the stem chem- recurs across the language.","cn":"chemistry 是整词借入，而非前缀加词根的构造，但它的词尾与词族仍可逐段读出，chem- 这一词干在英语中反复出现。"},"latinIntro":{"en":"Medieval Latin alchimia and alchimista stand behind the English family, and the Latinised adjective chymicus supplied the pattern for chemical.","cn":"中世纪拉丁语 alchimia 与 alchimista 是英语词族的来源，拉丁化的形容词 chymicus 则为 chemical 提供了样板。"},"items":[{"word":"chem-","structure":"bound stem from alchemy (Arabic al-kīmiyā)","meaning":"the art and later the science of substances","meaningCN":"关于物质的技艺，后指这门科学","example":"The bare stem survives in dozens of compounds.","exampleCN":"这一裸露词干存活在数十个复合词中。"},{"word":"-istry","structure":"-istry (noun ending of a field or practice)","meaning":"the field or practice named by the stem","meaningCN":"由词干命名的领域或实践","example":"The ending turns the stem into the name of a discipline.","exampleCN":"这个词尾把词干变成一门学科的名称。"},{"word":"chemistry","structure":"chem- plus -istry","meaning":"the science of substances","meaningCN":"研究物质的科学","example":"Chemistry explains the colour change.","exampleCN":"化学解释了这一颜色变化。"},{"word":"chemical","structure":"chem- plus -ical (relating to)","meaning":"relating to chemistry; a substance so produced","meaningCN":"与化学有关的；由此产生的物质","example":"A chemical reaction rearranges atoms.","exampleCN":"化学反应重新排列原子。"},{"word":"chemically","structure":"chemical plus -ly (adverb)","meaning":"in chemical terms or by chemical means","meaningCN":"从化学角度；用化学方法","example":"The two samples differ chemically.","exampleCN":"这两个样品在化学上不同。"},{"word":"chemist","structure":"chem- plus -ist (person)","meaning":"a person who practises chemistry","meaningCN":"从事化学的人","example":"The chemist weighed the powder to the milligram.","exampleCN":"化学家把粉末称到毫克。"},{"word":"alchemy","structure":"Arabic al-kīmiyā, the older name","meaning":"the older art of transmutation","meaningCN":"更古老的变金技艺","example":"Alchemy kept the furnace and the secrecy.","exampleCN":"炼金术保留了炉子与秘密。"},{"word":"biochemistry","structure":"bio- (life) plus chemistry","meaning":"the chemistry of living things","meaningCN":"生物的化学","example":"Biochemistry explains how enzymes speed up reactions.","exampleCN":"生物化学解释酶如何加快反应。"},{"word":"chemotherapy","structure":"chemo- (chemical) plus therapy","meaning":"treatment by chemical drugs","meaningCN":"用化学药物治疗","example":"The word uses the same stem in a medical setting.","exampleCN":"这个词在医学语境中使用同一词干。"},{"word":"petrochemistry","structure":"petro- (rock, oil) plus chemistry","meaning":"the chemistry of petroleum","meaningCN":"石油的化学","example":"Petrochemistry turns crude oil into plastics.","exampleCN":"石油化学把原油变成塑料。"}],"latinEntries":[{"word":"alchimia","structure":"alchimia, alchimiae (f., first declension)","meaning":"alchemy; the transmutation art","meaningCN":"炼金术；变金技艺"},{"word":"alchimista","structure":"alchimista, alchimistae (m., first declension)","meaning":"an alchemist","meaningCN":"炼金术士"},{"word":"chymicus","structure":"chymicus (adj., medieval Latin)","meaning":"chemical; of the chemical art","meaningCN":"化学的；属于化学技艺的"}],"derivatives":[{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemically","pos":"adv.","zh":"化学上；用化学方法"},{"word":"chemist","pos":"n.","zh":"化学家；药剂师"},{"word":"biochemistry","pos":"n.","zh":"生物化学"},{"word":"chemotherapy","pos":"n.","zh":"化学治疗"}]}},{"word":"chemist","ipa_uk":"/ˈkemɪst/","ipa_us":"/ˈkemɪst/","definition_zh":"化学家；药剂师（英式）；药房（英式，the chemist's）","definition_en":"a scientist who works with chemistry, or in British English a person who prepares and sells medicines","core_image":"通风橱前一位穿白大褂的人，一手持滴管，一手在记录本上写下一行数字","scene":"通风橱前的白大褂把最后一滴试剂滴进烧杯，随即在记录本上写下一行数字。The chemist added the last drop of reagent and wrote the result down.","sceneCN":"这里 chemist 指从事化学工作的科学家（第 1 个义项：以化学研究为职业的人）；句意：化学家滴入最后一滴试剂，并把结果记了下来。图中可辨识物件：通风橱、滴管、烧杯、记录本。","pos":[{"tag":"n.","zh":"化学家；药剂师；药房"}],"collocations":[{"phrase":"research chemist","zh":"研究化学家"},{"phrase":"analytical chemist","zh":"分析化学师"},{"phrase":"organic chemist","zh":"有机化学家"},{"phrase":"dispensing chemist","zh":"配药药剂师"},{"phrase":"the chemist's","zh":"药房（英式）"},{"phrase":"process chemist","zh":"工艺化学师"}],"forms":[{"label":"复数","form":"chemists"},{"label":"名词（化学）","form":"chemistry"},{"label":"形容词（化学的）","form":"chemical"},{"label":"副词（化学上）","form":"chemically"},{"label":"旧拼写","form":"chymist"}],"derivatives":[{"word":"chemistry","pos":"n.","zh":"化学"},{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemically","pos":"adv.","zh":"化学上"},{"word":"biochemist","pos":"n.","zh":"生物化学家"},{"word":"alchemist","pos":"n.","zh":"炼金术士"}],"senses":[{"no":"01","title":"A scientist working in chemistry","titleCN":"从事化学研究的科学家","definition":"a person trained in chemistry who carries out research or laboratory work","definitionCN":"受过化学训练、从事研究或实验室工作的人","example":"The chemist added the last drop of reagent and wrote the result down.","exampleCN":"化学家滴入最后一滴试剂，并把结果记了下来。","why":"the agent ending -ist marks the person who performs the activity named by the stem, so chemist is the doer of chemistry.","whyCN":"施动词尾 -ist 标记执行词干所指活动的人，因此 chemist 就是「做化学的人」。"},{"no":"02","title":"A pharmacist in British usage","titleCN":"英式用法中的药剂师","definition":"in British English, a person qualified to prepare and dispense medicines","definitionCN":"在英式英语中指有资格配制与发放药物的人","example":"Ask the chemist whether the two prescriptions can be taken together.","exampleCN":"问问药剂师这两张处方能不能同时服用。","why":"British pharmacy grew out of the apothecary shop, where chemical preparation of remedies was the daily trade, so the same word covers the druggist.","whyCN":"英国的药房业脱胎于药剂师铺子，配制药剂是日常手艺，因此同一个词也指配药者。"},{"no":"03","title":"A pharmacy, in British usage","titleCN":"英式用法中的药房","definition":"the shop itself, usually in the phrase the chemist's","definitionCN":"指店铺本身，通常用于 the chemist's 这一说法","example":"The chemist's on the corner stays open until ten.","exampleCN":"街角的药房开到十点。","why":"in British speech a shop is often named after its trade, so the person's title became the name of the place.","whyCN":"英式口语常用行业名替代店铺，于是对人的称呼变成了店名。"},{"no":"04","title":"An analytical specialist","titleCN":"分析化学岗位上的专业人员","definition":"a specialist whose job is to identify and measure substances, often in a laboratory or factory","definitionCN":"以鉴定与测量物质为职责的专业人员，常在实验室或工厂工作","example":"The analytical chemist tested every batch for traces of lead.","exampleCN":"分析化学师检测每一批货是否含微量铅。","why":"workplaces split the trade into named posts, and the fixed phrase analytical chemist narrows the general title to one job.","whyCN":"工作场所把这一行分成有名字的岗位，固定说法「分析化学师」把通称收窄为一种职务。"},{"no":"05","title":"Someone trained in chemistry","titleCN":"受过化学训练的人（不限职业）","definition":"a person whose training is in chemistry, even if the present job lies elsewhere","definitionCN":"训练背景是化学的人，即使当前工作不在化学领域","example":"She is a chemist by training but now writes science policy.","exampleCN":"她出身化学专业，如今撰写科学政策。","why":"the title can mark a qualification rather than a post, so it survives a change of career.","whyCN":"这个称呼可以标记资历而非职位，因此换了职业仍然保留。"},{"no":"06","title":"An alchemist, in older use","titleCN":"旧用法中的炼金术士","definition":"the older spelling chymist named a practitioner of alchemy before the science separated out","definitionCN":"旧拼写 chymist 指化学独立出来之前的炼金术从业者","example":"Seventeenth-century chymists kept their furnaces in the cellar.","exampleCN":"十七世纪的炼金术士把炉子放在地窖里。","why":"the word and the art were one until the seventeenth century, so older texts use chemist for the transmutation worker.","whyCN":"直到 17 世纪，这个词与这门技艺还是一体的，因此旧文本用 chemist 指从事变金的人。"},{"no":"07","title":"An industrial process specialist","titleCN":"工业界的工艺化学师","definition":"a chemist who scales a laboratory reaction up to factory production","definitionCN":"把实验室反应放大到工厂生产的化学师","example":"The process chemist found a cheaper solvent for the plant.","exampleCN":"工艺化学师为工厂找到了一种更便宜的溶剂。","why":"industry needed a name for the person who turns a bench method into a production line, and reused the general title with a qualifier.","whyCN":"工业需要给「把台面方法变成生产线」的人一个名字，于是给通称加限定语再用。"},{"no":"08","title":"The person who dispenses in a hospital","titleCN":"医院里配药的人","definition":"the member of staff who prepares and issues medicines inside a hospital or clinic","definitionCN":"在医院或诊所内配制与发放药物的工作人员","example":"The ward chemist checked the dose before the nurse gave it.","exampleCN":"病房药剂师在护士给药前核对了剂量。","why":"hospital work separates prescribing from dispensing, and this sense labels the second role.","whyCN":"医院把开药与配药分开，这一义项标记的是后一个角色。"}],"etymology":{"intro":{"en":"Chemist is older in English than chemistry. It descends from medieval chymist, from Medieval Latin chimista, an alteration of alchimista, the alchemist. The modern spelling was reshaped after the Greek term. Dates are approximate.","cn":"chemist 在英语中比 chemistry 更早。它出自中古写法 chymist，再上溯中世纪拉丁语 chimista，那是对 alchimista「炼金术士」的改形。现代拼写依照希腊语原词改写。年代均为约数。"},"items":[{"era":"MEDIEVAL LATIN ALCHIMISTA","en":"Alchimista, from alchimia, named the practitioner of the transmutation art; the word circulated with the Arabic-derived name of the craft.","cn":"alchimista 出自 alchimia，指变金技艺的从业者；这个词随这门技艺的阿拉伯语名称一起流传。"},{"era":"CHYMISTA AND CHYMIST","en":"Late medieval Latin chimista dropped the first syllable, and English took chymist in the sixteenth century for the same practitioner.","cn":"中世纪末的拉丁语 chimista 脱落了开头音节，英语在 16 世纪以 chymist 接收这个词，所指相同。"},{"era":"GREEK RESPELLING","en":"Seventeenth-century writers reconnected the word with Greek khēmeia and respelled it chemist, with ch standing for the Greek chi.","cn":"17 世纪的写作者把这个词重新系到希腊语 khēmeia，改写为 chemist，用 ch 对应希腊字母 chi。"},{"era":"CHEMISTRY ARRIVES LATER","en":"The noun chemistry is a later formation from the same stem, so the person's title is historically prior to the science's name.","cn":"名词 chemistry 是同词干后起的构词，因此「人」的称呼在历史上早于「学科」的名称。"},{"era":"BRITISH PHARMACY","en":"In Britain the chemist's shop made the word the everyday name for a pharmacist and for the shop itself, a sense not usual in American English.","cn":"在英国，药房使这个词成了药剂师与店铺的日常称呼，这一义项在美式英语中不常用。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): beyond alchimista the trail enters the disputed pre-Greek history of alchemy, where the competing explanations are hypotheses rather than established facts.","cn":"来源不确定（更深源头）：越过 alchimista 之后，线索进入炼金术那个有争议的希腊语之前的历史，各种竞争性解释都只是假说，而非既定事实。"}]},"similar":{"note":{"en":"The first group is the same stem in its other grammatical shapes; the second group names neighbouring trades that the English word can shade into.","cn":"第一组是同一词干的其他语法形态；第二组是英语中这个词可能滑向的相邻职业。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chemistry","ipa":"/ˈkemɪstri/","tag":"same stem, subject","definition":"The name of the science itself; the person and the subject differ by their endings, not by their stem.","definitionCN":"这门科学本身的名称；人与学科只差词尾，词干相同。"},{"word":"chemical","ipa":"/ˈkemɪkl/","tag":"same stem, adjective","definition":"The adjective describing anything related to chemistry, or the noun for a substance so produced.","definitionCN":"描述与化学有关的形容词，或指由此产生的物质。"},{"word":"alchemist","ipa":"/ˈælkəmɪst/","tag":"older relative","definition":"The practitioner of the older art of transmutation; it keeps the full Arabic-derived stem that chemist shortened.","definitionCN":"更古老的变金技艺的从业者；它保留了 chemist 所缩短的、源自阿拉伯语的完整词干。"},{"word":"chymist","ipa":"/ˈkɪmɪst/","tag":"archaic spelling","definition":"An older spelling of the same word, still used when writing about seventeenth-century practice.","definitionCN":"同一个词的旧拼写，在写到 17 世纪实践时仍会使用。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pharmacist","ipa":"/ˈfɑːməsɪst/","tag":"British overlap","definition":"The standard modern title for the person who dispenses medicines; in Britain chemist covers the same role informally.","definitionCN":"指配药者的标准现代称呼；在英国，chemist 非正式地覆盖同一角色。"},{"word":"druggist","ipa":"/ˈdrʌɡɪst/","tag":"American trade word","definition":"An American term for a pharmacist or a pharmacy, now largely replaced by pharmacist and drugstore.","definitionCN":"美式英语中指药剂师或药房，如今多被 pharmacist 与 drugstore 取代。"},{"word":"apothecary","ipa":"/əˈpɒθəkəri/","tag":"historical trade","definition":"The pre-modern dealer in herbs and prepared remedies, the ancestor of the British chemist's shop.","definitionCN":"近代以前经营草药与配制药剂的人，是英国药房的前身。"},{"word":"researcher","ipa":"/rɪˈsɜːtʃə/","tag":"general role","definition":"A general word for anyone doing research; chemist specifies the field as well as the activity.","definitionCN":"泛指做研究的人；chemist 既指活动，也指明领域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin line, the real word family and real British usage.","cn":"正常联想：真实的拉丁语源流、真实的同族词与真实的英式用法。"},"normal":[{"en":"The -ist ending marks a person, just as it does in artist and scientist.","cn":"词尾 -ist 标记一个人，正如它在 artist 与 scientist 中那样。"},{"en":"The family runs chemist, chemistry, chemical, chemically and biochemist.","cn":"同族词有 chemist、chemistry、chemical、chemically 与 biochemist。"},{"en":"British fixed phrases carry the pharmacy sense: the chemist's, dispensing chemist.","cn":"英式固定说法承载药房义：药房、配药药剂师。"},{"en":"The older spelling chymist still appears in histories of alchemy.","cn":"旧拼写 chymist 仍出现在炼金术史著作中。"},{"en":"Chemist is older than chemistry, so the person named the trade before the science had its name.","cn":"chemist 比 chemistry 更早，人是先有称呼，学科后来才有名字。"}],"abstract":[{"en":"Picture a hand that both weighs a powder and counts out pills behind the same counter.","cn":"想象同一张柜台后面的一只手，既称量粉末，也数出药片。"},{"en":"Picture a shop sign that gives the trade instead of the address.","cn":"想象一块店铺招牌，写的是行业而不是地址。"},{"en":"Picture two rooms in one building, one with a furnace and one with a till.","cn":"想象同一栋楼里的两个房间，一间有炉子，一间有收银机。"}]},"examples":[{"en":"The chemist published a new method for measuring trace metals.","cn":"这位化学家发表了一种测量微量金属的新方法。"},{"en":"In Britain you can buy cough syrup at the chemist's.","cn":"在英国，你可以在药房买到止咳糖浆。"},{"en":"A process chemist shortened the plant's reaction time by half.","cn":"一位工艺化学师把工厂的反应时间缩短了一半。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「化学（chemistry）」去掉尾巴就是「chemist」——做化学的那个人 → 化学家；英式还指药剂师","word":"chemist"},"root":"中世纪拉丁 alchimista「炼金术士」→ chimista → 英语 chymist → 依希腊语改写为 chemist；化学学科名 chemistry 反而是后起构词。","sensesIntro":{"en":"Eight senses follow one person: the researcher, then the British dispenser, then the shop, then the specialised posts, then the qualification, then the older alchemist, then the industrial and hospital roles.","cn":"八个义项沿「一个人」展开：先是研究者，再是英式配药者，再是店铺，再是各种专门岗位，再是资历，再是更早的炼金术士，最后是工业与医院中的角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: a figure in a white coat at a fume hood, one hand on a pipette and one on a notebook.","cn":"核心意象：通风橱前一个穿白大褂的身影，一只手拿滴管，一只手按着记录本。"},"chain":["PERSON IN THE LAB","TRAINED SPECIALIST","DISPENSER","SHOP","OLD ALCHEMIST","INDUSTRIAL ROLE"],"branches":[{"senses":"01","en":"THE SCIENTIST: the person whose work is the science itself.","cn":"科学家：以这门科学为工作的人。"},{"senses":"02 · 08","en":"THE DISPENSER: preparing and giving out medicines, in a shop or on a ward.","cn":"配药者：在店铺或病房里配制、发放药物。"},{"senses":"03","en":"THE SHOP: the trade name becomes the name of the place.","cn":"店铺：行业称呼变成了地点名称。"},{"senses":"04 · 07","en":"THE NAMED POST: analysis in a laboratory, scale-up in a plant.","cn":"有名字的岗位：实验室里的分析，工厂里的放大生产。"},{"senses":"05 · 06","en":"THE TITLE AS HISTORY: a qualification that outlasts a job, and the older alchemist behind the word.","cn":"作为资历与历史的称呼：能长过职位的资历，以及词背后更早的炼金术士。"}]},"affixes":{"intro":{"en":"Chemist is a borrowed stem plus an agent ending, and the stem is the shortened form of the alchemy word that also gives chemistry and chemical.","cn":"chemist 是借入词干加施动词尾，词干是炼金术那个词的缩短形式，后者同时给出 chemistry 与 chemical。"},"latinIntro":{"en":"Medieval Latin alchimista and alchimia supply the stem, and the Latinised chymicus supplies the adjective pattern behind chemical.","cn":"中世纪拉丁语 alchimista 与 alchimia 提供词干，拉丁化的 chymicus 提供 chemical 背后的形容词样板。"},"items":[{"word":"chem-","structure":"bound stem from alchimista","meaning":"the art of substances","meaningCN":"关于物质的技艺","example":"The stem is shared by the person, the science and the adjective.","exampleCN":"这个词干由人、学科与形容词共同使用。"},{"word":"-ist","structure":"-ista through Latin and French (agent ending)","meaning":"a person who practises something","meaningCN":"从事某事的人","example":"The ending is the same one heard in artist.","exampleCN":"这个词尾与 artist 中的相同。"},{"word":"chemist","structure":"chem- plus -ist","meaning":"a practitioner of chemistry","meaningCN":"从事化学的人","example":"The chemist recorded every reading.","exampleCN":"化学家记录了每一次读数。"},{"word":"chemistry","structure":"chem- plus -istry","meaning":"the science itself","meaningCN":"这门科学本身","example":"Chemistry grew out of alchemy.","exampleCN":"化学由炼金术生长出来。"},{"word":"chemical","structure":"chem- plus -ical","meaning":"relating to chemistry","meaningCN":"与化学有关的","example":"A chemical change alters the substance.","exampleCN":"化学变化改变物质本身。"},{"word":"alchemist","structure":"al- plus chemist, the older title","meaning":"a practitioner of transmutation","meaningCN":"从事变金的人","example":"The alchemist kept the full stem.","exampleCN":"炼金术士保留了完整词干。"},{"word":"biochemist","structure":"bio- (life) plus chemist","meaning":"a chemist of living systems","meaningCN":"研究生命体系的化学家","example":"A biochemist studies enzymes in cells.","exampleCN":"生物化学家研究细胞中的酶。"},{"word":"chemist's","structure":"chemist plus possessive ending","meaning":"the shop of the chemist","meaningCN":"化学师的店铺，即药房","example":"The chemist's sells both remedies and advice.","exampleCN":"药房既卖药，也给建议。"},{"word":"chymist","structure":"older spelling of chemist","meaning":"the same person, before the Greek respelling","meaningCN":"改写前的同一称呼","example":"Chymist appears in older workshop records.","exampleCN":"chymist 出现在更早的作坊记录中。"},{"word":"chemistry set","structure":"chemistry plus set (a kit)","meaning":"a boxed kit for simple experiments","meaningCN":"装在小盒子里的简易实验套件","example":"The set let a child try safe reactions.","exampleCN":"这套器具让孩子尝试安全的反应。"}],"latinEntries":[{"word":"alchimista","structure":"alchimista, alchimistae (m., first declension)","meaning":"an alchemist","meaningCN":"炼金术士"},{"word":"alchimia","structure":"alchimia, alchimiae (f., first declension)","meaning":"alchemy","meaningCN":"炼金术"},{"word":"chymicus","structure":"chymicus (adj., medieval Latin)","meaning":"chemical","meaningCN":"化学的"}],"derivatives":[{"word":"chemistry","pos":"n.","zh":"化学"},{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemically","pos":"adv.","zh":"化学上"},{"word":"biochemist","pos":"n.","zh":"生物化学家"},{"word":"alchemist","pos":"n.","zh":"炼金术士"}]}},{"word":"chemically","ipa_uk":"/ˈkemɪkli/","ipa_us":"/ˈkemɪkli/","definition_zh":"化学上；用化学方法；在化学性质上；由化学作用造成地","definition_en":"in chemical terms, by chemical means, or with respect to chemical properties","core_image":"试纸浸入液面的一瞬由蓝转红，操作者把两张记录纸并排放好，比对颜色深浅","scene":"试纸浸入液面的一瞬由蓝转红，操作者把两张记录纸并排放好，比对颜色深浅。The two samples differ chemically even though they look identical.","sceneCN":"这里 chemically 指在化学性质上（第 4 个义项：就化学组成与性质而言）；句意：两个样品外观完全相同，化学性质却不同。图中可辨识物件：试纸、两支试管、比色卡、记录纸。","pos":[{"tag":"adv.","zh":"化学上；用化学方法；在化学性质方面"}],"collocations":[{"phrase":"chemically identical","zh":"化学上完全相同的"},{"phrase":"chemically inert","zh":"化学性质不活泼的"},{"phrase":"chemically pure","zh":"化学纯的"},{"phrase":"chemically synthesized","zh":"化学合成的"},{"phrase":"chemically related","zh":"化学上同族的"},{"phrase":"chemically induced","zh":"化学作用引起的"}],"forms":[{"label":"原级（副词无比较级）","form":"chemically"},{"label":"形容词（化学的）","form":"chemical"},{"label":"名词（化学）","form":"chemistry"},{"label":"名词（化学家）","form":"chemist"},{"label":"形容词（炼金术的）","form":"alchemical"}],"derivatives":[{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemistry","pos":"n.","zh":"化学"},{"word":"chemist","pos":"n.","zh":"化学家；药剂师"},{"word":"biochemically","pos":"adv.","zh":"在生物化学方面"},{"word":"alchemical","pos":"adj.","zh":"炼金术的"}],"senses":[{"no":"01","title":"In chemical terms","titleCN":"就化学而言","definition":"considered from the point of view of chemistry rather than of physics, biology or everyday description","definitionCN":"从化学而非物理、生物或日常描述的角度来看","example":"Chemically, the alloy is mostly iron with a little carbon.","exampleCN":"从化学上看，这种合金主要是铁，外加少量碳。","why":"the adverb opens a sentence the way a field label does, telling the reader which description is being used.","whyCN":"这个副词像领域标签一样开启句子，告诉读者正在使用哪一种描述方式。"},{"no":"02","title":"By chemical means","titleCN":"用化学方法","definition":"by a process that uses chemical agents rather than mechanical or physical ones","definitionCN":"通过使用化学试剂而非机械或物理手段的工序","example":"The surface was chemically polished before the paint went on.","exampleCN":"上漆之前，表面先用化学方法抛光。","why":"here the adverb answers how something is done, and the answer is a reaction rather than a tool.","whyCN":"这里的副词回答「怎么做」，而答案是反应，不是工具。"},{"no":"03","title":"By artificial synthesis","titleCN":"化学合成地","definition":"made in a laboratory or factory rather than taken directly from a living source","definitionCN":"在实验室或工厂制成，而非直接取自生物来源","example":"Most of the vitamin C in the bottle was chemically synthesized.","exampleCN":"瓶中的维生素 C 大多是化学合成的。","why":"since laboratory production is almost always chemical, the adverb became a short way of saying made rather than grown.","whyCN":"由于实验室生产几乎总是化学的，这个副词就成了「是造出来的，不是长出来的」的简写。"},{"no":"04","title":"In chemical properties","titleCN":"在化学性质上","definition":"with respect to composition and behaviour in reactions, as opposed to appearance","definitionCN":"就组成与反应中的行为而言，与外观相对","example":"The two samples differ chemically even though they look identical.","exampleCN":"两个样品外观完全相同，化学性质却不同。","why":"when two things look alike but behave differently, the adverb marks the hidden dimension in which they actually differ.","whyCN":"当两件东西样子相同而表现不同时，这个副词标出它们真正有差别的那个看不见的维度。"},{"no":"05","title":"Caused by a chemical","titleCN":"由化学物质造成的","definition":"brought about by exposure to a chemical substance, as a rash, a burn or a change in the body","definitionCN":"因接触化学物质而产生，如皮疹、灼伤或体内变化","example":"The rash was chemically induced, not infectious.","exampleCN":"这皮疹是化学物质引起的，不是传染性的。","why":"the adverb plus a participle names the cause, separating a reaction to a substance from a reaction to a germ.","whyCN":"副词加过去分词指明原因，把对物质的反应与对病菌的反应区分开。"},{"no":"06","title":"In chemical structure","titleCN":"在化学结构上","definition":"with respect to the arrangement of atoms or the identity of a molecular family","definitionCN":"就原子排列或分子所属类别而言","example":"The two hormones are chemically related but act on different tissues.","exampleCN":"这两种激素在化学结构上同族，却作用于不同组织。","why":"the adverb marks kinship at the level of structure rather than of function.","whyCN":"这个副词标记的是结构层面的亲缘关系，而不是功能层面。"},{"no":"07","title":"Inside the body's chemistry","titleCN":"在体内化学过程层面","definition":"with respect to the chemical processes of a living body, as in chemically altered metabolism","definitionCN":"就生物体内化学过程而言，如被化学改变的代谢","example":"The drug chemically alters the way the liver processes fat.","exampleCN":"这种药在化学层面改变了肝脏处理脂肪的方式。","why":"medicine describes what a substance does inside the body as a chemical change, so the adverb marks that inner level.","whyCN":"医学把某种物质在体内做的事描述为化学变化，这个副词便标记那个内部层面。"},{"no":"08","title":"As a field label in speech","titleCN":"口语中作为领域标记","definition":"used at the start of a remark to signal that the following statement belongs to chemistry","definitionCN":"置于话语开头，提示随后的话属于化学领域","example":"Chemically speaking, the two salts belong to the same family.","exampleCN":"从化学角度说，这两种盐属于同一族。","why":"speakers borrow the adverb to frame a claim, exactly as they say legally speaking or medically speaking.","whyCN":"说话人借这个副词来框定一句话，正如说「从法律上说」「从医学上说」。"}],"etymology":{"intro":{"en":"Chemically is the adverb of chemical, which comes from Medieval Latin chymicus, itself built on alchimia, the alchemy word. The adverb ending is English. Dates are approximate.","cn":"chemically 是 chemical 的副词形式；chemical 出自中世纪拉丁语 chymicus，后者又由 alchimia（炼金术一词）构成。副词词尾来自英语。年代均为约数。"},"items":[{"era":"MEDIEVAL LATIN CHYMICUS","en":"Chymicus, also written alchimicus, meant of the chemical art and described both substances and practitioners in medieval texts.","cn":"chymicus 也写作 alchimicus，意为「属于化学技艺的」，在中世纪文本中既形容物质，也形容从业者。"},{"era":"ENGLISH CHEMICAL","en":"English chemical appears in the seventeenth century, replacing the older chymical, and serves as both adjective and noun.","cn":"英语 chemical 出现于 17 世纪，取代更早的 chymical，既作形容词也作名词。"},{"era":"ADVERB ENDING -LY","en":"The ending -ly descends from Old English -līce and turns an adjective into an adverb of manner or viewpoint.","cn":"词尾 -ly 出自古英语 -līce，把形容词变成表示方式或视角的副词。"},{"era":"CHEMICALLY RECORDED","en":"Chemically is recorded in English from the seventeenth century, first in the sense of by chemical means.","cn":"chemically 在英语中自 17 世纪有记录，最初意为「用化学方法」。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin and first date): beyond chymicus the trail enters the disputed pre-Greek history of alchemy, and the earliest use of the adverb is not precisely dated, so both the date and the deeper chain are approximate.","cn":"来源不确定（更深源头与首见年代）：越过 chymicus 之后，线索进入炼金术那个有争议的希腊语之前的历史；这个副词的最早用例也没有确切年代，因此年代与更深源流都只是约数。"}]},"similar":{"note":{"en":"The first group is the same stem in other shapes; the second group is adverbs that label a different viewpoint or a different way of making something.","cn":"第一组是同一词干的其他形态；第二组是标记别的视角、或别的制作方式的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chemical","ipa":"/ˈkemɪkl/","tag":"same stem, adjective","definition":"The adjective behind the adverb; it describes a noun, whereas the adverb describes how or in what respect.","definitionCN":"副词背后的形容词，修饰名词；副词则说明方式或视角。"},{"word":"chemistry","ipa":"/ˈkemɪstri/","tag":"same stem, subject","definition":"The name of the science; it cannot stand where the adverb stands.","definitionCN":"学科名称，不能出现在副词的位置。"},{"word":"chemist","ipa":"/ˈkemɪst/","tag":"same stem, person","definition":"The person, not the manner; the pair differ by their endings alone.","definitionCN":"指人而非方式；两者只差词尾。"},{"word":"alchemical","ipa":"/ˌælˈkemɪkl/","tag":"older relative","definition":"The adjective of the older art, still used for symbolic or archaic contexts rather than for laboratory work.","definitionCN":"更古老技艺的形容词，仍用于象征性或古旧语境，而非实验室工作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"physically","ipa":"/ˈfɪzɪkli/","tag":"other viewpoint","definition":"In terms of physics or the body; it contrasts with chemically when a change is described at the level of atoms versus at the level of matter in bulk.","definitionCN":"从物理或身体角度；当变化分别从原子层面与宏观物质层面描述时，它与 chemically 相对。"},{"word":"biologically","ipa":"/baɪəˈlɒdʒɪkli/","tag":"other viewpoint","definition":"In terms of living processes; a substance may be chemically inert yet biologically active.","definitionCN":"从生命过程角度；一种物质可能在化学上不活泼，却在生物上有作用。"},{"word":"synthetically","ipa":"/sɪnˈθetɪkli/","tag":"way of making","definition":"By building a substance from simpler parts in a laboratory, a sense chemically can carry but does not always.","definitionCN":"在实验室里由更简单的部分造出物质，chemically 有时含此义，但并不总是。"},{"word":"artificially","ipa":"/ˌɑːtɪˈfɪʃli/","tag":"way of making","definition":"By human action rather than nature; it says nothing about the method, which chemically may specify.","definitionCN":"指非自然、由人力造成；它不说明方法，而 chemically 可能指明方法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin stem, the real adverb ending and real fixed phrases.","cn":"正常联想：真实的拉丁词干、真实的副词词尾与真实的固定搭配。"},"normal":[{"en":"Chemical plus the adverb ending -ly gives the word, and the ending answers the question how or in what respect.","cn":"chemical 加副词词尾 -ly 构成这个词，词尾回答「如何」或「在哪个方面」。"},{"en":"The family runs chemical, chemically, chemistry, chemist and alchemical.","cn":"同族词有 chemical、chemically、chemistry、chemist 与 alchemical。"},{"en":"Fixed phrases show the range: chemically identical, chemically inert, chemically pure.","cn":"固定搭配显示范围：化学上相同、化学上不活泼、化学纯。"},{"en":"The word sits beside physically and biologically as a viewpoint label.","cn":"这个词与 physically、biologically 并列，都是视角标签。"},{"en":"A strange ad says no chemicals, yet the product is chemically identical to the natural one.","cn":"一句奇怪的广告说「不含化学物质」，可产品与天然品在化学上完全相同。"}],"abstract":[{"en":"Picture two keys cut from the same blank that open different doors.","cn":"想象两把从同一块坯料切出的钥匙，却打开不同的门。"},{"en":"Picture a label on a bottle that describes behaviour instead of appearance.","cn":"想象瓶子上的一张标签，描述的是行为而不是外观。"},{"en":"Picture a translator who explains a taste by naming the ingredients.","cn":"想象一位译者，用列出配料来解释一种味道。"}]},"examples":[{"en":"Chemically, the human body is mostly water.","cn":"从化学上看，人体主要由水构成。"},{"en":"The pipes were chemically cleaned instead of replaced.","cn":"管道是用化学方法清洗的，而非更换。"},{"en":"Chemically speaking, graphite and diamond are the same element.","cn":"从化学角度说，石墨与金刚石是同一种元素。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「化学（chemical）+ 地（-ly）」——以化学的方式 → 化学上、用化学方法","word":"chemically"},"root":"中世纪拉丁 chymicus「属于化学技艺的」→ 英语 chemical「化学的」→ 加副词词尾 -ly → chemically；更深源头通向阿拉伯语炼金术名称，希腊语之前的来源无定论。","sensesIntro":{"en":"Eight senses follow one question: in what respect, or by what means, is something being described as chemical? The answer runs from a viewpoint label to a method, a manufacture, a property, a cause, a structure, an inner process and finally a phrase that frames a claim.","cn":"八个义项沿同一个问题展开：究竟在哪个方面、用什么手段，把某事说成「化学的」？答案从视角标签延伸到方法、制造、性质、成因、结构、体内过程，最后是一个框定话语的说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a strip of test paper crossing a liquid surface and changing colour at the moment of contact.","cn":"核心意象：一条试纸越过液面，在接触的一瞬变色。"},"chain":["VIEWPOINT","METHOD","MANUFACTURE","PROPERTY","CAUSE","STRUCTURE"],"branches":[{"senses":"01 · 08","en":"FRAMING: the word tells the listener which description is in force, in writing or in speech.","cn":"框定：这个词告诉听者，此刻生效的是哪一种描述，书面与口语皆然。"},{"senses":"02","en":"METHOD: a reaction does the work that a tool would otherwise do.","cn":"方法：让反应来完成本该由工具完成的活。"},{"senses":"03","en":"MANUFACTURE: what is made in a plant rather than grown.","cn":"制造：在工厂里造出来，而不是长出来。"},{"senses":"04 · 06","en":"HIDDEN DIMENSION: two things alike in appearance but different in makeup, or related in structure.","cn":"看不见的维度：外观相同而组成不同，或在结构上同族。"},{"senses":"05 · 07","en":"INNER CAUSE: a substance acting on a surface or inside a living body.","cn":"内部成因：物质作用于表面，或作用于活体内部。"}]},"affixes":{"intro":{"en":"Chemically is the shortest word in the family to show all three layers at once: a borrowed stem, an adjective ending and an adverb ending.","cn":"chemically 是这个词族中能一次显示三层结构的最短词：借入词干、形容词词尾、副词词尾。"},"latinIntro":{"en":"Medieval Latin chymicus and alchimia supply the stem and the adjective pattern; the adverb ending itself is English, not Latin.","cn":"中世纪拉丁语 chymicus 与 alchimia 提供词干与形容词样板；副词词尾本身来自英语，不是拉丁语。"},"items":[{"word":"chem-","structure":"bound stem from alchimia","meaning":"the art of substances","meaningCN":"关于物质的技艺","example":"The stem is shared by the whole family.","exampleCN":"这个词干由整个词族共用。"},{"word":"-ical","structure":"-icus through Latin and French","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes an adjective of the stem.","exampleCN":"这个词尾把词干变成形容词。"},{"word":"chemical","structure":"chem- plus -ical","meaning":"relating to chemistry","meaningCN":"与化学有关的","example":"A chemical change alters composition.","exampleCN":"化学变化改变组成。"},{"word":"-ly","structure":"Old English -līce (adverb ending)","meaning":"in a given manner or respect","meaningCN":"以某种方式或在某方面","example":"The ending turns the adjective into a manner word.","exampleCN":"这个词尾把形容词变成方式副词。"},{"word":"chemically","structure":"chemical plus -ly","meaning":"in chemical terms or by chemical means","meaningCN":"从化学角度；用化学方法","example":"The two samples differ chemically.","exampleCN":"两个样品在化学上不同。"},{"word":"chemistry","structure":"chem- plus -istry","meaning":"the science itself","meaningCN":"这门科学本身","example":"Chemistry studies composition and change.","exampleCN":"化学研究组成与变化。"},{"word":"chemist","structure":"chem- plus -ist","meaning":"a practitioner","meaningCN":"从业者","example":"The chemist ran the test.","exampleCN":"化学家做了这项检测。"},{"word":"alchemical","structure":"al- plus chemical","meaning":"of the older transmutation art","meaningCN":"属于更古老变金技艺的","example":"Alchemical symbols fill the old manuscript.","exampleCN":"古老手稿里满是炼金术符号。"},{"word":"biochemically","structure":"bio- (life) plus chemically","meaning":"in terms of the chemistry of life","meaningCN":"从生命化学角度","example":"The two patients are biochemically similar.","exampleCN":"两位病人在生物化学上相似。"}],"latinEntries":[{"word":"chymicus","structure":"chymicus (adj., medieval Latin)","meaning":"chemical; of the chemical art","meaningCN":"化学的；属于化学技艺的"},{"word":"alchimia","structure":"alchimia, alchimiae (f., first declension)","meaning":"alchemy","meaningCN":"炼金术"},{"word":"alchimicus","structure":"alchimicus (adj., medieval Latin)","meaning":"alchemical","meaningCN":"炼金术的"}],"derivatives":[{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemistry","pos":"n.","zh":"化学"},{"word":"chemist","pos":"n.","zh":"化学家；药剂师"},{"word":"alchemical","pos":"adj.","zh":"炼金术的"},{"word":"biochemically","pos":"adv.","zh":"在生物化学方面"}]}},{"word":"reactant","ipa_uk":"/riˈæktənt/","ipa_us":"/riˈæktənt/","definition_zh":"反应物；参与化学反应并被消耗的物质","definition_en":"a substance that takes part in and is changed by a chemical reaction","core_image":"两只贴着标签的烧杯被倒进同一个容器，液面上升，颜色开始变化","scene":"两只贴着标签的烧杯被倒进同一个容器，液面上升，颜色开始变化。Oxygen is the reactant that combines with iron to form rust.","sceneCN":"这里 reactant 指参与反应并被消耗的反应物（第 1 个义项：在化学反应中被转化的起始物质）；句意：氧气是与铁结合生成铁锈的反应物。图中可辨识物件：两只烧杯、标签、合并后的容器、变色的液面。","pos":[{"tag":"n.","zh":"反应物；参与反应的物质"}],"collocations":[{"phrase":"limiting reactant","zh":"限量反应物"},{"phrase":"excess reactant","zh":"过量反应物"},{"phrase":"reactant concentration","zh":"反应物浓度"},{"phrase":"reactant molecules","zh":"反应物分子"},{"phrase":"reactant gas","zh":"反应气体"},{"phrase":"unreacted reactant","zh":"未反应的反应物"}],"forms":[{"label":"复数","form":"reactants"},{"label":"动词（反应）","form":"react"},{"label":"名词（反应）","form":"reaction"},{"label":"形容词（反应性的）","form":"reactive"},{"label":"名词（反应堆）","form":"reactor"}],"derivatives":[{"word":"react","pos":"v.","zh":"反应；起反应"},{"word":"reaction","pos":"n.","zh":"反应"},{"word":"reactive","pos":"adj.","zh":"易起反应的；反应性的"},{"word":"reactivity","pos":"n.","zh":"反应性；活泼程度"},{"word":"reactor","pos":"n.","zh":"反应器；反应堆"}],"senses":[{"no":"01","title":"A substance consumed in a reaction","titleCN":"化学反应中被消耗的起始物质","definition":"a substance that enters a chemical reaction and is converted into something else","definitionCN":"进入化学反应并被转化为其他物质的起始物质","example":"Oxygen is the reactant that combines with iron to form rust.","exampleCN":"氧气是与铁结合生成铁锈的反应物。","why":"the ending -ant marks the thing performing the action of the verb, so a reactant is whatever is doing the reacting.","whyCN":"词尾 -ant 标记执行动词动作的事物，因此 reactant 就是「在起反应的那个东西」。"},{"no":"02","title":"Any input consumed by a process","titleCN":"被过程消耗的任何输入物","definition":"broadly, any material that a process takes in and uses up, even outside a strict chemical reaction","definitionCN":"广义上指某个过程吸入并消耗掉的任何材料，即使不在严格意义上的化学反应中","example":"The furnace cannot run if one reactant in the feed is missing.","exampleCN":"如果进料中缺少一种反应物，炉子就无法运转。","why":"industry widened the word from the flask to the whole plant, where every consumed input counts as a reactant.","whyCN":"工业把这个词从烧瓶扩大到整个工厂，凡被消耗的输入都算反应物。"},{"no":"03","title":"A reacting molecule or particle","titleCN":"发生反应的分子或粒子","definition":"a single molecule or ion considered as the unit that collides and changes","definitionCN":"被视作碰撞并发生变化的单位的单个分子或离子","example":"Each reactant must collide with enough energy to break its bonds.","exampleCN":"每个反应物分子都必须以足够的能量碰撞才能断键。","why":"at the microscopic scale the word shifts from a heap of stuff to one particle taking part in a collision.","whyCN":"在微观尺度上，这个词从「一堆物质」转为一个参与碰撞的粒子。"},{"no":"04","title":"The limiting reactant","titleCN":"限量反应物","definition":"the reactant present in the smallest proportion and therefore the one that stops the reaction first","definitionCN":"比例最小、因而最先使反应停止的反应物","example":"The limiting reactant decides how much product can form.","exampleCN":"限量反应物决定能生成多少产物。","why":"textbooks needed a fixed name for the one input that runs out first, and attached it to the general word.","whyCN":"教科书需要给「最先耗尽的那一种输入」一个固定名称，于是把它附着在通称上。"},{"no":"05","title":"The reactant left over","titleCN":"过量后剩余的反应物","definition":"a reactant supplied beyond what the reaction needs, so that some remains at the end","definitionCN":"供给超过反应所需，结束时仍有剩余的反应物","example":"Excess reactant is recovered from the outlet gas and returned to the feed.","exampleCN":"过量反应物从排出气体中回收，再送回进料。","why":"the same word covers the opposite role: the input that does not run out, and therefore must be handled afterwards.","whyCN":"同一个词也覆盖相反的角色：没有耗尽、因此事后必须处理的那种输入。"},{"no":"06","title":"A substrate in enzyme chemistry","titleCN":"酶化学中的底物","definition":"the molecule on which an enzyme acts, treated as the reactant of a biological reaction","definitionCN":"酶所作用的分子，被当作生物反应中的反应物","example":"The enzyme binds its reactant before the bond is broken.","exampleCN":"酶先结合它的反应物，然后才断键。","why":"biochemistry borrowed the general term and applied it to the molecule handed to an enzyme, while keeping substrate as the specialist word.","whyCN":"生物化学借用这个通称，指交给酶的分子，同时保留 substrate 这个更专门的词。"},{"no":"07","title":"Feed material in an industrial process","titleCN":"工业过程中的进料","definition":"the raw material charged into a reactor, often in the plural","definitionCN":"装入反应器的原料，常用复数","example":"Plant operators adjust the reactants hourly to keep the yield steady.","exampleCN":"工厂操作员每小时调整进料，以保持收率稳定。","why":"a production line speaks of reactants where a laboratory speaks of reagents, and the plural marks the bulk quantity.","whyCN":"生产线说 reactants，实验室说 reagents；复数标记的是大宗用量。"},{"no":"08","title":"A factor consumed by a change","titleCN":"比喻：被变化消耗的起因","definition":"figuratively, whatever is drawn on and changed by a process, as money or trust in a social change","definitionCN":"比喻用法，指被某个过程动用并改变的要素，如社会变化中的金钱或信任","example":"Trust was the reactant that the reform spent fastest.","exampleCN":"信任是这场改革消耗得最快的反应物。","why":"the metaphor treats any process as a reaction that consumes its inputs, a usage real in commentary but clearly figurative.","whyCN":"这个比喻把任何过程都当作消耗输入的反应，此用法在评论文字中确实存在，但明显是比喻。"}],"etymology":{"intro":{"en":"Reactant is an English coinage built from react plus the -ant ending, and react goes back to Latin re- plus agere, to act or drive. The chemical noun dates from the nineteenth century. Dates are approximate.","cn":"reactant 是英语自造词，由 react 加词尾 -ant 构成；react 上溯拉丁语 re- 加 agere「做、驱动」。这个化学名词产生于 19 世纪。年代均为约数。"},"items":[{"era":"LATIN AGERE","en":"Agere meant to do, to drive, to set going; its past participle actum supplied the noun act. The deeper Indo-European form is a reconstruction.","cn":"agere 意为「做、驱动、使前进」，其过去分词 actum 提供了名词 act。更早的印欧语形式属于重构。"},{"era":"LATIN REAGERE","en":"Re-, back, plus agere produced reagere, to act back or respond, which is the ancestor of the English verb react.","cn":"re-「向后」加 agere 构成 reagere「反过来行动、回应」，是英语动词 react 的祖先。"},{"era":"ENGLISH REACT","en":"English react appears in the seventeenth century in the general sense of acting in response, before chemistry narrowed it.","cn":"英语 react 于 17 世纪出现，先是一般的「作出回应」，化学随后才把它收窄。"},{"era":"COINED REACTANT","en":"Nineteenth-century chemistry coined reactant beside reaction to name the substance that undergoes the change, on the model of other -ant nouns.","cn":"19 世纪的化学在 reaction 之外造出 reactant，仿照其他 -ant 名词，指发生变化的物质。"},{"era":"-ANT","en":"The ending comes from Latin -ans, -antis, the present participle suffix, which English borrowed through French for nouns of agent or instrument.","cn":"词尾出自拉丁语 -ans、-antis，即现在分词后缀；英语经法语借入，用来构成施动者或工具名词。"},{"era":"FIRST DATE","en":"First date uncertain: dictionaries place the chemical noun in the nineteenth century, but the earliest citation is not settled, so the century given is approximate.","cn":"首见年代不确定：词典把这个化学名词置于 19 世纪，但最早的书证尚无定论，此处给出的世纪只是约数。"}]},"similar":{"note":{"en":"The first group shares the react stem and is constantly mixed up in laboratory writing; the second group names the other inputs and outputs of a reaction.","cn":"第一组共享 react 词干，在实验写作中极易混用；第二组是反应的其他输入与产出名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"reaction","ipa":"/riˈækʃn/","tag":"same stem, event","definition":"The process itself, not a substance in it; a reactant is what the reaction consumes.","definitionCN":"指过程本身，而不是过程中的物质；反应物是被反应消耗的东西。"},{"word":"reactor","ipa":"/riˈæktə/","tag":"same stem, vessel","definition":"The vessel or plant where the change happens; the -or ending marks a thing, not a material.","definitionCN":"变化发生的容器或装置；词尾 -or 标记器物，而非材料。"},{"word":"reactive","ipa":"/riˈæktɪv/","tag":"same stem, adjective","definition":"Describing a substance that reacts readily; it is a property, while reactant is a role in one reaction.","definitionCN":"形容容易起反应的物质；它是性质，而 reactant 是在某次反应中的角色。"},{"word":"reagent","ipa":"/riˈeɪdʒənt/","tag":"near form, different role","definition":"A substance added to bring about or detect a reaction; it is usually not the material being studied, which is exactly what a reactant is.","definitionCN":"为引起或检测反应而加入的物质；它通常不是被研究的材料，而反应物恰恰是被转化的那种。"}]},{"heading":"NEAR MEANING","entries":[{"word":"substrate","ipa":"/ˈsʌbstreɪt/","tag":"biological input","definition":"The molecule an enzyme acts on; it is the biochemical counterpart of a reactant.","definitionCN":"酶所作用的分子，是反应物在生物化学中的对应词。"},{"word":"educt","ipa":"/ɪˈdʌkt/","tag":"archaic synonym","definition":"An older chemistry term for a substance drawn out of another in a reaction; now largely replaced by reactant.","definitionCN":"较早的化学术语，指反应中由另一物生成或抽出的物质，如今多被 reactant 取代。"},{"word":"input","ipa":"/ˈɪnpʊt/","tag":"process word","definition":"Anything fed into a system; the general word for what reactant says in chemistry.","definitionCN":"送入系统的任何东西；是 reactant 在化学中所说的内容在一般语境中的说法。"},{"word":"feed","ipa":"/fiːd/","tag":"industrial word","definition":"The material stream charged into a plant unit; it stresses flow and quantity rather than chemical role.","definitionCN":"送入工厂单元的物料流；强调流动与数量，而非化学角色。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb, the real -ant pattern and real laboratory phrases.","cn":"正常联想：真实的拉丁动词、真实的 -ant 构词模式与真实的实验室说法。"},"normal":[{"en":"React plus -ant: the thing that does the reacting.","cn":"react 加 -ant：正在起反应的那个东西。"},{"en":"The family runs react, reaction, reactant, reactive, reactivity and reactor.","cn":"同族词有 react、reaction、reactant、reactive、reactivity 与 reactor。"},{"en":"Fixed phrases mark the laboratory: limiting reactant, excess reactant, reactant concentration.","cn":"固定搭配标出实验室语境：限量反应物、过量反应物、反应物浓度。"},{"en":"The word is the mirror image of product: what goes in against what comes out.","cn":"这个词与 product 互为镜像：进去的东西对出来的东西。"},{"en":"A reactant is spent; a catalyst is not, which is why the two are never interchangeable.","cn":"反应物会被消耗，催化剂不会，所以两者绝不能互换。"}],"abstract":[{"en":"Picture two runners who both start but only one finishes, the other having spent everything.","cn":"想象两位都起跑的跑者，只有一位到终点，另一位已把力气用尽。"},{"en":"Picture a recipe where the flour runs out first and stops the baking.","cn":"想象一份食谱，面粉最先用完，烘焙就此停下。"},{"en":"Picture a debate that consumes its own best arguments and ends with nothing left to say.","cn":"想象一场辩论，把自己最好的论据消耗殆尽，最后无话可说。"}]},"examples":[{"en":"In the flask, the two reactants meet only after the stopcock is opened.","cn":"在烧瓶里，两种反应物只在旋塞打开之后才相遇。"},{"en":"Raising the temperature makes the reactant molecules collide harder.","cn":"升高温度使反应物分子碰撞得更猛烈。"},{"en":"The plant recycles unreacted reactant to cut waste.","cn":"工厂回收未反应的反应物以减少浪费。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「react（反应）+ ant（东西）」——被反应消耗掉的那样东西 → 反应物","word":"reactant"},"root":"拉丁 agere「做、驱动」→ reagere「反过来行动」→ 英语 react「反应」→ 加 -ant（施动者后缀）→ reactant「反应物」；最早化学用例在 19 世纪，确切年份无定论。","sensesIntro":{"en":"Eight senses follow one role: a substance is spent in a change. The role then narrows to a single molecule, splits into the one that runs out and the one left over, moves into enzymes and factories, and finally becomes a metaphor for any consumed input.","cn":"八个义项沿同一个角色展开：某物质在一场变化中被消耗。这个角色随后收窄到单个分子，分成先耗尽的一种与剩下的另一种，再进入酶与工厂，最后成为任何被消耗输入的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: two labelled beakers poured into one vessel, the level rising as the colour begins to change.","cn":"核心意象：两只贴标签的烧杯倒进同一个容器，液面上升，颜色开始变化。"},"chain":["STARTING SUBSTANCE","CONSUMED INPUT","SINGLE MOLECULE","LIMITING PORTION","BIOLOGICAL SUBSTRATE","FIGURATIVE COST"],"branches":[{"senses":"01","en":"THE SPENT SUBSTANCE: what enters the reaction and does not come out unchanged.","cn":"被消耗的物质：进入反应、不会原样出来的那种东西。"},{"senses":"02 · 07","en":"THE PLANT SCALE: any consumed input, charged by the tonne into a reactor.","cn":"工厂尺度：任何被消耗的输入，以吨计装入反应器。"},{"senses":"03","en":"ONE PARTICLE: at molecular scale the word means a colliding unit, not a heap.","cn":"单个粒子：在分子尺度上，这个词指一个参与碰撞的单位，而不是一堆材料。"},{"senses":"04 · 05","en":"TWO PORTIONS: the one that runs out first and the one deliberately left over.","cn":"两份配比：先耗尽的一份，与故意留多的一份。"},{"senses":"06 · 08","en":"FROM ENZYME TO METAPHOR: a molecule handed to an enzyme, or any input a change spends.","cn":"从酶到比喻：交给酶的分子，或任何被变化消耗掉的输入。"}]},"affixes":{"intro":{"en":"Reactant shows the whole machinery in one word: a Latin prefix, a Latin verb stem and a Latin participle ending, all still readable.","cn":"reactant 在一个词里显示了整套构词机制：拉丁前缀、拉丁动词词干与拉丁分词词尾，都仍然可读。"},"latinIntro":{"en":"Latin agere and its participle actum give the stem, re- gives the sense of acting back, and -ant gives the doer.","cn":"拉丁语 agere 及其分词 actum 提供词干，re- 提供「反过来」的意思，-ant 提供施动者。"},"items":[{"word":"re-","structure":"re- (Latin prefix, back, again)","meaning":"back; in return","meaningCN":"向后；反过来","example":"The prefix adds the idea of acting in return.","exampleCN":"这个前缀加上「反过来行动」的意思。"},{"word":"agere","structure":"agere, egi, actum (Latin verb, third conjugation)","meaning":"to do, drive, set going","meaningCN":"做；驱动；使前进","example":"The verb supplies the bare idea of action.","exampleCN":"这个动词提供「行动」这一最单纯的意思。"},{"word":"reagere","structure":"re- plus agere","meaning":"to act back, respond","meaningCN":"反过来行动；回应","example":"The Latin verb is the direct source of react.","exampleCN":"这个拉丁动词是 react 的直接来源。"},{"word":"-ant","structure":"-ans, -antis (Latin present participle ending)","meaning":"the one doing the action","meaningCN":"执行动作的那一个","example":"The ending turns a verb into a noun of agent.","exampleCN":"这个词尾把动词变成施动名词。"},{"word":"reactant","structure":"react plus -ant","meaning":"a substance that reacts","meaningCN":"起反应的物质","example":"Oxygen is a reactant in rusting.","exampleCN":"氧气是生锈过程中的反应物。"},{"word":"react","structure":"re- plus act","meaning":"to respond or undergo a change","meaningCN":"作出回应；发生变化","example":"The two gases react at room temperature.","exampleCN":"这两种气体在室温下反应。"},{"word":"reaction","structure":"react plus -ion (process)","meaning":"the process of changing","meaningCN":"发生变化的过程","example":"The reaction releases heat.","exampleCN":"这个反应释放热量。"},{"word":"reactive","structure":"react plus -ive (tending to)","meaning":"ready to react","meaningCN":"容易起反应的","example":"Sodium is far more reactive than gold.","exampleCN":"钠比金活泼得多。"},{"word":"reactor","structure":"react plus -or (thing that acts)","meaning":"a vessel where a reaction runs","meaningCN":"进行反应的容器","example":"The reactor holds the mixture at high pressure.","exampleCN":"反应器在高压下容纳混合物。"},{"word":"reagent","structure":"re- plus agent (acting thing)","meaning":"a substance added to cause or detect a reaction","meaningCN":"为引起或检测反应而加入的物质","example":"A reagent tests for starch in the leaf.","exampleCN":"一种试剂用于检测叶片中的淀粉。"}],"latinEntries":[{"word":"agere","structure":"agere, egi, actum (verb, third conjugation)","meaning":"to do, drive, set in motion","meaningCN":"做；驱动；使动"},{"word":"actum","structure":"actum, acti (n., second declension)","meaning":"a deed; something done","meaningCN":"行为；所做的事"},{"word":"reagere","structure":"re- plus agere (verb, third conjugation)","meaning":"to act back, respond","meaningCN":"反过来行动；回应"}],"derivatives":[{"word":"react","pos":"v.","zh":"反应"},{"word":"reaction","pos":"n.","zh":"反应"},{"word":"reactive","pos":"adj.","zh":"易起反应的"},{"word":"reactivity","pos":"n.","zh":"反应性"},{"word":"reactor","pos":"n.","zh":"反应器"}]}},{"word":"product","ipa_uk":"/ˈprɒdʌkt/","ipa_us":"/ˈprɑːdʌkt/","definition_zh":"产品；产物；成果；（数学）乘积；（化学）生成物","definition_en":"something produced by a process, a reaction, a multiplication or human work","core_image":"流水线尽头，一只刚成型的物件被机械臂放进托盘，旁边堆着已经空了的料箱","scene":"流水线尽头，一只刚成型的物件被机械臂放进托盘，旁边堆着已经空了的料箱。Water is the product of the reaction between hydrogen and oxygen.","sceneCN":"这里 product 指化学反应生成的产物（第 1 个义项：反应结束后新生成的物质）；句意：水是氢与氧反应的生成物。图中可辨识物件：传送带、机械臂、托盘、空料箱。","pos":[{"tag":"n.","zh":"产品；产物；成果；乘积；生成物"}],"collocations":[{"phrase":"by-product","zh":"副产品"},{"phrase":"product line","zh":"产品线"},{"phrase":"final product","zh":"最终产品；成品"},{"phrase":"product quality","zh":"产品质量"},{"phrase":"reaction product","zh":"反应产物"},{"phrase":"product launch","zh":"产品发布"}],"forms":[{"label":"复数","form":"products"},{"label":"动词（生产）","form":"produce"},{"label":"名词（生产；产量）","form":"production"},{"label":"形容词（多产的；生产性的）","form":"productive"},{"label":"名词（生产者）","form":"producer"}],"derivatives":[{"word":"produce","pos":"v./n.","zh":"生产；农产品"},{"word":"production","pos":"n.","zh":"生产；产量；制作"},{"word":"productive","pos":"adj.","zh":"多产的；富有成效的"},{"word":"productivity","pos":"n.","zh":"生产率"},{"word":"producer","pos":"n.","zh":"生产者；制片人"}],"senses":[{"no":"01","title":"What a chemical reaction makes","titleCN":"化学反应生成的新物质","definition":"a substance formed when other substances react","definitionCN":"由其他物质发生反应后生成的新物质","example":"Water is the product of the reaction between hydrogen and oxygen.","exampleCN":"水是氢与氧反应的生成物。","why":"the word is the past participle of a Latin verb meaning to lead forth, so a product is literally what has been brought out of a process.","whyCN":"这个词是拉丁动词「引出」的过去分词，因此 product 字面就是「被过程带出来的东西」。"},{"no":"02","title":"A thing made for sale","titleCN":"为出售而制造的产品","definition":"an item manufactured or grown in order to be sold","definitionCN":"为出售而制造或种植的物品","example":"The company moved its best product to the front of the catalogue.","exampleCN":"公司把最好的产品移到目录前页。","why":"commerce narrowed the general sense of what is brought forth to what is brought forth for a buyer.","whyCN":"商业把「被带出来的东西」这一通义收窄为「为买家带出来的东西」。"},{"no":"03","title":"A result of effort","titleCN":"努力或过程的成果","definition":"an outcome of work, thinking or events, often abstract","definitionCN":"工作、思考或事件带来的结果，常为抽象之物","example":"The report was the product of three years of fieldwork.","exampleCN":"这份报告是三年野外工作的成果。","why":"if a process brings something out, anything brought out counts, including knowledge and institutions.","whyCN":"只要过程能带出东西，被带出的一切都算，包括知识与制度。"},{"no":"04","title":"The result of multiplication","titleCN":"乘法运算的结果","definition":"the number obtained by multiplying two or more numbers","definitionCN":"两个或多个数相乘所得的数","example":"The product of six and seven is forty-two.","exampleCN":"六与七的乘积是四十二。","why":"mathematics borrowed the same participle: multiplication brings forth a number from two others.","whyCN":"数学借用了同一个分词：乘法从两个数里带出一个数。"},{"no":"05","title":"A child of its time or place","titleCN":"时代或环境的产物","definition":"a person or thing shaped entirely by a particular background","definitionCN":"完全由某一背景塑造的人或事物","example":"He was a product of the same crowded schools he later criticized.","exampleCN":"他正是他后来批评的那种拥挤学校的产物。","why":"the metaphor says that circumstances manufacture people in the way a factory manufactures goods.","whyCN":"这个比喻说环境造人，正如工厂造货。"},{"no":"06","title":"Farm output","titleCN":"农产品","definition":"crops or other goods grown from the land, often in the plural","definitionCN":"地里种出的作物等物产，常用复数","example":"The market sells local products from the surrounding farms.","exampleCN":"这个市场出售周边农场的本地农产品。","why":"farming speaks of its output as produce, and the plural products marks things grown rather than made.","whyCN":"农业把自己的产出说成 produce，复数 products 标记的是种出来的东西，而非造出来的。"},{"no":"07","title":"A work of media or art","titleCN":"媒体或艺术作品的产物","definition":"a film, recording or other creative work considered as an item made by a studio","definitionCN":"被视为由制片机构制作的电影、录音等创作成品","example":"The studio treats every film as a product with a release date.","exampleCN":"制片方把每部电影都当作有发行日期的产品。","why":"the entertainment industry uses the commercial sense of the word, so a film becomes a product beside toys and tickets.","whyCN":"娱乐业使用这个词的商业义，于是电影与玩具、门票并列成为产品。"},{"no":"08","title":"One item in a brand range","titleCN":"品牌系列中的单个品项","definition":"a single item within a company's range, tracked separately in sales and marketing","definitionCN":"公司系列中的单个品项，在销售与营销中单独核算","example":"Each product in the range has its own price and its own page.","exampleCN":"系列中的每个产品都有自己的价格与页面。","why":"marketing splits a range into countable units, and the word becomes the unit of accounting rather than the whole output.","whyCN":"营销把一个系列拆成可数的单位，这个词于是成为核算单位，而不是全部产出。"}],"etymology":{"intro":{"en":"Product comes from Latin productum, the neuter past participle of producere, to lead forth, built on pro-, forward, and ducere, to lead. It entered English in the sixteenth century. Dates are approximate.","cn":"product 出自拉丁语 productum，即 producere「引出」的中性过去分词；该动词由 pro-「向前」与 ducere「引导」构成。它在 16 世纪进入英语。年代均为约数。"},"items":[{"era":"LATIN DUCERE","en":"Ducere meant to lead, draw or guide; its past participle ductum supplied a long series of English words. The deeper Indo-European root is a reconstruction.","cn":"ducere 意为「引导、拉、带领」，其过去分词 ductum 提供了一长串英语词。更早的印欧词根属于重构。"},{"era":"LATIN PRODUCERE","en":"Pro-, forward, plus ducere produced producere, to lead forth, bring out, extend, which is the source of produce, product and production.","cn":"pro-「向前」加 ducere 构成 producere「引出、带出、延长」，是 produce、product 与 production 的来源。"},{"era":"LATIN PRODUCTUM","en":"The neuter participle productum came to be used as a noun for something brought out or brought forth, the direct model of the English word.","cn":"中性分词 productum 被当作名词使用，指被带出、被产生的东西，是英语词的直接样板。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"Product entered English in the sixteenth century, first as a general word for a result and also as the mathematical term for the result of multiplication.","cn":"product 于 16 世纪进入英语，最初泛指结果，同时也是表示乘法结果的数学术语。"},{"era":"INDUSTRIAL SENSE","en":"From the nineteenth century the commercial sense of a manufactured item for sale became dominant, and the plural products spread into farming and marketing.","cn":"从 19 世纪起，指供出售的制成品这一商业义占据主导，复数形式 products 又扩散到农业与营销。"},{"era":"FIRST DATE","en":"First date uncertain: the century of entry is well attested, but the earliest citation of the commercial sense is not settled, so the date given for that sense is approximate.","cn":"首见年代不确定：进入英语的世纪有可靠记载，但商业义的最早书证尚无定论，因此为该义给出的年代只是约数。"}]},"similar":{"note":{"en":"The first group shares the produce stem; the second group names other results and other stages of making something.","cn":"第一组共享 produce 词干；第二组是其他表示结果或制作阶段的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"produce","ipa":"/prəˈdjuːs/","tag":"same stem, verb","definition":"The verb meaning to bring forth; its noun form, pronounced differently, means fresh farm goods as a mass.","definitionCN":"意为「产生、生产」的动词；其名词形式读音不同，指作为整体的新鲜农产品。"},{"word":"production","ipa":"/prəˈdʌkʃn/","tag":"same stem, process","definition":"The activity or amount of making things; a product is the thing, production is the making of it.","definitionCN":"指制作活动或产量；product 是物，production 是制作这件事。"},{"word":"by-product","ipa":"/ˈbaɪprɒdʌkt/","tag":"secondary output","definition":"Something made incidentally while the main product is being made; it is not the intended output.","definitionCN":"在制造主要产品时顺带产生的东西，不是有意要的产出。"},{"word":"producer","ipa":"/prəˈdjuːsə/","tag":"same stem, person","definition":"The person or firm that makes the product; the -er ending marks the maker rather than the made.","definitionCN":"制作产品的人或公司；词尾 -er 标记制作者，而不是被制作之物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"result","ipa":"/rɪˈzʌlt/","tag":"general outcome","definition":"The general word for what follows from something; it does not imply that the thing was made or sold.","definitionCN":"泛指由某事带来的结果；不含「被制造或被出售」的意思。"},{"word":"output","ipa":"/ˈaʊtpʊt/","tag":"quantity produced","definition":"What a system turns out, often measured as a rate or total; it stresses quantity more than the item itself.","definitionCN":"系统产出的东西，常以速率或总量计量；强调数量多过单件物品。"},{"word":"yield","ipa":"/jiːld/","tag":"amount obtained","definition":"The amount obtained from a process, especially a reaction or a field; chemistry counts yield, not products alone.","definitionCN":"从过程得到的量，尤指反应或田地；化学算的是收率，而不只是产物本身。"},{"word":"goods","ipa":"/ɡʊdz/","tag":"saleable items","definition":"Movable items for sale, always plural; it is a commercial collective, while product can name one item.","definitionCN":"可供出售的动产，总用复数；它是商业集合名词，而 product 可以指单件。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb, the real word family and real commercial phrases.","cn":"正常联想：真实的拉丁动词、真实的同族词与真实的商业说法。"},"normal":[{"en":"Pro- forward plus ducere to lead: to lead something out of a process.","cn":"pro-「向前」加 ducere「引导」：把某物从过程中引出来。"},{"en":"The family runs produce, product, production, productive, productivity and producer.","cn":"同族词有 produce、product、production、productive、productivity 与 producer。"},{"en":"Fixed phrases mark the commercial sense: product line, product launch, final product.","cn":"固定搭配标出商业义：产品线、产品发布、成品。"},{"en":"The same word serves the reaction and the multiplication, which is why chemistry and arithmetic share it.","cn":"同一个词既服务反应也服务乘法，所以化学与算术共用它。"},{"en":"Product and by-product differ by one prefix: the second is what came out although nobody planned it.","cn":"product 与 by-product 只差一个前缀：后者是没人计划却照样出来的东西。"}],"abstract":[{"en":"Picture a conveyor belt that ends exactly where the empty crates begin.","cn":"想象一条传送带的终点，正好是空料箱开始的地方。"},{"en":"Picture a child who repeats the habits of a school he later argues against.","cn":"想象一个孩子，重复着他后来反对的那所学校的习惯。"},{"en":"Picture two numbers meeting and leaving one number behind.","cn":"想象两个数相遇，留下一个数。"}]},"examples":[{"en":"The reaction produces a gas as its main product.","cn":"这个反应的主要产物是一种气体。"},{"en":"A product that nobody can repair will not keep its buyers.","cn":"无人能修的产品留不住买家。"},{"en":"The product of the two lengths gives the area of the rectangle.","cn":"两条边的乘积给出矩形的面积。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pro（向前）+ duct（引导）」——把东西往前带出来的结果 → 产品、产物","word":"product"},"root":"拉丁 ducere「引导」→ pro- 加 ducere 成 producere「引出」→ 过去分词 productum → 英语 product「被带出的东西」；16 世纪进入英语，商业义确切首见年代无定论。","sensesIntro":{"en":"Eight senses follow one act: something is led out of a process. The act then serves a reaction, a factory, a piece of work, a multiplication, a whole era, a farm, a studio and finally one shelf item.","cn":"八个义项沿同一个动作展开：某物被从过程中引出来。这个动作随后服务于反应、工厂、一项工作、一次乘法、一个时代、一片农田、一家制片机构，最后是货架上的一个单品。"},"semanticMap":{"core":{"en":"CORE IMAGE: the end of a conveyor belt where a finished object drops into a tray beside empty crates.","cn":"核心意象：传送带的尽头，一件成品落进托盘，旁边是空了的料箱。"},"chain":["BROUGHT FORTH","CHEMICAL PRODUCT","GOODS FOR SALE","RESULT OF WORK","MULTIPLICATION","SHAPED BY CIRCUMSTANCES"],"branches":[{"senses":"01","en":"THE REACTION OUTPUT: a new substance appears where two others met.","cn":"反应产出：两种物质相遇之处出现一种新物质。"},{"senses":"02 · 08","en":"THE SHELF: a made item, and then one countable item inside a range.","cn":"货架：一件制成品，再细化为系列中可数的一个单品。"},{"senses":"03 · 07","en":"WORK AND MEDIA: knowledge, reports and films are brought out like goods.","cn":"劳动与媒体：知识、报告与影片也像货物一样被带出来。"},{"senses":"04","en":"ARITHMETIC: multiplication brings one number out of two.","cn":"算术：乘法从两个数里带出一个数。"},{"senses":"05 · 06","en":"WHAT GROWS OR SHAPES: crops grown from land, and people shaped by their time.","cn":"长成或被塑造之物：田里长出的作物，与被时代塑造的人。"}]},"affixes":{"intro":{"en":"Product is a Latin participle turned noun, and its prefix and verb stem still build a large English family.","cn":"product 是拉丁分词转成的名词，其前缀与动词词干仍在构建一个庞大的英语词族。"},"latinIntro":{"en":"Latin producere and productum supply the stem, and ducere supplies a whole series of English verbs through its participle ductum.","cn":"拉丁语 producere 与 productum 提供词干，ducere 则通过其分词 ductum 提供了一整串英语动词。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, forward, forth)","meaning":"forward; out","meaningCN":"向前；向外","example":"The prefix adds the idea of bringing something out.","exampleCN":"这个前缀加上「把某物带出来」的意思。"},{"word":"ducere","structure":"ducere, duxi, ductum (Latin verb, third conjugation)","meaning":"to lead, draw, guide","meaningCN":"引导；拉；带领","example":"The verb supplies the idea of leading.","exampleCN":"这个动词提供「引导」的意思。"},{"word":"producere","structure":"pro- plus ducere","meaning":"to lead forth, bring out","meaningCN":"引出；带出","example":"The Latin verb is the source of the whole family.","exampleCN":"这个拉丁动词是整个词族的来源。"},{"word":"productum","structure":"neuter past participle of producere","meaning":"something brought forth","meaningCN":"被带出之物","example":"The participle became a noun in its own right.","exampleCN":"这个分词本身变成了名词。"},{"word":"product","structure":"productum through Latin and French","meaning":"a thing produced","meaningCN":"被产生的东西","example":"Water is the product of the reaction.","exampleCN":"水是这个反应的产物。"},{"word":"produce","structure":"pro- plus ducere, as a verb","meaning":"to bring forth","meaningCN":"产生；生产","example":"The factory produces parts for bicycles.","exampleCN":"这家工厂生产自行车零件。"},{"word":"production","structure":"produce plus -tion (process)","meaning":"the making of something","meaningCN":"制造某物的过程","example":"Production rose after the line was rebuilt.","exampleCN":"生产线改建后产量上升。"},{"word":"productive","structure":"produce plus -ive (tending to)","meaning":"yielding much","meaningCN":"富有产出的","example":"The meeting was short and productive.","exampleCN":"这次会议简短而有成效。"},{"word":"by-product","structure":"by- (secondary) plus product","meaning":"an incidental output","meaningCN":"顺带产生的产出","example":"Heat is a by-product of the reaction.","exampleCN":"热是这个反应的副产品。"},{"word":"producer","structure":"produce plus -er (person or thing)","meaning":"one that produces","meaningCN":"生产的人或物","example":"The producer financed the whole shoot.","exampleCN":"制片人资助了整次拍摄。"}],"latinEntries":[{"word":"ducere","structure":"ducere, duxi, ductum (verb, third conjugation)","meaning":"to lead, draw","meaningCN":"引导；拉"},{"word":"producere","structure":"pro- plus ducere (verb, third conjugation)","meaning":"to lead forth, bring out","meaningCN":"引出；带出"},{"word":"productum","structure":"productum, producti (n., second declension)","meaning":"something brought forth","meaningCN":"被带出之物"}],"derivatives":[{"word":"produce","pos":"v./n.","zh":"生产；农产品"},{"word":"production","pos":"n.","zh":"生产；产量"},{"word":"productive","pos":"adj.","zh":"多产的；有成效的"},{"word":"productivity","pos":"n.","zh":"生产率"},{"word":"producer","pos":"n.","zh":"生产者；制片人"}]}},{"word":"catalysis","ipa_uk":"/kəˈtæləsɪs/","ipa_us":"/kəˈtæləsɪs/","definition_zh":"催化作用；催化；促成变化的中介力量","definition_en":"the process by which a substance speeds up a reaction while itself remaining unchanged","core_image":"一条陡峭的山路旁多出一条平缓隧道，走路的人还是那些人，路却通了","scene":"一条陡峭的山路旁多出一条平缓隧道，走路的人还是那些人，路却通了。A trace of platinum speeds up the reaction through catalysis.","sceneCN":"这里 catalysis 指催化剂加快反应而自身不被消耗的作用（第 1 个义项：降低反应阻力、加快反应速度的过程）；句意：微量铂通过催化作用加快了反应。图中可辨识物件：陡坡、隧道口、行走的人、路面标线。","pos":[{"tag":"n.","zh":"催化作用；催化"}],"collocations":[{"phrase":"heterogeneous catalysis","zh":"多相催化"},{"phrase":"homogeneous catalysis","zh":"均相催化"},{"phrase":"enzyme catalysis","zh":"酶催化"},{"phrase":"industrial catalysis","zh":"工业催化"},{"phrase":"catalysis research","zh":"催化研究"},{"phrase":"photocatalysis","zh":"光催化"}],"forms":[{"label":"复数","form":"catalyses"},{"label":"形容词（催化的）","form":"catalytic"},{"label":"动词（催化）","form":"catalyse"},{"label":"动词（美式拼写）","form":"catalyze"},{"label":"名词（催化剂）","form":"catalyst"}],"derivatives":[{"word":"catalyst","pos":"n.","zh":"催化剂；促变因素"},{"word":"catalytic","pos":"adj.","zh":"催化的"},{"word":"catalyse","pos":"v.","zh":"催化；促成"},{"word":"autocatalysis","pos":"n.","zh":"自催化"},{"word":"photocatalysis","pos":"n.","zh":"光催化"}],"senses":[{"no":"01","title":"Speeding a reaction without being consumed","titleCN":"不消耗自身而加快反应","definition":"the chemical process in which a substance lowers the barrier to a reaction and is recovered unchanged","definitionCN":"某种物质降低反应阻力、自身却在反应后原样回收的化学过程","example":"A trace of platinum speeds up the reaction through catalysis.","exampleCN":"微量铂通过催化作用加快了反应。","why":"the Greek word meant a loosening or dissolving, and chemistry borrowed that image for the removal of a barrier that held the reaction back.","whyCN":"这个希腊词原意是「松开、化解」，化学借这个意象表示移除挡住反应的那道障碍。"},{"no":"02","title":"Catalysis inside a living cell","titleCN":"活细胞内的催化","definition":"the same speeding-up performed by enzymes on biological molecules","definitionCN":"由酶对生物分子执行的同类加速作用","example":"Enzyme catalysis lets a cell break down sugar at body temperature.","exampleCN":"酶催化让细胞在体温下分解糖。","why":"enzymes do exactly what metal catalysts do, only more precisely, so biology uses the same noun for the process.","whyCN":"酶做的事与金属催化剂完全相同，只是更精准，因此生物学用同一个名词指这一过程。"},{"no":"03","title":"Catalysis as an industrial process","titleCN":"作为工业工艺的催化","definition":"the use of catalysts on a plant scale to make fuels, fertiliser or plastics","definitionCN":"在工厂规模上使用催化剂来生产燃料、肥料或塑料","example":"Industrial catalysis turns most of the world's ammonia into fertiliser.","exampleCN":"工业催化把世界上大部分氨变成肥料。","why":"when the process leaves the flask for a reactor, the noun shifts from a mechanism to a production method.","whyCN":"当这一过程离开烧瓶进入反应器，这个名词便从机理转为生产方法。"},{"no":"04","title":"The field that studies catalysts","titleCN":"研究催化剂的学科领域","definition":"the branch of chemistry concerned with how catalysts work and how to design them","definitionCN":"研究催化剂如何工作、如何设计的化学分支","example":"Catalysis is now a field with its own journals and its own methods.","exampleCN":"催化如今是一个有自己的期刊与方法的领域。","why":"any named process can become a discipline, and this noun did: the study is called by the process it studies.","whyCN":"任何有名字的过程都能成为一门学科，这个名词确实如此：研究以它所研究的过程命名。"},{"no":"05","title":"A force that makes change easier","titleCN":"使变化更易发生的中介力量","definition":"figuratively, any agent that lowers the resistance to a change without being used up","definitionCN":"比喻用法，指降低变化阻力、自身却不被耗尽的任何因素","example":"The report acted as catalysis for a reform nobody had dared to start.","exampleCN":"这份报告成了那场无人敢启动的改革的催化。","why":"the metaphor keeps the whole structure of the chemical idea: a small input, no consumption, a large change.","whyCN":"这个比喻保留了化学概念的整体结构：输入很小、不被消耗、变化很大。"},{"no":"06","title":"Catalysis of social change","titleCN":"社会变革中的催化","definition":"the role of an event or group that sets a wider movement going","definitionCN":"某一事件或群体促使更大规模运动启动的角色","example":"Historians describe the strike as catalysis rather than cause.","exampleCN":"历史学家把那次罢工描述为催化，而不是原因。","why":"commentary borrows the word to separate a trigger from a cause, just as a catalyst is not a reactant.","whyCN":"评论文字借这个词把「触发」与「原因」区分开，正如催化剂不是反应物。"},{"no":"07","title":"Autocatalysis","titleCN":"自催化","definition":"the special case in which a product of the reaction itself acts as the catalyst","definitionCN":"反应产物本身充当催化剂这一特殊情形","example":"Autocatalysis makes the reaction accelerate as it proceeds.","exampleCN":"自催化使反应随着进行而不断加速。","why":"chemistry needed a short name for the loop where output feeds back as input, and built it on catalysis.","whyCN":"化学需要给「产出回喂输入」的回路一个短名字，于是以 catalysis 为基础造词。"},{"no":"08","title":"Light-driven catalysis","titleCN":"光驱动的催化","definition":"catalysis in which light supplies the energy that drives the reaction","definitionCN":"由光提供能量、推动反应的催化","example":"Photocatalysis on a titanium surface splits water into its gases.","exampleCN":"钛表面上的光催化把水分解成两种气体。","why":"when the energy source rather than the catalyst is the new element, the compound name marks the difference.","whyCN":"当新的要素是能量来源而不是催化剂时，复合名称便标记出这一区别。"}],"etymology":{"intro":{"en":"Catalysis is Greek: katalysis meant a dissolving or loosening, from katalyein, to dissolve, built on kata-, down, and lyein, to loosen. Berzelius gave it its chemical sense in 1835. Dates are approximate.","cn":"catalysis 是希腊语：katalysis 意为「化解、松开」，出自 katalyein「使化解」，由 kata-「向下」与 lyein「松开」构成。贝采利乌斯在 1835 年赋予它化学义。年代均为约数。"},"items":[{"era":"GREEK LYEIN","en":"Lyein meant to loosen, release, dissolve. Its earlier Indo-European connections are reconstructions, and the form usually cited for it is not attested in any written language.","cn":"lyein 意为「松开、释放、化解」。它更早的印欧语联系属于重构，通常引用的形式在任何有文字的语言中都没有记录。"},{"era":"GREEK KATALYEIN","en":"Kata-, down, plus lyein produced katalyein, to dissolve or break up, used of a body losing its cohesion and of an army disbanding.","cn":"kata-「向下」加 lyein 构成 katalyein「化解、分解」，可用于物体失去结合，也可用于军队解散。"},{"era":"GREEK KATALYSIS","en":"The noun katalysis named a dissolving or a release, and in later Greek also a means of ending something; it carried no chemical sense.","cn":"名词 katalysis 指「化解、释放」，在后来的希腊语中也指结束某事的手段；它并无化学含义。"},{"era":"BERZELIUS 1835","en":"Jöns Jacob Berzelius introduced catalysis for the strange power by which certain substances set reactions going without taking part in them.","cn":"贝采利乌斯引入 catalysis，指某些物质推动反应却不参与其中的那种奇特能力。"},{"era":"ENZYMES AND INDUSTRY","en":"Nineteenth-century fermentation studies and twentieth-century chemical plants extended the word to enzymes and to reactors alike.","cn":"19 世纪的发酵研究与 20 世纪的化工厂把这个词同时扩展到酶与反应器。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (deeper origin): the pre-Greek history of lyein is unsettled, and the reconstructed Indo-European root offered for it is a hypothesis rather than a demonstrated form.","cn":"来源不确定（更深源头）：lyein 在希腊语之前的历史没有定论，为它提出的重构印欧词根只是假说，并非已证实的形式。"}]},"similar":{"note":{"en":"The first group is the same Greek stem in its other shapes, easily confused in writing; the second group names neighbouring ways of making a process go faster.","cn":"第一组是同一希腊词干的其他形态，在写作中极易混淆；第二组是意思相邻的「让过程加快」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"catalyst","ipa":"/ˈkætəlɪst/","tag":"same stem, agent","definition":"The substance that performs catalysis; the -yst ending marks the agent, not the process.","definitionCN":"执行催化作用的物质；词尾标出施动者，而不是过程。"},{"word":"catalytic","ipa":"/ˌkætəˈlɪtɪk/","tag":"same stem, adjective","definition":"The adjective describing anything that works by catalysis, as a converter or a cracker.","definitionCN":"形容词，描述任何以催化方式工作的东西，如转化器或裂化装置。"},{"word":"catalyse","ipa":"/ˈkætəlaɪz/","tag":"same stem, verb","definition":"The verb meaning to bring catalysis about; American spelling uses -yze.","definitionCN":"表示「使发生催化」的动词；美式拼写用 -yze。"},{"word":"autocatalysis","ipa":"/ˌɔːtəʊkəˈtæləsɪs/","tag":"same stem, compound","definition":"A loop within catalysis where the product is its own catalyst; it is a special case, not a synonym.","definitionCN":"催化内部的一种回路，产物自己充当催化剂；它是特例，不是同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"activation","ipa":"/ˌæktɪˈveɪʃn/","tag":"starting a process","definition":"The act of making something ready to react; catalysis lowers the energy needed, while activation supplies it.","definitionCN":"使某物进入可反应状态；催化降低所需能量，活化则提供能量。"},{"word":"acceleration","ipa":"/ˌæsəˈreɪʃn/","tag":"getting faster","definition":"A general word for speeding up; it says nothing about a catalyst or about being recovered unchanged.","definitionCN":"泛指加快；不涉及催化剂，也不涉及反应后原样回收。"},{"word":"promotion","ipa":"/prəˈməʊʃn/","tag":"industrial usage","definition":"In catalysis research, promotion is the boosting of a catalyst by a small added substance, not catalysis itself.","definitionCN":"在催化研究中，助催是少量添加物提升催化剂效果，并非催化本身。"},{"word":"facilitation","ipa":"/ˌfæsɪlɪˈteɪʃn/","tag":"general help","definition":"Making an outcome easier without doing the work; close to the figurative sense of catalysis but without the chemistry.","definitionCN":"使结果更容易达成而不亲自去做；接近催化的比喻义，但没有化学内容。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek root, the real word family and real laboratory phrases.","cn":"正常联想：真实的希腊词根、真实的同族词与真实的实验室说法。"},"normal":[{"en":"Kata- down plus lyein to loosen: the barrier is loosened, so the reaction runs.","cn":"kata-「向下」加 lyein「松开」：障碍被松开，反应就跑起来。"},{"en":"The family runs catalysis, catalyst, catalytic, catalyse and autocatalysis.","cn":"同族词有 catalysis、catalyst、catalytic、catalyse 与 autocatalysis。"},{"en":"Fixed phrases mark the branch: heterogeneous catalysis, enzyme catalysis, industrial catalysis.","cn":"固定搭配标出分支：多相催化、酶催化、工业催化。"},{"en":"The catalyst is never the reactant: it goes in and comes out, which is the whole point of the word.","cn":"催化剂从来不是反应物：它进去又出来，这正是这个词的全部要点。"},{"en":"The 1835 date belongs to Berzelius, who gave an old Greek noun its modern chemical job.","cn":"1835 年这个年份属于贝采利乌斯，是他让一个古老的希腊名词承担了现代化学的职务。"}],"abstract":[{"en":"Picture a tunnel that shortens a mountain without moving any of the rock.","cn":"想象一条隧道缩短了一座山，却没有搬走任何一块岩石。"},{"en":"Picture a match that lights a whole field and is not burned itself.","cn":"想象一根火柴点亮整片田野，自己却没有被烧掉。"},{"en":"Picture a stranger who opens a locked door and walks away before anyone enters.","cn":"想象一个陌生人打开一扇锁着的门，在任何人进去之前就走了。"}]},"examples":[{"en":"Catalysis by an acid can turn alcohol into ether at moderate heat.","cn":"酸催化可以在中等温度下把醇变成醚。"},{"en":"The plant doubled its output by improving catalysis rather than buying new reactors.","cn":"工厂靠改进催化而非购置新反应器使产量翻倍。"},{"en":"The discovery acted as catalysis for an entire branch of chemistry.","cn":"这一发现成了整个化学分支的催化。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cata（向下）+ lysis（松开）」——把阻力松下来，反应就快了 → 催化作用","word":"catalysis"},"root":"希腊 kata-「向下」+ lyein「松开」→ katalysis「化解、松开」→ 1835 年贝采利乌斯用作化学术语 catalysis；lyein 的更早来源无定论。","sensesIntro":{"en":"Eight senses follow one act: a barrier is lowered and a process runs faster without the helper being used up. The act then enters cells, factories, a research field, social commentary, a feedback loop and a light-driven variant.","cn":"八个义项沿同一个动作展开：障碍被降低，过程加快，而帮手并未被消耗。这个动作随后进入细胞、工厂、研究领域、社会评论、反馈回路，以及一种由光驱动的变体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tunnel opened beside a steep road, with the same walkers arriving sooner.","cn":"核心意象：陡路旁开出一条隧道，还是那些人，却更早到达。"},"chain":["LOWER THE BARRIER","FASTER REACTION","ENZYME","PLANT SCALE","FIELD OF STUDY","SOCIAL TRIGGER"],"branches":[{"senses":"01","en":"THE MECHANISM: a barrier falls and the same reaction needs less energy.","cn":"机理：障碍落下，同一个反应所需能量变少。"},{"senses":"02","en":"THE CELL: enzymes perform the same trick at body temperature.","cn":"细胞：酶在体温下做同一套把戏。"},{"senses":"03 · 04","en":"FROM PLANT TO DISCIPLINE: what works in a reactor becomes a field with its own journals.","cn":"从工厂到学科：在反应器里奏效的事，变成有自己期刊的领域。"},{"senses":"05 · 06","en":"THE METAPHOR: a small trigger that is not spent and starts a large change.","cn":"比喻：一个不被消耗的小小触发，启动一场大变化。"},{"senses":"07 · 08","en":"VARIETIES: the product that catalyses itself, and light that pays the energy bill.","cn":"变体：催化自身的产物，以及替能量买单的光。"}]},"affixes":{"intro":{"en":"Catalysis is built from a Greek prefix and a Greek verb, with a Greek noun ending; the modern chemical compounds add Latin and English pieces on top.","cn":"catalysis 由希腊前缀、希腊动词与希腊名词词尾构成；现代化学的复合词又在其上叠加拉丁语与英语成分。"},"latinIntro":{"en":"This word is entirely Greek; the Latin-looking forms in the family come through scientific Latin, which simply transliterated the Greek pieces.","cn":"这个词完全是希腊语；词族中看似拉丁的形式都经科学拉丁语转写而来，实际只是把希腊成分音译。"},"items":[{"word":"kata-","structure":"kata- (Greek prefix, down, throughout)","meaning":"down; thoroughly","meaningCN":"向下；彻底","example":"The prefix gives the sense of a downward loosening.","exampleCN":"这个前缀给出「向下松开」的意思。"},{"word":"lyein","structure":"lyein (Greek verb, to loosen)","meaning":"to loosen, release, dissolve","meaningCN":"松开；释放；化解","example":"The verb supplies the image of a bond coming apart.","exampleCN":"这个动词提供「结合被拆开」的意象。"},{"word":"katalyein","structure":"kata- plus lyein","meaning":"to dissolve, break up","meaningCN":"化解；分解","example":"Greek used it of bodies and of disbanded troops.","exampleCN":"希腊语用它指物体分解，也指军队解散。"},{"word":"-sis","structure":"-sis (Greek noun ending of a process)","meaning":"the process of","meaningCN":"……的过程","example":"The ending turns the verb into the name of a process.","exampleCN":"这个词尾把动词变成过程名称。"},{"word":"catalysis","structure":"katalyein plus -sis","meaning":"a loosening; later, chemical catalysis","meaningCN":"松开；后指化学催化","example":"Catalysis leaves the catalyst unchanged.","exampleCN":"催化作用使催化剂本身保持不变。"},{"word":"catalyst","structure":"catalysis reshaped with -yst (agent)","meaning":"the substance that catalyses","meaningCN":"起催化作用的物质","example":"The catalyst is recovered at the end of the run.","exampleCN":"催化剂在运行结束时被回收。"},{"word":"catalytic","structure":"catalyst plus -ic (relating to)","meaning":"working by catalysis","meaningCN":"以催化方式工作的","example":"A catalytic converter cleans the exhaust.","exampleCN":"催化转化器净化尾气。"},{"word":"catalyse","structure":"back-formed verb from catalysis","meaning":"to bring catalysis about","meaningCN":"使发生催化","example":"The enzyme catalyses the breakdown of starch.","exampleCN":"这种酶催化淀粉的分解。"},{"word":"autocatalysis","structure":"auto- (self) plus catalysis","meaning":"catalysis by the product itself","meaningCN":"由产物自身进行的催化","example":"Autocatalysis can make a reaction run away.","exampleCN":"自催化可能让反应失控加速。"},{"word":"photocatalysis","structure":"photo- (light) plus catalysis","meaning":"catalysis driven by light","meaningCN":"由光驱动的催化","example":"Photocatalysis needs a surface that absorbs light.","exampleCN":"光催化需要能吸光的表面。"}],"latinEntries":[{"word":"catalysis","structure":"catalysis, catalysis (f., Greek loan in scientific Latin)","meaning":"a dissolving; chemical catalysis","meaningCN":"化解；化学催化"},{"word":"catalystus","structure":"catalystus, catalysti (m., modern scientific Latin)","meaning":"a catalyst","meaningCN":"催化剂"}],"derivatives":[{"word":"catalyst","pos":"n.","zh":"催化剂；促变因素"},{"word":"catalytic","pos":"adj.","zh":"催化的"},{"word":"catalyse","pos":"v.","zh":"催化"},{"word":"autocatalysis","pos":"n.","zh":"自催化"},{"word":"photocatalysis","pos":"n.","zh":"光催化"}]}},{"word":"elemental","ipa_uk":"/ˌelɪˈmentl/","ipa_us":"/ˌelɪˈmentl/","definition_zh":"元素的；基本的；自然力般的；原始的","definition_en":"relating to a chemical element, or to basic and powerful forces of nature","core_image":"一堆杂物被拆到只剩四块最基本的积木，其余全都可以由它们再拼出来","scene":"风从山口灌进来，院墙外的树被连根拔起。Wind and rain are elemental forces that no wall can stop.","sceneCN":"这里 elemental 指自然力般的、狂暴而不可挡的（第 3 个义项：如自然元素之力那样强大）；句意：风与雨是任何墙都挡不住的自然之力。图中可辨识物件：山口、被吹倒的树、断裂的院墙、飞散的枝叶。","pos":[{"tag":"adj.","zh":"元素的；基本的；自然力般的；原始的"}],"collocations":[{"phrase":"elemental analysis","zh":"元素分析"},{"phrase":"elemental composition","zh":"元素组成"},{"phrase":"elemental forces","zh":"自然之力"},{"phrase":"elemental fury","zh":"自然力般的狂暴"},{"phrase":"elemental truth","zh":"根本的道理"},{"phrase":"elemental units","zh":"基本单元"}],"forms":[{"label":"原级","form":"elemental"},{"label":"比较级","form":"more elemental"},{"label":"最高级","form":"most elemental"},{"label":"副词","form":"elementally"},{"label":"名词（元素；要素）","form":"element"}],"derivatives":[{"word":"element","pos":"n.","zh":"元素；要素；成分"},{"word":"elementary","pos":"adj.","zh":"基础的；初级的"},{"word":"elementally","pos":"adv.","zh":"在基本层面；以自然力方式"},{"word":"elementalist","pos":"n.","zh":"元素论者；自然力艺术创作者"},{"word":"elements","pos":"n.","zh":"诸元素；基础知识"}],"senses":[{"no":"01","title":"Relating to a chemical element","titleCN":"与化学元素有关的","definition":"concerning a chemical element or the elements that a substance contains","definitionCN":"关于化学元素，或关于某物质所含各元素的","example":"Elemental analysis showed that the sample was almost pure carbon.","exampleCN":"元素分析显示这个样品几乎是纯碳。","why":"the adjective simply attaches the noun element to a method or a result, with no figurative colour at all.","whyCN":"这个形容词只是把名词「元素」接到方法或结果上，完全没有比喻色彩。"},{"no":"02","title":"Basic and fundamental","titleCN":"基本而根本的","definition":"forming the simplest necessary part of something, beyond which one cannot go","definitionCN":"构成某物最简单而必要的部分，再不能往下拆","example":"The report reduced the problem to a few elemental facts.","exampleCN":"报告把问题归结为几条根本事实。","why":"an element is a first principle, so what cannot be reduced further is naturally called elemental.","whyCN":"元素即是第一原理，因此不能再往下拆的东西自然被称为「基本的」。"},{"no":"03","title":"Like a force of nature","titleCN":"自然力般的","definition":"as powerful and unstoppable as wind, water, fire or earth","definitionCN":"像风、水、火、土那样强大而不可阻挡","example":"Wind and rain are elemental forces that no wall can stop.","exampleCN":"风与雨是任何墙都挡不住的自然之力。","why":"the ancient four elements were believed to underlie all matter, so a force that feels older than buildings is called elemental.","whyCN":"古代认为四种元素构成万物，因此那种比建筑更古老的力量被称为「元素般的」。"},{"no":"04","title":"Rough and primitive","titleCN":"粗陋原始的","definition":"simple to the point of crudeness, stripped of comfort or refinement","definitionCN":"简单到粗陋，毫无舒适或精致可言","example":"The shelter was elemental: four posts, a roof and a fire.","exampleCN":"那处居所极其原始：四根柱子、一个顶、一堆火。","why":"if only the basic elements remain, nothing has been added for comfort, and the adjective records that bareness.","whyCN":"若只剩最基本的要素，就没有为舒适添加任何东西，这个形容词记录的正是这种裸露。"},{"no":"05","title":"Of the four-element theory","titleCN":"四元素说的","definition":"belonging to the old theory that all matter is made of earth, water, air and fire","definitionCN":"属于「万物由土、水、气、火构成」这一旧理论的","example":"Elemental theory explained burning as the release of fire from wood.","exampleCN":"四元素说把燃烧解释为火从木头中释放。","why":"before modern chemistry, element meant one of four substances, and the adjective still labels that system.","whyCN":"在现代化学之前，元素指四种物质之一，这个形容词仍用来标记那套体系。"},{"no":"06","title":"Serving as a basic unit","titleCN":"作为基本单元的","definition":"describing the smallest units out of which a larger whole is built","definitionCN":"指构成更大整体的最小单元","example":"The model treats families as elemental units of the settlement.","exampleCN":"该模型把家庭当作聚落的基本单元。","why":"the word keeps the image of building blocks: whatever cannot be split further serves as an elemental part.","whyCN":"这个词保留「积木」的意象：凡是不能再拆的东西，就充当基本部件。"},{"no":"07","title":"At the level of basic skills","titleCN":"基础技能层面的","definition":"belonging to the first, simplest layer of a skill or subject","definitionCN":"属于某项技能或学科最初、最简单的层次","example":"The course covers elemental reading and counting before any theory.","exampleCN":"这门课先讲最基础的读与算，然后才谈理论。","why":"schooling speaks of elemental skills where it means the layer below all later ones.","whyCN":"教育说「基础技能」，指的是位于一切后续层次之下的那一层。"},{"no":"08","title":"Simple and uncomplicated","titleCN":"单纯不复杂的","definition":"pleasantly plain, without sophistication or hidden layers","definitionCN":"质朴而令人愉快，没有精巧或隐藏的层次","example":"Swimming in cold water gave him an elemental pleasure.","exampleCN":"在冷水里游泳给他一种单纯的快乐。","why":"the same bareness that can feel harsh can also feel honest, so the adjective carries a second, warmer tone.","whyCN":"同一种裸露既可能显得艰苦，也可能显得诚实，因此这个形容词带有第二种更温暖的语气。"}],"etymology":{"intro":{"en":"Elemental is element plus the Latin adjective ending -alis, English -al. The noun element goes back to Latin elementum, whose own origin is disputed. Dates are approximate.","cn":"elemental 是 element 加拉丁形容词词尾 -alis（英语作 -al）。名词 element 上溯拉丁语 elementum，其本身来源有争议。年代均为约数。"},"items":[{"era":"LATIN ELEMENTUM","en":"Elementum meant a first principle or rudiment, and in the plural elementa, the letters of the alphabet, the first lessons of a subject.","cn":"elementum 意为「第一原理、入门」，复数 elementa 指字母表，也指一门学科最初的课程。"},{"era":"FOUR ELEMENTS","en":"Medieval and Renaissance Latin used elementum for earth, water, air and fire, the supposed constituents of all bodies.","cn":"中世纪与文艺复兴时期的拉丁语用 elementum 指土、水、气、火，即被认为构成一切物体的四种东西。"},{"era":"ENGLISH ELEMENT","en":"English element is recorded from the fourteenth century in both the alphabetical and the material senses.","cn":"英语 element 自 14 世纪有记录，兼具字母与物质两种含义。"},{"era":"CHEMICAL ELEMENT","en":"Modern chemistry redefined element as a substance that cannot be split by chemical means, and this sense now dominates.","cn":"现代化学把 element 重新定义为不能用化学方法再分的物质，这一义项如今占主导。"},{"era":"-ALIS AND -AL","en":"Latin -alis made adjectives of relation; English shortened the ending to -al, giving elemental beside elementary.","cn":"拉丁语 -alis 构成关系形容词；英语把词尾缩为 -al，于是在 elementary 之外又有了 elemental。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (origin of elementum): no derivation is established. One old suggestion links it to alere, to nourish; another reads it as a sequence of letters; a third treats it as an Etruscan or otherwise borrowed word. All three are hypotheses.","cn":"来源不确定（elementum 的来源）：没有已证实的派生。旧说之一把它与 alere「滋养」相联系；另一说把它读作字母序列；第三说视之为伊特鲁里亚语或其他借词。三者都只是假说。"}]},"similar":{"note":{"en":"The first group shares the element stem and is often confused in writing; the second group names other words for what is basic or raw.","cn":"第一组共享 element 词干，写作中常被混用；第二组是其他表示「基本、原始」的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"element","ipa":"/ˈeləmənt/","tag":"same stem, noun","definition":"The noun itself: a chemical element, a component or a first principle; the adjective only describes such a thing.","definitionCN":"名词本身：化学元素、成分或第一原理；形容词只是描述这类事物。"},{"word":"elementary","ipa":"/ˌelɪˈmentri/","tag":"same stem, different suffix","definition":"From the same stem but with a different ending, it usually means simple, introductory or basic, as in elementary school.","definitionCN":"同词干而词尾不同，通常指简单、入门、基础，如小学。"},{"word":"elementally","ipa":"/ˌelɪˈmentli/","tag":"same stem, adverb","definition":"The adverb form, used when describing how something acts at the level of elements or basic forces.","definitionCN":"副词形式，用于描述某物在元素或基本力量层面如何起作用。"},{"word":"elements","ipa":"/ˈeləmənts/","tag":"plural, different sense","definition":"The plural often means the weather and its forces, as in exposed to the elements, a sense the adjective echoes.","definitionCN":"复数常指天气及其力量，如「暴露在风雨中」，形容词正呼应这一义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"basic","ipa":"/ˈbeɪsɪk/","tag":"plain fundamental","definition":"The everyday word for what lies at the bottom of a structure; it lacks the force-of-nature overtone.","definitionCN":"日常用词，指结构最底层的部分；没有「自然之力」那层意味。"},{"word":"fundamental","ipa":"/ˌfʌndəˈmentl/","tag":"foundation","definition":"From Latin fundus, bottom: it stresses that everything else rests on this, rather than that it cannot be split.","definitionCN":"出自拉丁 fundus「底部」：强调其余一切依赖它，而不是强调不可再分。"},{"word":"primal","ipa":"/ˈpraɪml/","tag":"earliest layer","definition":"Of the first age or the earliest layer of feeling; it adds time and instinct, which elemental only suggests.","definitionCN":"指最初的时代或最早的情感层次；加上时间与本能，而 elemental 只是暗示。"},{"word":"raw","ipa":"/rɔː/","tag":"unprocessed","definition":"Unprocessed, uncovered or harsh; it is close to one sense of elemental but said of materials and weather.","definitionCN":"未经加工、裸露或严酷；接近 elemental 的某一义，但多用于材料与天气。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin noun, the real adjective ending and real fixed phrases.","cn":"正常联想：真实的拉丁名词、真实的形容词词尾与真实的固定搭配。"},"normal":[{"en":"Element plus -al: the adjective of first principles.","cn":"element 加 -al：第一原理的形容词。"},{"en":"The family runs element, elemental, elementary, elementally and elements.","cn":"同族词有 element、elemental、elementary、elementally 与 elements。"},{"en":"Fixed phrases show both halves: elemental analysis, elemental forces.","cn":"固定搭配显示两面：元素分析、自然之力。"},{"en":"Old chemistry counted four elements, which is why the word can mean weather at its worst.","cn":"旧化学只数四种元素，所以这个词也能指最恶劣的天气。"},{"en":"Elementary and elemental share a stem but not a job: one means introductory, the other means of elements.","cn":"elementary 与 elemental 同词干而分工不同：一个指入门，一个指元素本身。"}],"abstract":[{"en":"Picture a child who empties a toy box until only four shapes remain.","cn":"想象一个孩子把玩具箱倒空，只剩四种形状。"},{"en":"Picture a storm that treats a brick wall as a curtain.","cn":"想象一场风暴把砖墙当作帘子。"},{"en":"Picture a meal of bread and water eaten outdoors, tasting better than a banquet.","cn":"想象在户外吃面包和白水，却比宴席更有滋味。"}]},"examples":[{"en":"Elemental sulphur is yellow and brittle at room temperature.","cn":"单质硫在室温下是黄色而易碎的。"},{"en":"The film reduces the story to an elemental struggle for water.","cn":"影片把故事归结为一场最根本的争水之争。"},{"en":"The hut offered elemental shelter and nothing more.","cn":"那间小屋只提供最原始的遮蔽，别无一物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「element（元素）+ al」——像元素一样不可再分、又像自然力一样强大 → 基本的、自然力般的","word":"elemental"},"root":"拉丁 elementum「第一原理、入门（复数指字母）」→ 英语 element「元素」→ 加形容词词尾 -al → elemental；elementum 本身的来源无定论，滋养说、字母序列说、借词说三者并列。","sensesIntro":{"en":"Eight senses follow one idea: what cannot be reduced further. The idea serves chemistry, then plain fundamentals, then the four ancient elements, then forces of nature, then bare shelter, basic units, first skills and finally simple pleasure.","cn":"八个义项沿同一个想法展开：不能再往下拆的东西。这个想法依次用于化学、一般原理、古代四元素、自然之力、裸露的居所、基本单元、最初技能，最后是单纯的快乐。"},"semanticMap":{"core":{"en":"CORE IMAGE: a heap of clutter reduced to four building blocks from which everything else can be rebuilt.","cn":"核心意象：一堆杂物被拆到只剩四块积木，其余一切都能由它们重建。"},"chain":["FIRST PRINCIPLE","CHEMICAL ELEMENT","BUILDING BLOCK","FOUR ELEMENTS","FORCE OF NATURE","BARE AND PLAIN"],"branches":[{"senses":"01","en":"THE ELEMENT ITSELF: a method or result that concerns chemical elements.","cn":"元素本身：涉及化学元素的方法或结果。"},{"senses":"02 · 06","en":"THE BLOCK: what cannot be split further, and what therefore supports everything else.","cn":"积木：不能再拆的东西，因而支撑其余一切。"},{"senses":"03","en":"THE STORM: the old elements imagined as weather with no wall strong enough.","cn":"风暴：把古老元素想象成任何墙都挡不住的天气。"},{"senses":"04 · 08","en":"BARE LIFE: only the necessary parts left, which can feel harsh or honest.","cn":"裸露的生活：只剩必需的部分，既可能艰苦，也可能诚实。"},{"senses":"05 · 07","en":"OLD THEORY AND FIRST LESSONS: four substances, and the first layer of a skill.","cn":"旧理论与最初课程：四种物质，以及一门技能的最初层次。"}]},"affixes":{"intro":{"en":"Elemental is a Latin-derived noun with a Latin adjective ending; the stem itself is ancient but of disputed origin.","cn":"elemental 是拉丁来源的名词加拉丁形容词词尾；词干古老，但来源有争议。"},"latinIntro":{"en":"Latin elementum and its plural elementa supply the stem, and -alis supplies the adjective pattern shared with many English words in -al.","cn":"拉丁语 elementum 及其复数 elementa 提供词干，-alis 提供与许多英语 -al 词共享的形容词样板。"},"items":[{"word":"elementum","structure":"elementum, elementi (n., second declension)","meaning":"first principle; rudiment","meaningCN":"第一原理；入门","example":"The Latin noun already carried the idea of a starting unit.","exampleCN":"这个拉丁名词已带有「起始单元」的意思。"},{"word":"elementa","structure":"plural of elementum","meaning":"letters; first lessons","meaningCN":"字母；最初的课程","example":"The plural meant the alphabet before it meant substances.","exampleCN":"这个复数先指字母表，后指物质。"},{"word":"-alis","structure":"-alis (Latin adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending made relational adjectives throughout Latin.","exampleCN":"这个词尾在拉丁语中构成大量关系形容词。"},{"word":"-al","structure":"English form of Latin -alis","meaning":"relating to","meaningCN":"与……有关的","example":"English shortened the ending in hundreds of borrowings.","exampleCN":"英语在数百个借词中把这个词尾缩短。"},{"word":"element","structure":"elementum through French","meaning":"a substance or component","meaningCN":"元素；成分","example":"Carbon is an element; water is a compound.","exampleCN":"碳是元素，水是化合物。"},{"word":"elemental","structure":"element plus -al","meaning":"of elements or of basic forces","meaningCN":"元素的；基本力量的","example":"Elemental forces shaped the coastline.","exampleCN":"自然之力塑造了这段海岸。"},{"word":"elementary","structure":"element plus -ary (relating to)","meaning":"introductory; simple","meaningCN":"入门的；简单的","example":"Elementary arithmetic comes before algebra.","exampleCN":"初等算术先于代数。"},{"word":"elementally","structure":"elemental plus -ly (adverb)","meaning":"at the level of elements","meaningCN":"在元素层面","example":"The two reactions are elementally different.","exampleCN":"这两个反应在元素层面上不同。"},{"word":"elements","structure":"plural of element","meaning":"weather and its forces","meaningCN":"天气及其力量","example":"The tent stood against the elements all night.","exampleCN":"帐篷整夜抵挡风雨。"}],"latinEntries":[{"word":"elementum","structure":"elementum, elementi (n., second declension)","meaning":"first principle, rudiment","meaningCN":"第一原理；入门"},{"word":"elementa","structure":"elementa, elementorum (n. plural)","meaning":"letters; first lessons","meaningCN":"字母；最初课程"}],"derivatives":[{"word":"element","pos":"n.","zh":"元素；要素"},{"word":"elementary","pos":"adj.","zh":"基础的；初级的"},{"word":"elementally","pos":"adv.","zh":"在基本层面"},{"word":"elements","pos":"n.","zh":"诸元素；风雨"},{"word":"elementalist","pos":"n.","zh":"元素论者"}]}},{"word":"molecular structure","ipa_uk":"/məˈlekjələ ˈstrʌktʃə/","ipa_us":"/məˈlekjələr ˈstrʌktʃər/","definition_zh":"分子结构；分子中原子间的排列与连接方式","definition_en":"the arrangement of atoms and the bonds between them within a molecule","core_image":"一组小球用细杆连成骨架，学生绕着它换角度，找出哪几个球连在同一个中心上","scene":"实验台上摆着一组小球与细杆连成的骨架模型，学生绕着它换角度观察。The molecular structure of the compound decides how it behaves in water.","sceneCN":"这里 molecular structure 指分子中原子与键的排列方式（第 1 个义项：分子内原子的空间排布与连接）；句意：这种化合物的分子结构决定了它在水中如何表现。图中可辨识物件：小球、细杆、实验台、旋转底座。","pos":[{"tag":"n.","zh":"分子结构；分子内原子的排列与连接"}],"collocations":[{"phrase":"molecular structure determination","zh":"分子结构测定"},{"phrase":"three-dimensional molecular structure","zh":"三维分子结构"},{"phrase":"molecular structure model","zh":"分子结构模型"},{"phrase":"change in molecular structure","zh":"分子结构的变化"},{"phrase":"molecular structure analysis","zh":"分子结构分析"},{"phrase":"protein molecular structure","zh":"蛋白质分子结构"}],"forms":[{"label":"复数","form":"molecular structures"},{"label":"名词（分子）","form":"molecule"},{"label":"形容词（分子的）","form":"molecular"},{"label":"名词（结构）","form":"structure"},{"label":"形容词（结构的）","form":"structural"}],"derivatives":[{"word":"molecule","pos":"n.","zh":"分子"},{"word":"molecular","pos":"adj.","zh":"分子的"},{"word":"structure","pos":"n.","zh":"结构"},{"word":"structural","pos":"adj.","zh":"结构的"},{"word":"macromolecule","pos":"n.","zh":"大分子"}],"senses":[{"no":"01","title":"The spatial arrangement inside a molecule","titleCN":"分子内原子的空间排布","definition":"the way atoms are placed in three-dimensional space within a single molecule","definitionCN":"单个分子内原子在三维空间中的摆放方式","example":"The molecular structure of the compound decides how it behaves in water.","exampleCN":"这种化合物的分子结构决定了它在水中如何表现。","why":"the phrase joins a unit of matter to the word for how parts are fitted together, so it names the fitting itself.","whyCN":"这个短语把物质单位与「部件如何拼合」这个词连在一起，因此命名的正是这种拼合。"},{"no":"02","title":"The order in which atoms are joined","titleCN":"原子相连的顺序","definition":"the connectivity of atoms, which atom is bonded to which, regardless of exact shape","definitionCN":"原子的连接关系，即谁与谁成键，不论精确形状","example":"Two compounds can share a molecular structure in connectivity yet differ in shape.","exampleCN":"两种化合物在连接顺序上可有相同的分子结构，形状却不同。","why":"structure includes the wiring diagram before it includes the angle, and this sense isolates that first layer.","whyCN":"「结构」先包含接线图，再包含角度，这一义项把第一层单独抽出来。"},{"no":"03","title":"The overall shape of a molecule","titleCN":"分子的整体形状","definition":"the actual three-dimensional form a molecule takes, as folded, bent or coiled","definitionCN":"分子实际呈现的三维形态，如折叠、弯曲或盘绕","example":"The molecular structure of the protein folds into a tight ball.","exampleCN":"这种蛋白质的分子结构折叠成紧密的一团。","why":"shape is the visible consequence of arrangement, so the same phrase names what the arrangement produces.","whyCN":"形状是排布带来的可见结果，因此同一短语也指排布所产生的东西。"},{"no":"04","title":"Bond lengths and angles","titleCN":"键长与键角等几何参数","definition":"the measured geometry of bonds, including lengths and the angles between them","definitionCN":"对键的几何测量，包括键长与键之间的夹角","example":"The molecular structure shows a bond angle close to one hundred and nine degrees.","exampleCN":"该分子结构显示键角接近一百零九度。","why":"structure is also a set of numbers, once the arrangement is measured rather than merely pictured.","whyCN":"一旦排布被测量而不只是被想象，结构也就成了一套数字。"},{"no":"05","title":"A drawn structure or model","titleCN":"结构式或结构模型","definition":"the diagram or physical model that represents the arrangement","definitionCN":"表现这种排布的图示或实体模型","example":"The paper printed the molecular structure beside the data table.","exampleCN":"论文把分子结构图印在数据表旁边。","why":"the representation is named by the thing it represents, a common shift from object to its picture.","whyCN":"表示物按它所表示的东西命名，这是从实物转到其图像的常见转义。"},{"no":"06","title":"Structure of a large molecule","titleCN":"大分子或聚合物的结构","definition":"the arrangement of repeating units in a polymer, protein or other macromolecule","definitionCN":"聚合物、蛋白质或其他大分子中重复单元的排布","example":"The molecular structure of the polymer explains why the fibre stretches.","exampleCN":"这种聚合物的分子结构解释了纤维为何能拉伸。","why":"the same phrase scales up from a small molecule to a chain of thousands of atoms without changing its meaning.","whyCN":"同一短语从一个小分子放大到上千原子的长链，意思并未改变。"},{"no":"07","title":"A structure as determined","titleCN":"经测定解析出的结构","definition":"the arrangement as established by experiment, often reported as a solved structure","definitionCN":"由实验确定、常被报告为「已解析」的排布","example":"The team published the molecular structure of the enzyme at high resolution.","exampleCN":"该团队发表了这种酶的高分辨率分子结构。","why":"research treats the structure as a result to be obtained, so the phrase names an achievement rather than a fact of nature.","whyCN":"研究把结构当作待取得的结果，因此这个短语命名的是一项成果，而非自然事实。"},{"no":"08","title":"Fine makeup of anything","titleCN":"比喻：事物的精细构成","definition":"figuratively, the detailed arrangement of parts in a system or argument","definitionCN":"比喻用法，指某个体系或论证内部各部分的细致安排","example":"The book lays out the molecular structure of the argument before judging it.","exampleCN":"这本书先铺陈这套论证的分子结构，再作评判。","why":"the metaphor borrows the chemist's picture of tiny parts joined in a definite order, a usage that stays clearly figurative.","whyCN":"这个比喻借化学家那幅「微小部件按确定次序相连」的图景，用法明显是比喻。"}],"etymology":{"intro":{"en":"The phrase joins two Latin lines: molecule, from molecula, a small mass, and structure, from structura, a building or fitting together. Both reached English through French. Dates are approximate.","cn":"这个短语连接两条拉丁语线索：molecule 出自 molecula「小团物质」，structure 出自 structura「建造、拼合」。两者都经法语进入英语。年代均为约数。"},"items":[{"era":"LATIN MOLES","en":"Moles meant a mass, a bulk, a heavy load; the diminutive molecula named a small mass of matter.","cn":"moles 意为「团块、体量、重负」；指小形式 molecula 指一小团物质。"},{"era":"FRENCH MOLECULE","en":"French molécule, used by seventeenth-century natural philosophers, named the smallest particle of a substance, and English borrowed it in that sense.","cn":"17 世纪的自然哲学家使用法语 molécule 指物质的最小粒子，英语按此义借入。"},{"era":"LATIN STRUERE","en":"Struere meant to pile up, build or arrange; structura named the act and the result, a building or an arrangement.","cn":"struere 意为「堆叠、建造、安排」，structura 既指动作，也指结果，即建筑或安排。"},{"era":"ENGLISH STRUCTURE","en":"English structure entered through French in the fourteenth century and widened from buildings to the arrangement of any organised whole.","cn":"英语 structure 于 14 世纪经法语进入，从建筑扩展到任何有组织整体的安排方式。"},{"era":"JOINED IN CHEMISTRY","en":"Nineteenth-century chemistry put the two nouns together once atoms were known to sit in definite positions inside a molecule.","cn":"当原子被确认在分子内占据确定位置之后，19 世纪的化学把这两个名词拼在一起。"},{"era":"FIRST DATE","en":"First date uncertain: the compound phrase is a modern technical formation, and its earliest citation is not settled, so the date is given as a century only.","cn":"首见年代不确定：这个复合短语是现代技术构词，最早书证尚无定论，因此只以世纪为单位给出年代。"}]},"similar":{"note":{"en":"The first group is the same two stems in other combinations; the second group names neighbouring descriptions of how a molecule is put together.","cn":"第一组是同样两个词干的其他组合；第二组是描述分子如何构成的相邻说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"molecule","ipa":"/ˈmɒlɪkjuːl/","tag":"same stem, object","definition":"The particle itself; the phrase with structure names how its atoms are arranged, not the particle.","definitionCN":"指粒子本身；加 structure 的短语说的是其原子怎样排布，而不是这个粒子。"},{"word":"molecular","ipa":"/məˈlekjələ/","tag":"same stem, adjective","definition":"The adjective meaning of molecules; alone it describes a scale, not an arrangement.","definitionCN":"意为「分子的」的形容词；单独使用时描述的是尺度，不是排布。"},{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"second stem alone","definition":"The general noun for arrangement; without molecular it could refer to a building or an organisation.","definitionCN":"泛指安排、构造的名词；不带 molecular 时也可能指建筑或组织。"},{"word":"structural","ipa":"/ˈstrʌktʃərəl/","tag":"same stem, adjective","definition":"Relating to structure; structural formula is the drawing of the molecular arrangement.","definitionCN":"与结构有关的；结构式正是分子排布的图示。"}]},{"heading":"NEAR MEANING","entries":[{"word":"configuration","ipa":"/kənˌfɪɡəˈreɪʃn/","tag":"fixed arrangement","definition":"The fixed spatial arrangement around a bond that can only change by breaking it; narrower than the whole molecular structure.","definitionCN":"绕键的固定空间排布，只有断键才能改变；比整个分子结构窄。"},{"word":"conformation","ipa":"/kənfɔːˈmeɪʃn/","tag":"changeable shape","definition":"A shape a molecule can adopt by rotating about single bonds; it changes without breaking bonds, unlike configuration.","definitionCN":"分子绕单键旋转可采取的形态；不经断键即可改变，与构型不同。"},{"word":"composition","ipa":"/ˌkɒmpəˈzɪʃn/","tag":"what is in it","definition":"Which atoms a molecule contains and in what proportion; it answers what, while structure answers where.","definitionCN":"分子含哪些原子、比例如何；它回答「有什么」，结构回答「在哪里」。"},{"word":"geometry","ipa":"/dʒiˈɒmətri/","tag":"measured shape","definition":"The measured angles and distances around a central atom; it is one layer of the molecular structure.","definitionCN":"中心原子周围测得的键角与距离；是分子结构的一层。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin nouns, the real word family and real laboratory phrases.","cn":"正常联想：真实的拉丁名词、真实的同族词与真实的实验室说法。"},"normal":[{"en":"Molecula is a small mass, and structura is a fitting together: a small mass fitted together in a set order.","cn":"molecula 是「小团物质」，structura 是「拼合」：一小团按确定次序拼起来的东西。"},{"en":"The family runs molecule, molecular, molecular structure, structure and structural.","cn":"同族词有 molecule、molecular、molecular structure、structure 与 structural。"},{"en":"Fixed phrases mark the laboratory: molecular structure determination, molecular structure model.","cn":"固定搭配标出实验室语境：分子结构测定、分子结构模型。"},{"en":"Composition answers what, structure answers where: the two questions are never the same.","cn":"组成回答「有什么」，结构回答「在哪里」：两个问题从不相同。"},{"en":"A structure can be drawn, measured or solved, which is why the phrase appears beside formulas and instruments alike.","cn":"结构可以被画、被测量、被解析，所以这个短语既出现在结构式旁，也出现在仪器旁。"}],"abstract":[{"en":"Picture a skeleton of wire and beads that looks different from every side.","cn":"想象一具铁丝与珠子搭成的骨架，从每一面看都不一样。"},{"en":"Picture two buildings made of the same bricks stacked in different orders.","cn":"想象两座用同样的砖、以不同次序砌成的楼。"},{"en":"Picture a sentence whose words are fixed but whose meaning changes when the order does.","cn":"想象一句话，词都相同，次序一变意思就变。"}]},"examples":[{"en":"Knowing the molecular structure let the team predict the drug's side effects.","cn":"了解分子结构使团队能够预测这种药的副作用。"},{"en":"The two isomers differ in molecular structure although their formulas match.","cn":"这两种异构体的分子式相同，分子结构却不同。"},{"en":"Cooling the sample changed its molecular structure without changing its composition.","cn":"冷却样品改变了它的分子结构，却没有改变其组成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「molecule（分子）+ structure（结构）」——分子内部的搭法 → 分子结构","word":"molecular structure"},"root":"拉丁 moles「团块」→ 指小形式 molecula「小团物质」→ 法语 molécule → 英语 molecule；拉丁 struere「堆叠、建造」→ structura「拼合、建筑」→ 英语 structure；两者合为 molecular structure。","sensesIntro":{"en":"Eight senses follow one question: how are the atoms inside a molecule put together? The answer moves from the whole spatial layout to connectivity, shape, measured geometry, the drawing, the large molecule, the solved result and finally a figurative use.","cn":"八个义项沿同一个问题展开：一个分子内部的原子是怎样拼起来的？答案从整体空间排布，依次走到连接顺序、形状、测量出的几何、图示、大分子、解析出的结果，最后是一个比喻用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: beads joined by rods into a frame that looks different from every angle.","cn":"核心意象：珠子由细杆连成骨架，从每个角度看都不一样。"},"chain":["SMALL MASS","JOINED ATOMS","CONNECTIVITY","SHAPE","MEASURED GEOMETRY","DRAWN MODEL"],"branches":[{"senses":"01","en":"THE WHOLE LAYOUT: where every atom sits in three dimensions.","cn":"整体排布：每个原子在三维空间中的位置。"},{"senses":"02 · 04","en":"WIRING AND MEASUREMENT: who is bonded to whom, and how long and at what angle.","cn":"接线与测量：谁与谁成键，键有多长、夹角多少。"},{"senses":"03","en":"THE SHAPE: the folded or coiled form that the layout produces.","cn":"形状：排布所产生的那团折叠或盘绕的形态。"},{"senses":"05 · 07","en":"THE PICTURE AND THE RESULT: a diagram on the page, and a structure solved in the laboratory.","cn":"图与结果：纸上的图示，与实验室里解析出来的结构。"},{"senses":"06 · 08","en":"SCALING OUT: a chain of thousands of atoms, or a system's fine makeup used as a metaphor.","cn":"向外缩放：上千原子的长链，或被用作比喻的体系精细构成。"}]},"affixes":{"intro":{"en":"The phrase is built from two complete Latin-derived words, each with its own suffix, so it can be read as two morpheme chains joined by English syntax.","cn":"这个短语由两个完整的拉丁来源词构成，各自带词尾，因此可以读作两条语素链由英语句法连接。"},"latinIntro":{"en":"Moles and molecula supply the first chain, struere and structura the second; -cule and -ure are the two endings that make the nouns.","cn":"moles 与 molecula 提供第一条链，struere 与 structura 提供第二条；-cule 与 -ure 是构成这两个名词的两个词尾。"},"items":[{"word":"moles","structure":"moles, molis (f., third declension)","meaning":"mass, bulk, heavy load","meaningCN":"团块；体量；重负","example":"The Latin noun names a lump of matter.","exampleCN":"这个拉丁名词指一团物质。"},{"word":"-cule","structure":"-cula (Latin diminutive ending)","meaning":"small","meaningCN":"小的","example":"The ending shrinks a mass into a particle.","exampleCN":"这个词尾把「团块」缩小成「粒子」。"},{"word":"molecula","structure":"moles plus -cula","meaning":"a small mass","meaningCN":"一小团物质","example":"The diminutive became the scientific term for a particle.","exampleCN":"这一指小形式成了指粒子的科学术语。"},{"word":"molecule","structure":"molecula through French molécule","meaning":"the smallest particle of a substance","meaningCN":"物质的最小粒子","example":"A water molecule has three atoms.","exampleCN":"一个水分子有三个原子。"},{"word":"molecular","structure":"molecule plus -ar (relating to)","meaning":"of molecules","meaningCN":"分子的","example":"Molecular scale is measured in billionths of a metre.","exampleCN":"分子尺度以十亿分之一米计量。"},{"word":"struere","structure":"struere, struxi, structum (Latin verb, third conjugation)","meaning":"to pile up, build, arrange","meaningCN":"堆叠；建造；安排","example":"The verb supplies the image of laying parts in order.","exampleCN":"这个动词提供「把部件按次序码放」的意象。"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building; a fitting together","meaningCN":"建筑；拼合方式","example":"The noun covers both the act and the result.","exampleCN":"这个名词同时涵盖动作与结果。"},{"word":"structure","structure":"structura through Old French","meaning":"arrangement of parts","meaningCN":"各部分的安排","example":"The structure decides which parts can move.","exampleCN":"结构决定哪些部件可以动。"},{"word":"structural","structure":"structure plus -al","meaning":"relating to structure","meaningCN":"与结构有关的","example":"A structural formula draws the bonds.","exampleCN":"结构式把键画出来。"},{"word":"macromolecule","structure":"macro- (large) plus molecule","meaning":"a very large molecule","meaningCN":"很大的分子","example":"Proteins are macromolecules with folded structure.","exampleCN":"蛋白质是具有折叠结构的大分子。"}],"latinEntries":[{"word":"moles","structure":"moles, molis (f., third declension)","meaning":"mass, bulk","meaningCN":"团块；体量"},{"word":"molecula","structure":"molecula, moleculae (f., first declension)","meaning":"a small mass","meaningCN":"一小团物质"},{"word":"struere","structure":"struere, struxi, structum (verb, third conjugation)","meaning":"to pile up, build","meaningCN":"堆叠；建造"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building; arrangement","meaningCN":"建筑；安排"}],"derivatives":[{"word":"molecule","pos":"n.","zh":"分子"},{"word":"molecular","pos":"adj.","zh":"分子的"},{"word":"structure","pos":"n.","zh":"结构"},{"word":"structural","pos":"adj.","zh":"结构的"},{"word":"macromolecule","pos":"n.","zh":"大分子"}]}},{"word":"atomic structure","ipa_uk":"/əˈtɒmɪk ˈstrʌktʃə/","ipa_us":"/əˈtɑːmɪk ˈstrʌktʃər/","definition_zh":"原子结构；原子内部核与电子的组成与排布","definition_en":"the arrangement of protons, neutrons and electrons within an atom","core_image":"一颗小核被几层薄薄的轨道环围住，环上散着细小的光点","scene":"一颗小核被几层薄薄的轨道环围住，环上散着细小的光点。The atomic structure of carbon explains why it forms four bonds.","sceneCN":"这里 atomic structure 指原子内部核与电子的排布（第 1 个义项：原子整体的内部构成与层次）；句意：碳的原子结构解释了它为何能形成四个键。图中可辨识物件：中心核、三层轨道环、环上的光点、斜射的光束。","pos":[{"tag":"n.","zh":"原子结构；原子内部的组成与排布"}],"collocations":[{"phrase":"atomic structure model","zh":"原子结构模型"},{"phrase":"atomic structure theory","zh":"原子结构理论"},{"phrase":"atomic structure of an element","zh":"某元素的原子结构"},{"phrase":"atomic structure determination","zh":"原子结构测定"},{"phrase":"electron arrangement in atomic structure","zh":"原子结构中的电子排布"},{"phrase":"changes in atomic structure","zh":"原子结构的变化"}],"forms":[{"label":"复数","form":"atomic structures"},{"label":"名词（原子）","form":"atom"},{"label":"形容词（原子的）","form":"atomic"},{"label":"名词（结构）","form":"structure"},{"label":"形容词（结构的）","form":"structural"}],"derivatives":[{"word":"atom","pos":"n.","zh":"原子"},{"word":"atomic","pos":"adj.","zh":"原子的；原子能的"},{"word":"atomism","pos":"n.","zh":"原子论"},{"word":"structure","pos":"n.","zh":"结构"},{"word":"subatomic","pos":"adj.","zh":"亚原子的"}],"senses":[{"no":"01","title":"The internal layout of an atom","titleCN":"原子内部的整体排布","definition":"the way the parts of an atom are arranged, with a nucleus at the centre and electrons around it","definitionCN":"原子各部分的位置安排，核在中心，电子在其周围","example":"The atomic structure of carbon explains why it forms four bonds.","exampleCN":"碳的原子结构解释了它为何能形成四个键。","why":"the phrase puts the smallest unit of matter beside the word for how parts are fitted together, so it names an inner layout.","whyCN":"这个短语把物质的最小单位与「部件如何拼合」这个词放在一起，命名的是一种内部排布。"},{"no":"02","title":"What an atom is made of","titleCN":"原子由什么构成","definition":"the inventory of protons, neutrons and electrons that a particular atom contains","definitionCN":"某个原子所含质子、中子与电子的清单","example":"Adding a neutron changes the atomic structure without changing the element.","exampleCN":"加一个中子改变了原子结构，却不改变元素种类。","why":"structure also answers what is inside, so the phrase covers the count of particles as well as their placement.","whyCN":"结构也回答「里面有什么」，因此这个短语既涵盖粒子的数量，也涵盖它们的位置。"},{"no":"03","title":"The shell arrangement of electrons","titleCN":"电子层结构","definition":"the distribution of electrons among shells and subshells around the nucleus","definitionCN":"电子在核外各壳层与亚层中的分布","example":"The atomic structure of sodium leaves one electron in an outer shell.","exampleCN":"钠的原子结构在最外层留下一个电子。","why":"most chemical behaviour is decided by the outermost electrons, so this layer of the structure is often what the phrase means.","whyCN":"大部分化学行为由最外层电子决定，因此这个短语常指的正是这一层结构。"},{"no":"04","title":"The structure of the nucleus","titleCN":"原子核的结构","definition":"the arrangement of protons and neutrons within the nucleus itself","definitionCN":"核内质子与中子自身的排列","example":"The atomic structure at the centre of the atom is far smaller than the atom.","exampleCN":"原子中心那部分结构比整个原子小得多。","why":"the phrase can be narrowed to the core, where a different set of forces holds the parts together.","whyCN":"这个短语可以被收窄到核心，那里由另一套力把部件聚在一起。"},{"no":"05","title":"A model or diagram of the atom","titleCN":"原子结构模型或图示","definition":"a drawing, physical model or animation that stands for the arrangement","definitionCN":"代表这种排布的图、实体模型或动画","example":"The textbook prints the atomic structure as rings around a dot.","exampleCN":"教科书把原子结构画成一个点外的几圈环。","why":"the representation takes the name of the thing represented, a common shift from object to image.","whyCN":"表示物取用了被表示之物的名字，这是从实物到图像的常见转义。"},{"no":"06","title":"The theory of atomic structure","titleCN":"原子结构理论","definition":"the body of principles explaining how atoms are built and why they behave as they do","definitionCN":"解释原子如何构成、为何如此表现的一套原理","example":"Atomic structure theory replaced the older picture of indivisible spheres.","exampleCN":"原子结构理论取代了早先那种不可分的球体图景。","why":"the same phrase names both the object and the science of the object, as with many technical terms.","whyCN":"同一个短语既命名对象，也命名关于对象的科学，许多技术术语都是如此。"},{"no":"07","title":"A structure found by experiment","titleCN":"实验测定出的原子结构","definition":"the arrangement as established by scattering, spectroscopy or other measurements","definitionCN":"通过散射、光谱或其他测量确定的排布","example":"The team reported the atomic structure of the surface layer at high precision.","exampleCN":"该团队高精度报告了表面层的原子结构。","why":"research treats the structure as a result to be obtained, so the phrase can name an achievement rather than a fact.","whyCN":"研究把结构当作待取得的结果，因此这个短语可以命名一项成果，而非一个事实。"},{"no":"08","title":"Atomic-scale arrangement in a material","titleCN":"材料中原子尺度的排列","definition":"the way atoms sit relative to one another in a crystal, alloy or surface","definitionCN":"原子在晶体、合金或表面中相对彼此的坐落方式","example":"Cooling slowly gives the alloy a more orderly atomic structure.","exampleCN":"缓慢冷却使合金获得更有序的原子排列。","why":"materials science widened the phrase from one atom to a whole lattice, keeping the same words.","whyCN":"材料科学把这个短语从单个原子扩大到整个晶格，用词不变。"}],"etymology":{"intro":{"en":"The phrase combines atomic, from Greek atomos, uncuttable, with structure, from Latin structura, a building. Both parts reached English by different routes. Dates are approximate.","cn":"这个短语把 atomic（出自希腊语 atomos「不可切分」）与 structure（出自拉丁语 structura「建筑、拼合」）组合起来。两部分经不同路径进入英语。年代均为约数。"},"items":[{"era":"GREEK TEMNEIN","en":"Temnein meant to cut. With the negative prefix a-, Greek formed atomos, not cuttable, hence indivisible.","cn":"temnein 意为「切」。加上否定前缀 a-，希腊语构成 atomos「不可切的」，因而「不可分」。"},{"era":"GREEK ATOMOS","en":"Atomos was used by Democritus and Epicurus for the smallest, indivisible pieces of matter, a philosophical claim rather than an experimental finding.","cn":"atomos 被德谟克利特与伊壁鸠鲁用于指最小、不可分的物质颗粒，那是哲学主张，不是实验发现。"},{"era":"LATIN ATOMUS","en":"Latin atomus borrowed the Greek word, and English atom arrived from it in the sixteenth century through French and Latin channels.","cn":"拉丁语 atomus 借入这个希腊词，英语 atom 于 16 世纪经法语与拉丁语渠道由它而来。"},{"era":"ENGLISH ATOMIC","en":"The adjective atomic appears later and took on the modern sense once atoms were known to have parts and to release energy.","cn":"形容词 atomic 出现较晚；当人们知道原子有内部结构并能释放能量后，它才获得现代含义。"},{"era":"LATIN STRUCTURA","en":"Structura, from struere, to build, gave English structure and the arrangement sense of the phrase.","cn":"structura 出自 struere「建造」，为英语提供 structure，以及这个短语中「排布」的含义。"},{"era":"FIRST DATE","en":"First date uncertain: the compound phrase is a modern technical formation whose earliest citation is not settled, so the date is given as a period rather than a year.","cn":"首见年代不确定：这个复合短语是现代技术构词，最早书证尚无定论，因此只以时期而非年份给出年代。"}]},"similar":{"note":{"en":"The first group shares the atom stem; the second group names other levels at which structure is described.","cn":"第一组共享 atom 词干；第二组是描述结构的其他层次。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"atom","ipa":"/ˈætəm/","tag":"same stem, object","definition":"The particle itself; the phrase with structure describes its insides rather than naming it again.","definitionCN":"指粒子本身；加 structure 的短语描述的是它的内部，而不是再命名一次。"},{"word":"atomic","ipa":"/əˈtɒmɪk/","tag":"same stem, adjective","definition":"The adjective meaning of atoms, also used for atomic energy; alone it says nothing about arrangement.","definitionCN":"意为「原子的」的形容词，也用于原子能；单独使用不涉及排布。"},{"word":"atomism","ipa":"/ˈætəmɪzəm/","tag":"same stem, doctrine","definition":"The philosophical claim that matter consists of indivisible units, which is older than any measured structure.","definitionCN":"认为物质由不可分单位构成的哲学主张，比任何实测结构都古老。"},{"word":"subatomic","ipa":"/ˌsʌbəˈtɒmɪk/","tag":"same stem, smaller scale","definition":"Describing particles smaller than an atom; it names the parts that the atomic structure is made of.","definitionCN":"描述比原子更小的粒子；它命名的正是构成原子结构的那些部件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"molecular structure","ipa":"/məˈlekjələ ˈstrʌktʃə/","tag":"next level up","definition":"The arrangement of atoms inside a molecule, one scale above the single atom.","definitionCN":"分子内原子的排布，比单个原子高一个尺度。"},{"word":"crystal structure","ipa":"/ˈkrɪstl ˈstrʌktʃə/","tag":"repeating lattice","definition":"The repeating arrangement of atoms in a solid, a level above one atom and below a whole material.","definitionCN":"固体中原子重复排列的方式，高于单个原子、低于整块材料。"},{"word":"nuclear structure","ipa":"/ˈnjuːkliə ˈstrʌktʃə/","tag":"inner level","definition":"The arrangement inside the nucleus; it is the core of the atomic structure, not the whole of it.","definitionCN":"原子核内部的排布；它是原子结构的核心部分，而非整体。"},{"word":"composition","ipa":"/ˌkɒmpəˈzɪʃn/","tag":"what is present","definition":"Which particles are present and in what number; structure adds where they sit.","definitionCN":"存在哪些粒子、各有多少；结构则补充它们的位置。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek and Latin roots and real textbook phrases.","cn":"正常联想：真实的希腊与拉丁词根，以及真实的教科书说法。"},"normal":[{"en":"A- not plus temnein to cut: atomos means uncuttable, the name given before anyone could cut one.","cn":"a-「不」加 temnein「切」：atomos 意为「不可切分」，这个名字在谁也切不开原子时就已取好。"},{"en":"The family runs atom, atomic, atomism, atomic structure and subatomic.","cn":"同族词有 atom、atomic、atomism、atomic structure 与 subatomic。"},{"en":"Fixed phrases mark the classroom: atomic structure model, atomic structure theory.","cn":"固定搭配标出课堂语境：原子结构模型、原子结构理论。"},{"en":"The outer electrons decide chemistry, which is why atomic structure questions usually end at the shell.","cn":"外层电子决定化学行为，所以关于原子结构的提问通常止于电子层。"},{"en":"The phrase has two halves from two languages: a Greek particle and a Latin building.","cn":"这个短语的两半来自两种语言：希腊语的粒子与拉丁语的建筑。"}],"abstract":[{"en":"Picture a tiny stone at the centre of a much larger empty room.","cn":"想象一颗小石子位于一间大得多的空房间中央。"},{"en":"Picture rings drawn on water where a pebble fell, with nothing solid in the rings.","cn":"想象石子落水后画出的一圈圈波纹，圈里并无实物。"},{"en":"Picture a library whose shelves are mostly empty but whose few books decide everything.","cn":"想象一座书架大多空着的图书馆，几本书却决定了一切。"}]},"examples":[{"en":"Atomic structure determines which elements react alike.","cn":"原子结构决定了哪些元素反应行为相似。"},{"en":"The model shows an atomic structure with two filled inner shells.","cn":"该模型显示了一个内层已填满两层的原子结构。"},{"en":"Heating changed the atomic structure of the surface, not its composition.","cn":"加热改变了表面的原子结构，却没有改变其组成。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「atomic（原子的）+ structure（结构）」——原子里面怎么搭 → 原子结构","word":"atomic structure"},"root":"希腊 a-「不」+ temnein「切」→ atomos「不可分」→ 拉丁 atomus → 英语 atom「原子」→ atomic；拉丁 struere「建造」→ structura → 英语 structure；合为 atomic structure。","sensesIntro":{"en":"Eight senses follow one layout: an atom has parts arranged in a definite order. The layout then narrows to the particle count, the electron shells, the nucleus, and widens to models, theory, measured results and whole crystals.","cn":"八个义项沿同一种排布展开：原子各部件按确定次序安排。这种排布随后收窄到粒子数量、电子层、原子核，再扩展到模型、理论、实测结果与整块晶体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tiny centre wrapped in thin rings, with small points of light scattered along them.","cn":"核心意象：一个极小的中心被薄薄的环包住，环上散着细小的光点。"},"chain":["UNCUTTABLE UNIT","CENTRE AND SHELLS","PARTICLE COUNT","ELECTRON SHELLS","NUCLEUS","ATOMIC-SCALE ORDER"],"branches":[{"senses":"01","en":"THE WHOLE ATOM: a centre with electrons arranged around it.","cn":"整个原子：一个中心，电子在其周围排布。"},{"senses":"02 · 04","en":"THE INVENTORY AND THE CORE: what is inside, and the nucleus that holds most of it.","cn":"清单与核心：里面有什么，以及容纳其中大部分物质的核。"},{"senses":"03","en":"THE OUTER SHELLS: the electrons that decide how the element behaves.","cn":"外层：决定元素行为的那些电子。"},{"senses":"05 · 07","en":"PICTURE AND MEASUREMENT: the classroom model and the precision result.","cn":"图与测量：课堂模型与精密测量结果。"},{"senses":"06 · 08","en":"THEORY AND LATTICE: the principles, and the same order repeated through a solid.","cn":"理论与晶格：一套原理，以及在固体中重复的同一秩序。"}]},"affixes":{"intro":{"en":"Two independent words, each with its own prefix, root and ending, are joined here; neither half is a suffix of the other.","cn":"这里连接两个独立的词，各自带前缀、词根与词尾；任何一半都不是另一半的后缀。"},"latinIntro":{"en":"Greek supplied the first word through Latin atomus, and Latin supplied the second through structura; the two lines never merged before English joined them.","cn":"希腊语经拉丁 atomus 提供第一个词，拉丁语经 structura 提供第二个词；两条线在英语把它们拼合之前从未合并。"},"items":[{"word":"a-","structure":"a- (Greek negative prefix)","meaning":"not","meaningCN":"不；非","example":"The prefix denies that the unit can be cut.","exampleCN":"这个前缀否定这个单位可以被切开。"},{"word":"temnein","structure":"temnein (Greek verb, to cut)","meaning":"to cut","meaningCN":"切；割","example":"The verb supplies the image of a blade meeting matter.","exampleCN":"这个动词提供刀刃碰到物质的意象。"},{"word":"atomos","structure":"a- plus temnein","meaning":"uncuttable","meaningCN":"不可切分的","example":"The Greek adjective became the name of the particle.","exampleCN":"这个希腊形容词成了粒子的名称。"},{"word":"atom","structure":"atomos through Latin atomus","meaning":"the smallest unit of an element","meaningCN":"元素的最小单位","example":"An atom of carbon has six protons.","exampleCN":"一个碳原子有六个质子。"},{"word":"atomic","structure":"atom plus -ic (relating to)","meaning":"of atoms","meaningCN":"原子的","example":"Atomic radius grows down a group.","exampleCN":"原子半径沿族向下增大。"},{"word":"struere","structure":"struere, struxi, structum (Latin verb, third conjugation)","meaning":"to build, pile up","meaningCN":"建造；堆叠","example":"The verb supplies the idea of ordered building.","exampleCN":"这个动词提供「有次序地搭建」的意思。"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building; arrangement","meaningCN":"建筑；安排","example":"The noun covers both the act and its result.","exampleCN":"这个名词同时涵盖动作与结果。"},{"word":"structure","structure":"structura through French","meaning":"arrangement of parts","meaningCN":"各部分的安排","example":"The structure decides how the parts move.","exampleCN":"结构决定部件如何运动。"},{"word":"atomic structure","structure":"atomic plus structure","meaning":"the arrangement inside an atom","meaningCN":"原子内部的排布","example":"The atomic structure explains the four bonds.","exampleCN":"原子结构解释了四个键的由来。"},{"word":"subatomic","structure":"sub- (below) plus atomic","meaning":"smaller than an atom","meaningCN":"小于原子的","example":"Electrons are subatomic particles.","exampleCN":"电子是亚原子粒子。"}],"latinEntries":[{"word":"atomus","structure":"atomus, atomi (f., Greek loan in Latin)","meaning":"an indivisible particle","meaningCN":"不可分的粒子"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building; arrangement","meaningCN":"建筑；安排"},{"word":"struere","structure":"struere, struxi, structum (verb, third conjugation)","meaning":"to build, pile up","meaningCN":"建造；堆叠"}],"derivatives":[{"word":"atom","pos":"n.","zh":"原子"},{"word":"atomic","pos":"adj.","zh":"原子的"},{"word":"atomism","pos":"n.","zh":"原子论"},{"word":"structure","pos":"n.","zh":"结构"},{"word":"subatomic","pos":"adj.","zh":"亚原子的"}]}},{"word":"bonding","ipa_uk":"/ˈbɒndɪŋ/","ipa_us":"/ˈbɑːndɪŋ/","definition_zh":"结合；成键；情感联结的建立；粘接","definition_en":"the act or process of joining things or people together","core_image":"两根木条被胶粘成一根，接缝处仍看得见两道纹路","scene":"两根木条被胶粘成一根，接缝处仍看得见两道纹路。Hydrogen bonding holds the two strands of the double helix together.","sceneCN":"这里 bonding 指原子或分子之间形成键合的作用（第 1 个义项：粒子间形成化学键的过程）；句意：氢键作用把双螺旋的两条链合在一起。图中可辨识物件：两根木条、胶层、接缝纹路、压紧的夹具。","pos":[{"tag":"n.","zh":"结合；成键；情感联结；粘接"}],"collocations":[{"phrase":"hydrogen bonding","zh":"氢键作用"},{"phrase":"chemical bonding","zh":"化学成键"},{"phrase":"team bonding","zh":"团队凝聚"},{"phrase":"bonding time","zh":"亲密相处的时间"},{"phrase":"dental bonding","zh":"牙科黏接修复"},{"phrase":"bonding agent","zh":"黏合剂"}],"forms":[{"label":"原形（动词）","form":"bond"},{"label":"三单","form":"bonds"},{"label":"过去式","form":"bonded"},{"label":"过去分词","form":"bonded"},{"label":"复数（作名词）","form":"bondings"}],"derivatives":[{"word":"bond","pos":"n./v.","zh":"纽带；债券；结合"},{"word":"bonded","pos":"adj.","zh":"黏合的；有保税监管的"},{"word":"bonder","pos":"n.","zh":"接合设备；黏合工"},{"word":"bondable","pos":"adj.","zh":"可黏合的"},{"word":"binder","pos":"n.","zh":"黏合剂；装订机"}],"senses":[{"no":"01","title":"Atoms joining by chemical bonds","titleCN":"原子通过化学键结合","definition":"the process by which atoms or ions become held together by chemical bonds","definitionCN":"原子或离子被化学键维系在一起的过程","example":"Hydrogen bonding holds the two strands of the double helix together.","exampleCN":"氢键作用把双螺旋的两条链合在一起。","why":"the -ing form turns the verb into the process, so bonding is the act of making a bond rather than the bond itself.","whyCN":"-ing 形式把动词变为过程，因此 bonding 是「建立键」这个动作，而不是键本身。"},{"no":"02","title":"A named type of chemical bonding","titleCN":"某一具体类型的成键","definition":"used with a qualifier to name a kind of bonding, as ionic, covalent, metallic or hydrogen bonding","definitionCN":"与限定词连用，命名某一类成键，如离子、共价、金属或氢键作用","example":"Ionic bonding explains why salt conducts when it melts.","exampleCN":"离子成键解释了盐熔化后为何能导电。","why":"chemistry sorts bonds into families, and the process noun takes the family name in front of it.","whyCN":"化学把键分成族，这个表示过程的名词便把族名放在自己前面。"},{"no":"03","title":"Building an emotional connection","titleCN":"建立情感联结","definition":"the forming of a close relationship of trust or affection","definitionCN":"建立信任或亲近的紧密关系","example":"The long train ride gave the two strangers time for bonding.","exampleCN":"漫长的火车旅程给了两个陌生人建立情谊的时间。","why":"the metaphor treats affection as a bond that is made rather than found, so the making takes the same name.","whyCN":"这个比喻把感情当作被建立而非被发现的纽带，因此建立的动作也用同一个名字。"},{"no":"04","title":"Parent and infant attachment","titleCN":"亲子依恋的形成","definition":"the early formation of attachment between a parent and a newborn","definitionCN":"父母与新生儿之间依恋关系的早期形成","example":"Hospital staff encourage bonding in the first hour after birth.","exampleCN":"医院人员鼓励在出生后第一小时内建立亲子联结。","why":"child development needed a plain word for the first tie, and borrowed the general idea of fastening.","whyCN":"儿童发展研究需要给最初的纽带一个朴素的词，于是借用了「系紧」这个概念。"},{"no":"05","title":"Bringing a group together","titleCN":"使群体凝聚","definition":"activities or shared experience that make a team feel like a unit","definitionCN":"让团队感觉像一个整体的活动或共同经历","example":"The company paid for a weekend of team bonding.","exampleCN":"公司出钱安排了一个周末的团队凝聚活动。","why":"management extended the family metaphor to colleagues, who are also said to be bonded.","whyCN":"管理学把这个家庭比喻扩展到同事，同事也被说成 bonded。"},{"no":"06","title":"Sticking materials together","titleCN":"把材料粘接起来","definition":"the use of an adhesive to join two surfaces","definitionCN":"用黏合剂把两个表面接合","example":"Proper bonding of the panels keeps water out of the joint.","exampleCN":"板材粘接到位才能让水不进入接缝。","why":"the physical sense of fastening never left the word, and industry kept it for gluing and welding.","whyCN":"「系紧」这个物理义从未离开这个词，工业把它保留给胶接与焊接。"},{"no":"07","title":"Joining parts in manufacture","titleCN":"制造中的部件接合","definition":"a step in production where two components are permanently joined","definitionCN":"生产中把两个部件永久接合的一道工序","example":"Robotic bonding replaced the hand-glued seam.","exampleCN":"机器人接合取代了手工涂胶的接缝。","why":"a factory names each step, and this process noun became the name of one station on the line.","whyCN":"工厂给每道工序命名，这个表示过程的名词便成了产线上一个工位的名字。"},{"no":"08","title":"Dental bonding","titleCN":"牙科黏接修复","definition":"a dental treatment in which resin is bonded to a tooth to repair or reshape it","definitionCN":"把树脂黏接到牙齿上以修复或改形的一种牙科治疗","example":"The dentist used bonding to close the small gap.","exampleCN":"牙医用黏接修复补上了那道小缝。","why":"dentistry borrowed the industrial word for gluing and gave it a clinical sense, now fixed in the phrase dental bonding.","whyCN":"牙科借用工业上的胶接一词，赋予它临床含义，如今固定在「牙科黏接」这一说法里。"}],"etymology":{"intro":{"en":"Bonding is the English -ing noun of the verb bond, which comes from Old Norse band, a band or cord, and is related to English bind. It is not Latin. Dates are approximate.","cn":"bonding 是动词 bond 的英语 -ing 名词形式；bond 出自古诺斯语 band「带子、绳索」，与英语 bind 同源。它并非拉丁语来源。年代均为约数。"},"items":[{"era":"PROTO-GERMANIC BINDAN","en":"The Germanic verb behind English bind meant to tie or fasten. Its Indo-European ancestor is usually given as a reconstructed form, not an attested word.","cn":"英语 bind 背后的日耳曼语动词意为「捆、系」。其印欧语祖先通常以重构形式给出，并非有记录的词。"},{"era":"OLD NORSE BAND","en":"Old Norse band named a band, a cord or a shackle, and the word entered English during the Scandinavian period.","cn":"古诺斯语 band 指带子、绳索或镣铐，这个词在斯堪的纳维亚影响时期进入英语。"},{"era":"ENGLISH BOND","en":"English bond appears in the thirteenth century for a restraint or a tie, and later for a promise sealed by such a tie, hence a financial bond.","cn":"英语 bond 于 13 世纪出现，指束缚或纽带，后来指以这种纽带来封存的承诺，因而有金融债券之义。"},{"era":"CHEMICAL BOND","en":"Nineteenth-century chemistry applied the word to the link between atoms, and the -ing noun followed for the process of forming such links.","cn":"19 世纪的化学把这个词用于原子之间的连接，随后 -ing 名词便指形成这种连接的过程。"},{"era":"SOCIAL BONDING","en":"Twentieth-century psychology and management extended the process noun to attachment between people and to team building.","cn":"20 世纪的心理学与管理学把这个过程名词扩展到人与人之间的依恋，以及团队建设。"},{"era":"FIRST DATE","en":"First date uncertain: the earliest chemical use of bonding is not precisely dated, and the psychological use belongs to the twentieth century, so the dates are approximate.","cn":"首见年代不确定：bonding 最早的化学用例没有确切年代，心理学用法属于 20 世纪，因此年代均为约数。"}]},"similar":{"note":{"en":"The first group is the same Germanic stock in its other shapes; the second group names neighbouring ways of joining or attaching, each with a different emphasis.","cn":"第一组是同一日耳曼词源的其他形态；第二组是相邻的「连接、附着」说法，各自侧重不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bond","ipa":"/bɒnd/","tag":"base noun and verb","definition":"The tie itself, or the act of tying; bonding is the process, bond is the thing or the verb.","definitionCN":"指纽带本身，或系结的动作；bonding 是过程，bond 是物或动词。"},{"word":"bind","ipa":"/baɪnd/","tag":"same stock, verb","definition":"The English verb meaning to tie; bond came from the Norse noun of the same family.","definitionCN":"意为「捆、系」的英语动词；bond 出自同族的诺斯语名词。"},{"word":"band","ipa":"/bænd/","tag":"same stock, noun","definition":"A flat strip that ties things; it is the visible object behind the abstract idea of a bond.","definitionCN":"用来捆扎的扁带；它是抽象的「纽带」背后那个看得见的物件。"},{"word":"bonded","ipa":"/ˈbɒndɪd/","tag":"same stem, participle","definition":"The participle and adjective meaning joined, or held under a customs bond; it describes a state, not the process.","definitionCN":"分词兼形容词，意为已接合的，或处于保税监管下的；描述状态，而非过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"attachment","ipa":"/əˈtætʃmənt/","tag":"emotional tie","definition":"The state of being emotionally connected, especially in psychology; bonding is the forming of that state.","definitionCN":"情感上相连的状态，尤用于心理学；bonding 是这种状态形成的过程。"},{"word":"adhesion","ipa":"/ədˈhiːʒn/","tag":"surface sticking","definition":"The sticking of two surfaces by molecular attraction or glue; it is the technical word for part of bonding.","definitionCN":"两个表面靠分子吸引或胶粘住；是 bonding 某一部分的技术用词。"},{"word":"cohesion","ipa":"/kəʊˈhiːʒn/","tag":"sticking within","definition":"The holding together of parts of the same substance, as water molecules to one another.","definitionCN":"同一物质内部各部分的聚拢，如水分子彼此相吸。"},{"word":"linkage","ipa":"/ˈlɪŋkɪdʒ/","tag":"mechanical join","definition":"A connection between parts of a machine or a system; it stresses mechanism rather than affection.","definitionCN":"机器或系统各部件之间的连接；强调机械，而非情感。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Norse source, the real word family and real phrases.","cn":"正常联想：真实的诺斯语来源、真实的同族词与真实说法。"},"normal":[{"en":"Old Norse band is a cord, and a cord is what ties two things into one.","cn":"古诺斯语 band 是一根绳，而绳正是把两样东西捆成一样的东西。"},{"en":"The family runs bond, bonding, bonded, binder and bind.","cn":"同族词有 bond、bonding、bonded、binder 与 bind。"},{"en":"Fixed phrases mark the range: hydrogen bonding, team bonding, dental bonding.","cn":"固定搭配标出范围：氢键作用、团队凝聚、牙科黏接。"},{"en":"The -ing ending is the tell: it names the making of a bond, not the bond.","cn":"词尾 -ing 是辨别标志：它命名的是建立纽带，而不是纽带本身。"},{"en":"The same word covers glue and affection, because both fasten two things that were apart.","cn":"同一个词覆盖胶水与感情，因为两者都是把原本分开的两样东西系在一起。"}],"abstract":[{"en":"Picture two planks whose grain still shows through the glue.","cn":"想象两块木板，木纹仍透过胶层看得见。"},{"en":"Picture a rope pulled tight between two posts and then left there for years.","cn":"想象一根绳在两根柱子间被拉紧，然后留在那里好多年。"},{"en":"Picture strangers who share a delay and leave as friends.","cn":"想象一群陌生人共同经历一次延误，离开时已成朋友。"}]},"examples":[{"en":"Covalent bonding keeps the diamond lattice rigid.","cn":"共价成键使金刚石晶格保持刚性。"},{"en":"The retreat was designed for bonding among the new staff.","cn":"这次集训是为新员工建立凝聚而设计的。"},{"en":"Poor bonding at the seam let moisture into the panel.","cn":"接缝处粘接不佳，让潮气进入了板材。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bond（纽带）+ ing」——正在把两端系起来 → 成键、联结","word":"bonding"},"root":"古诺斯语 band「带子、绳索」→ 英语 bond「纽带、束缚」→ 加 -ing 表过程 → bonding；与英语 bind「捆」同族，更深印欧词根属重构。","sensesIntro":{"en":"Eight senses follow one act: two separate things are fastened into one. The act then serves atoms, named bond types, affection, infancy, teams, glue, factory joints and dentistry.","cn":"八个义项沿同一个动作展开：两样分开的东西被系成一样。这个动作随后用于原子、各类键型、感情、婴儿期、团队、胶水、工厂接合与牙科。"},"semanticMap":{"core":{"en":"CORE IMAGE: two planks glued into one beam, the seam still visible as two lines of grain.","cn":"核心意象：两根木板被胶粘成一根梁，接缝处仍看得见两道木纹。"},"chain":["FASTEN","CHEMICAL LINK","BOND TYPE","AFFECTION","TEAM SPIRIT","ADHESIVE JOINT"],"branches":[{"senses":"01","en":"THE CHEMICAL PROCESS: atoms are fastened into a new unit.","cn":"化学过程：原子被系成一个新单位。"},{"senses":"02","en":"THE NAMED TYPE: a qualifier in front says which kind of fastening is meant.","cn":"命名的类型：前面的限定词说明是哪一种系结。"},{"senses":"03 · 04","en":"AFFECTION: the same act performed between people, from first hour to lifelong trust.","cn":"感情：同一个动作发生在人之间，从出生第一小时到一生的信任。"},{"senses":"05","en":"TEAM SPIRIT: many people fastened into one group that feels like a unit.","cn":"团队精神：许多人被系成一个感觉像整体的群体。"},{"senses":"06 · 07 · 08","en":"MATERIAL JOINTS: glue at home, a station on the line, resin on a tooth.","cn":"材料接合：家里的胶、产线上的工位、牙上的树脂。"}]},"affixes":{"intro":{"en":"Bonding has no Latin inside it: a Norse noun, an English verb of the same family and an English process ending.","cn":"bonding 里面没有拉丁语：一个诺斯语名词、一个同族的英语动词，加一个英语过程词尾。"},"latinIntro":{"en":"There is no Latin entry behind this word. The whole family is Germanic, and the nearest Latin words for tying, such as ligare, belong to unrelated lines.","cn":"这个词背后没有拉丁词条。整个词族属于日耳曼语，拉丁语中表示「捆绑」的词（如 ligare）属于无关的另一条线。"},"items":[{"word":"bond","structure":"Old Norse band (cord, tie)","meaning":"a tie; to tie","meaningCN":"纽带；系结","example":"The noun and the verb share one form in English.","exampleCN":"名词与动词在英语中同形。"},{"word":"bind","structure":"Old English bindan (to tie)","meaning":"to tie, fasten","meaningCN":"捆；系紧","example":"Bind and bond grew from the same Germanic stock.","exampleCN":"bind 与 bond 出自同一日耳曼语源。"},{"word":"band","structure":"Old Norse band (strip, cord)","meaning":"a strip that ties","meaningCN":"用于捆扎的带子","example":"A band is the visible object behind a bond.","exampleCN":"带子是纽带背后那个看得见的物件。"},{"word":"-ing","structure":"Old English -ung, -ing (process ending)","meaning":"the act or process of","meaningCN":"……的动作或过程","example":"The ending turns bond into the act of bonding.","exampleCN":"这个词尾把 bond 变成「结合」这一动作。"},{"word":"bonding","structure":"bond plus -ing","meaning":"the process of joining","meaningCN":"结合的过程","example":"Hydrogen bonding holds the strands together.","exampleCN":"氢键作用把两条链维系在一起。"},{"word":"bonded","structure":"bond plus -ed (past participle)","meaning":"joined; secured","meaningCN":"已接合的；受监管的","example":"The bonded panels resist separation.","exampleCN":"已黏合的板材不易分开。"},{"word":"bonder","structure":"bond plus -er (agent or tool)","meaning":"one that bonds, or a bonding machine","meaningCN":"执行黏合的人或设备","example":"The bonder presses the two sheets for a minute.","exampleCN":"黏合机把两张板压一分钟。"},{"word":"bondable","structure":"bond plus -able (can be)","meaning":"able to be bonded","meaningCN":"可黏合的","example":"Not every plastic is bondable without treatment.","exampleCN":"并非每种塑料不经处理就可黏合。"},{"word":"binder","structure":"bind plus -er (agent or tool)","meaning":"a substance or machine that holds things together","meaningCN":"把东西固定住的材料或机器","example":"The binder in the paint holds the pigment.","exampleCN":"漆里的黏合剂把颜料固定住。"}],"latinEntries":[],"derivatives":[{"word":"bond","pos":"n./v.","zh":"纽带；债券；结合"},{"word":"bonded","pos":"adj.","zh":"已黏合的"},{"word":"bonder","pos":"n.","zh":"黏合设备"},{"word":"bondable","pos":"adj.","zh":"可黏合的"},{"word":"binder","pos":"n.","zh":"黏合剂；装订机"}]}},{"word":"chemical bond","ipa_uk":"/ˈkemɪkl bɒnd/","ipa_us":"/ˈkemɪkl bɑːnd/","definition_zh":"化学键；把原子结合在一起的作用力","definition_en":"the force that holds atoms together in a molecule, crystal or compound","core_image":"两个小球之间一根被拉紧的短杆，把两端固定成一个整体","scene":"两个小球之间一根被拉紧的短杆，把两端固定成一个整体。A chemical bond holds the two atoms together in the molecule.","sceneCN":"这里 chemical bond 指把原子维系在一起的作用力（第 1 个义项：原子间形成稳定连接的力量）；句意：一条化学键把分子中的两个原子结合在一起。图中可辨识物件：两个小球、短杆、绷紧的连线、整体支架。","pos":[{"tag":"n.","zh":"化学键；原子间的结合力"}],"collocations":[{"phrase":"chemical bond formation","zh":"化学键的形成"},{"phrase":"chemical bond energy","zh":"化学键能"},{"phrase":"chemical bond length","zh":"化学键长"},{"phrase":"double chemical bond","zh":"双键"},{"phrase":"break a chemical bond","zh":"断裂化学键"},{"phrase":"chemical bond type","zh":"化学键类型"}],"forms":[{"label":"复数","form":"chemical bonds"},{"label":"名词（键）","form":"bond"},{"label":"过程名词（成键）","form":"bonding"},{"label":"形容词（化学的）","form":"chemical"},{"label":"名词（化学）","form":"chemistry"}],"derivatives":[{"word":"bond","pos":"n./v.","zh":"键；纽带；结合"},{"word":"bonding","pos":"n.","zh":"成键；联结"},{"word":"bonded","pos":"adj.","zh":"已结合的"},{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemistry","pos":"n.","zh":"化学"}],"senses":[{"no":"01","title":"The force holding atoms together","titleCN":"把原子维系在一起的作用力","definition":"the attraction that keeps atoms joined in a stable arrangement","definitionCN":"使原子保持在稳定排布中的吸引力","example":"A chemical bond holds the two atoms together in the molecule.","exampleCN":"一条化学键把分子中的两个原子结合在一起。","why":"the phrase names the tie itself, the thing that remains while the atoms stay put.","whyCN":"这个短语命名的正是那条纽带，即在原子不动时仍然存在的那个东西。"},{"no":"02","title":"A covalent bond","titleCN":"共价键","definition":"a bond formed by two atoms sharing a pair of electrons","definitionCN":"两个原子共享一对电子而形成的键","example":"Each covalent chemical bond in methane shares one pair of electrons.","exampleCN":"甲烷中的每条共价键共享一对电子。","why":"the general phrase narrows by qualifier, and the shared-electron case is the commonest one taught first.","whyCN":"通称靠限定词收窄，而共享电子这一情形是最先教授、也最常见的一种。"},{"no":"03","title":"An ionic bond","titleCN":"离子键","definition":"a bond formed by the attraction between oppositely charged ions","definitionCN":"由带相反电荷的离子相互吸引而形成的键","example":"The ionic chemical bond in salt breaks when the crystal dissolves.","exampleCN":"盐中的离子键在晶体溶解时断开。","why":"when electrons are transferred rather than shared, the resulting attraction is still called a bond, so the phrase covers it.","whyCN":"当电子被转移而非共享时，由此产生的吸引仍被称为键，因此这个短语也涵盖它。"},{"no":"04","title":"A metallic bond","titleCN":"金属键","definition":"a bond in which metal cations are held by a shared sea of electrons","definitionCN":"金属阳离子被共享的电子海维系的键","example":"A metallic chemical bond lets the metal bend without breaking.","exampleCN":"金属键使金属可以弯曲而不断裂。","why":"metals need a third model, and the general phrase with a qualifier carries it like the other two.","whyCN":"金属需要第三种模型，带限定词的通称像前两种一样承载它。"},{"no":"05","title":"A hydrogen bond","titleCN":"氢键","definition":"a weak attraction between a hydrogen atom and a nearby electronegative atom","definitionCN":"氢原子与邻近电负性原子之间的弱吸引","example":"A hydrogen chemical bond between the strands is weak but numerous.","exampleCN":"两条链之间的氢键虽弱，数量却多。","why":"weaker links are still called bonds in chemistry, and the qualifier keeps them distinct from the strong kinds.","whyCN":"较弱的连接在化学中仍称键，限定词使它们与强键区分开。"},{"no":"06","title":"The drawn line for a bond","titleCN":"结构式中表示键的短线","definition":"the short line in a structural formula that stands for a bond","definitionCN":"结构式中代表一条键的短线","example":"A double chemical bond is drawn as two short parallel lines.","exampleCN":"双键画成两条平行的短线。","why":"the mark takes the name of the thing it marks, a familiar shift from object to symbol.","whyCN":"标记取用了被标记之物的名字，这是从实物到符号的常见转义。"},{"no":"07","title":"Bond length and energy as properties","titleCN":"键长、键能等属性","definition":"the measurable features of a bond, such as its length, strength and energy","definitionCN":"键可测量的特征，如长度、强度与能量","example":"The chemical bond energy tells you how much heat is released.","exampleCN":"化学键能告诉你释放了多少热。","why":"once a bond is treated as an object, it can be measured, and the phrase then carries those measurements.","whyCN":"一旦键被当作对象，它就可以被测量，这个短语于是承载这些测量值。"},{"no":"08","title":"A strong tie between people","titleCN":"比喻：人与人之间牢固的联结","definition":"figuratively, a strong and hard-to-break connection between people","definitionCN":"比喻用法，指人与人之间牢固、难以拆开的联系","example":"Years of shared work formed a chemical bond between the two researchers.","exampleCN":"多年共事在两位研究者之间形成了一种牢固的联结。","why":"the metaphor works because a chemical bond is exactly what is hard to break, a usage that remains clearly figurative.","whyCN":"这个比喻之所以成立，正因为化学键恰恰是难以拆断的东西；此用法仍明显是比喻。"}],"etymology":{"intro":{"en":"The phrase joins chemical, which descends through Medieval Latin from the alchemy word, and bond, a Norse noun meaning a cord. The two halves have different origins. Dates are approximate.","cn":"这个短语把 chemical（经中世纪拉丁语上溯炼金术一词）与 bond（意为绳索的诺斯语名词）组合起来。两半来源不同。年代均为约数。"},"items":[{"era":"ALCHEMY TO CHEMICAL","en":"Chemical descends from Medieval Latin chymicus and alchimia, the alchemy word of disputed pre-Greek origin.","cn":"chemical 上溯中世纪拉丁语 chymicus 与 alchimia，即那个希腊语之前来源有争议的炼金术词。"},{"era":"OLD NORSE BAND","en":"Bond comes from Old Norse band, a cord or shackle, and is related to English bind; it has no Latin ancestor.","cn":"bond 出自古诺斯语 band「绳、镣铐」，与英语 bind 同族；它没有拉丁语祖先。"},{"era":"BOND IN ENGLISH","en":"English bond first named a restraint and then a promise sealed by one, which is how the financial sense arose.","cn":"英语 bond 先指束缚，再指以此封存的承诺，金融义即由此而来。"},{"era":"ATOMS LINKED","en":"Nineteenth-century chemists spoke of the bond between atoms once valence theory showed that atoms combine in fixed ratios.","cn":"当价键理论表明原子按固定比例结合后，19 世纪的化学家开始谈论原子之间的键。"},{"era":"MODERN BOND TYPES","en":"Twentieth-century quantum chemistry sorted bonds into covalent, ionic, metallic and weak kinds, all still called chemical bonds.","cn":"20 世纪的量子化学把键分为共价、离子、金属与弱作用等类型，它们仍统称化学键。"},{"era":"SOURCE UNCERTAIN","en":"Source uncertain (half of the phrase): the deeper origin of the alchemy word behind chemical is disputed, while bond is securely Germanic; only the first half carries this uncertainty.","cn":"来源不确定（短语的一半）：chemical 背后那个炼金术词的更深来源有争议，而 bond 确属日耳曼语；这种不确定性只在短语的前一半。"}]},"similar":{"note":{"en":"The first group is the bond family in its other shapes; the second group names related links and the general idea of attraction.","cn":"第一组是 bond 词族的其他形态；第二组是相关的连接说法与「吸引」这一总体概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bond","ipa":"/bɒnd/","tag":"same word, unqualified","definition":"The bare noun can mean a tie between people, a financial instrument or a bond between atoms; chemical narrows it.","definitionCN":"不带限定的名词可指人际纽带、金融债券或原子间的键；chemical 使它收窄。"},{"word":"bonding","ipa":"/ˈbɒndɪŋ/","tag":"process, not thing","definition":"The forming of bonds; the chemical bond is the link that results, not the activity of making it.","definitionCN":"指成键的过程；化学键是形成后的连接，而不是形成这一活动。"},{"word":"chemical","ipa":"/ˈkemɪkl/","tag":"first half alone","definition":"The adjective and noun of chemistry; on its own it says nothing about a tie between atoms.","definitionCN":"化学的形容词与名词；单独使用不涉及原子间的连接。"},{"word":"chemically","ipa":"/ˈkemɪkli/","tag":"adverb, different job","definition":"The adverb of viewpoint or method; it cannot replace the noun phrase in a sentence about atoms.","definitionCN":"表示视角或方法的副词；在谈论原子的句子里不能替代这个名词短语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"attraction","ipa":"/əˈtrækʃn/","tag":"general pull","definition":"The general pull between particles; a bond is the stable result of that pull, not the pull itself.","definitionCN":"粒子间一般的拉力；键是这种拉力稳定后的结果，而非拉力本身。"},{"word":"linkage","ipa":"/ˈlɪŋkɪdʒ/","tag":"connection","definition":"A connection between parts; in chemistry it often names how groups are joined, rather than the force.","definitionCN":"部件之间的连接；在化学中常指基团如何相连，而非那股力。"},{"word":"force","ipa":"/fɔːs/","tag":"physical quantity","definition":"A measurable push or pull; a bond involves forces but is named as the link, not as the force value.","definitionCN":"可测量的推或拉；键涉及力，但命名的是连接，不是力的数值。"},{"word":"cohesion","ipa":"/kəʊˈhiːʒn/","tag":"sticking within a substance","definition":"The holding together of like molecules by weak attraction; it is not a bond between two atoms in a molecule.","definitionCN":"同类分子靠弱吸引聚拢；它不是分子内两原子之间的键。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real source lines, the real word family and real textbook phrases.","cn":"正常联想：两条真实的来源线、真实的同族词与真实的教科书说法。"},"normal":[{"en":"Chemical is the adjective of chemistry; bond is a cord. Together they name the cord between atoms.","cn":"chemical 是化学的形容词，bond 是一根绳；合起来就是原子之间的那根绳。"},{"en":"The family runs bond, bonding, bonded, chemical and chemistry.","cn":"同族词有 bond、bonding、bonded、chemical 与 chemistry。"},{"en":"Fixed phrases mark the measurements: bond length, bond energy, bond type.","cn":"固定搭配标出测量项：键长、键能、键型。"},{"en":"Qualifiers do the sorting: covalent, ionic, metallic and hydrogen bonds.","cn":"限定词负责分类：共价键、离子键、金属键、氢键。"},{"en":"Breaking a bond costs energy; forming one releases it, which is why bond energy is always discussed with heat.","cn":"断键要耗能，成键会放能，所以键能总与热一起讨论。"}],"abstract":[{"en":"Picture two beads held apart by a taut rod that neither can escape.","cn":"想象两颗珠子被一根绷紧的短杆撑住，谁也逃不开。"},{"en":"Picture a line drawn between two dots on a page, standing for a force nobody can see.","cn":"想象纸上两点之间画的一条线，代表一股谁也看不见的力。"},{"en":"Picture two colleagues who finish each other's sentences after years of work.","cn":"想象两位同事多年共事后，能接上对方没说完的话。"}]},"examples":[{"en":"The chemical bond in nitrogen is strong enough to make the gas inert.","cn":"氮气中的化学键足够强，使这种气体不活泼。"},{"en":"Ultraviolet light can break a chemical bond in the pigment.","cn":"紫外光能断开颜料中的一条化学键。"},{"en":"Students drew every chemical bond in the formula before naming the shape.","cn":"学生们先画出式中每条化学键，再给形状命名。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「chemical（化学的）+ bond（纽带）」——原子之间那条化学的绳 → 化学键","word":"chemical bond"},"root":"chemical 上溯中世纪拉丁 chymicus / alchimia（炼金术词，希腊语之前来源有争议）；bond 出自古诺斯语 band「绳、镣铐」，与 bind 同族，无拉丁祖先。","sensesIntro":{"en":"Eight senses follow one link: two atoms are tied together. The link is then sorted into shared-electron, transferred-electron, metallic and weak kinds, drawn as a line, measured as energy, and finally borrowed for a human tie.","cn":"八个义项沿同一条连接展开：两个原子被系在一起。这条连接随后分为共享电子、转移电子、金属与弱作用等类型，被画成一条线、被测量为能量，最后借用于人与人之间的纽带。"},"semanticMap":{"core":{"en":"CORE IMAGE: two beads fixed at either end of a taut rod, one whole instead of two parts.","cn":"核心意象：两颗珠子固定在绷紧短杆的两端，成为一体而非两件。"},"chain":["TIE BETWEEN ATOMS","COVALENT","IONIC","METALLIC","WEAK LINK","MEASURED PROPERTY"],"branches":[{"senses":"01","en":"THE TIE ITSELF: whatever keeps the atoms in place once they are joined.","cn":"纽带本身：原子结合之后使它们留在原位的那个东西。"},{"senses":"02 · 03","en":"SHARED OR TRANSFERRED: electrons either travel together or move across.","cn":"共享或转移：电子要么同行，要么换边。"},{"senses":"04 · 05","en":"SEA AND GLUE: a metal holds its ions in a shared sea, while a hydrogen link is weak but numerous.","cn":"电子海与胶水：金属把离子浸在共享的电子海里，氢键则弱而多。"},{"senses":"06 · 07","en":"PICTURE AND NUMBER: a line on the page, and a length or energy to measure.","cn":"图与数：纸上的一条线，以及可测量的长度或能量。"},{"senses":"08","en":"HUMAN TIE: the same word for a friendship that is hard to break.","cn":"人的纽带：同一个词也用于难以拆断的友谊。"}]},"affixes":{"intro":{"en":"The phrase is half borrowed Latin and half Germanic: an adjective of the chemistry family in front, a Norse noun behind.","cn":"这个短语一半是借入的拉丁语，一半是日耳曼语：前面是化学词族的形容词，后面是诺斯语名词。"},"latinIntro":{"en":"Only the first half has Latin entries, through chymicus and alchimia; bond itself is Germanic and has none.","cn":"只有前一半有拉丁词条，经 chymicus 与 alchimia；bond 本身属日耳曼语，没有拉丁词条。"},"items":[{"word":"chem-","structure":"bound stem from alchimia","meaning":"the art of substances","meaningCN":"关于物质的技艺","example":"The stem serves the whole chemistry family.","exampleCN":"这个词干服务整个化学词族。"},{"word":"-ical","structure":"-icus through Latin and French","meaning":"relating to","meaningCN":"与……有关的","example":"The ending makes chemical an adjective.","exampleCN":"这个词尾把 chemical 变成形容词。"},{"word":"chemical","structure":"chem- plus -ical","meaning":"relating to chemistry","meaningCN":"与化学有关的","example":"A chemical bond is a link studied by chemistry.","exampleCN":"化学键是化学研究的一种连接。"},{"word":"bond","structure":"Old Norse band (cord, tie)","meaning":"a tie; to tie","meaningCN":"纽带；系结","example":"Bond is the noun that carries the image of a cord.","exampleCN":"bond 是承载绳索意象的那个名词。"},{"word":"chemical bond","structure":"chemical plus bond","meaning":"the tie between atoms","meaningCN":"原子之间的连接","example":"A chemical bond holds the atoms together.","exampleCN":"化学键把原子维系在一起。"},{"word":"bonding","structure":"bond plus -ing","meaning":"the forming of bonds","meaningCN":"成键的过程","example":"Bonding releases energy.","exampleCN":"成键会释放能量。"},{"word":"bonded","structure":"bond plus -ed","meaning":"joined by a bond","meaningCN":"由键结合的","example":"Bonded atoms sit at fixed distances.","exampleCN":"成键的原子保持固定距离。"},{"word":"bind","structure":"Old English bindan","meaning":"to tie","meaningCN":"捆；系","example":"Bind and bond share a Germanic origin.","exampleCN":"bind 与 bond 共享一个日耳曼语来源。"},{"word":"binder","structure":"bind plus -er","meaning":"something that holds parts together","meaningCN":"把部件固定的东西","example":"A binder keeps the powder in shape.","exampleCN":"黏合剂使粉末保持形状。"}],"latinEntries":[{"word":"chymicus","structure":"chymicus (adj., medieval Latin)","meaning":"chemical","meaningCN":"化学的"},{"word":"alchimia","structure":"alchimia, alchimiae (f., first declension)","meaning":"alchemy","meaningCN":"炼金术"}],"derivatives":[{"word":"bond","pos":"n./v.","zh":"键；纽带；结合"},{"word":"bonding","pos":"n.","zh":"成键"},{"word":"bonded","pos":"adj.","zh":"已结合的"},{"word":"chemical","pos":"adj./n.","zh":"化学的；化学制品"},{"word":"chemistry","pos":"n.","zh":"化学"}]}},{"word":"covalent","ipa_uk":"/ˌkəʊˈveɪlənt/","ipa_us":"/ˌkoʊˈveɪlənt/","definition_zh":"共价的；由原子共享电子对而形成的","definition_en":"describing a bond in which two atoms share one or more pairs of electrons","core_image":"两只手各伸出一半，握住同一根绳，绳由两边共同持有","scene":"两个人各用一只手握住同一根绳的中段，绳身由两边共同持有。Two atoms share a pair of electrons in a covalent bond.","sceneCN":"这里 covalent 指原子共享电子对而形成键的（第 1 个义项：以共享电子对为特征的键合）；句意：在共价键中两个原子共享一对电子。图中可辨识物件：一根绳、两只手、共同握住的绳段、绷紧的绳尾。","pos":[{"tag":"adj.","zh":"共价的；共享电子对的"}],"collocations":[{"phrase":"covalent bond","zh":"共价键"},{"phrase":"covalent compound","zh":"共价化合物"},{"phrase":"covalent radius","zh":"共价半径"},{"phrase":"covalent crystal","zh":"共价晶体"},{"phrase":"covalent modification","zh":"共价修饰"},{"phrase":"covalent cross-linking","zh":"共价交联"}],"forms":[{"label":"原级","form":"covalent"},{"label":"比较级（较少用）","form":"more covalent"},{"label":"最高级（较少用）","form":"most covalent"},{"label":"副词","form":"covalently"},{"label":"名词（共价）","form":"covalence"}],"derivatives":[{"word":"covalence","pos":"n.","zh":"共价；共价性"},{"word":"covalently","pos":"adv.","zh":"以共价方式"},{"word":"valence","pos":"n.","zh":"价；化合价"},{"word":"valency","pos":"n.","zh":"化合价（英式常用）"},{"word":"ionic","pos":"adj.","zh":"离子的；离子键的"}],"senses":[{"no":"01","title":"Sharing electrons in a bond","titleCN":"键中共享电子","definition":"describing a bond formed by two atoms sharing one or more pairs of electrons","definitionCN":"指两个原子共享一对或多对电子而形成的键","example":"Two atoms share a pair of electrons in a covalent bond.","exampleCN":"在共价键中两个原子共享一对电子。","why":"co- means together and the stem means strength or worth, so the word says that the two atoms hold the link jointly.","whyCN":"前缀表示「共同」，词干表示「力量、价值」，因此这个词说的是两个原子共同持有这条连接。"},{"no":"02","title":"Of a covalently bonded compound","titleCN":"由共价键构成的化合物","definition":"describing a compound whose atoms are joined mainly by shared-electron bonds","definitionCN":"指原子主要由共享电子键连接的化合物","example":"Carbon dioxide is a covalent compound with no ions in it.","exampleCN":"二氧化碳是一种共价化合物，其中没有离子。","why":"the adjective transferred from the bond to the whole substance that such bonds build.","whyCN":"这个形容词从键转移到由这类键构成的整个物质。"},{"no":"03","title":"Covalent radius","titleCN":"共价半径","definition":"describing the share of a bond length assigned to one atom when two atoms are joined covalently","definitionCN":"指共价相连时分配给单个原子的那部分键长","example":"The covalent radius of chlorine is smaller than that of bromine.","exampleCN":"氯的共价半径小于溴的共价半径。","why":"once bond lengths were measured, a half-length could be assigned to each atom, and the adjective marked that convention.","whyCN":"键长可测之后，便可把一半长度分配给每个原子，这个形容词标记的正是这一约定。"},{"no":"04","title":"Covalent crystal","titleCN":"共价晶体","definition":"describing a solid held together in three dimensions by a continuous network of shared-electron bonds","definitionCN":"指由共享电子键的连续网络在三维上维系的固体","example":"Diamond is a covalent crystal, which is why it scratches almost anything.","exampleCN":"金刚石是共价晶体，所以它几乎能划伤任何东西。","why":"when the same bond repeats through a whole solid, the adjective moves from one link to the entire lattice.","whyCN":"当同一种键贯穿整块固体重复出现，这个形容词便从一条连接转到整个晶格。"},{"no":"05","title":"Covalent modification in biochemistry","titleCN":"生物化学中的共价修饰","definition":"describing a permanent chemical attachment of a group to a molecule, as in enzyme regulation","definitionCN":"指某基团被化学性地永久接到分子上，如酶活性调节","example":"Phosphorylation is a covalent modification that switches the enzyme on.","exampleCN":"磷酸化是一种共价修饰，能开启这种酶。","why":"biology borrowed the adjective for changes made by forming a real bond rather than by weak association.","whyCN":"生物学借这个形容词指通过形成真实键、而非弱结合所造成的改变。"},{"no":"06","title":"Covalent catalysis","titleCN":"共价催化","definition":"describing an enzyme mechanism in which a temporary covalent bond forms between enzyme and substrate","definitionCN":"指酶与底物暂时形成共价键的催化机制","example":"The protease uses covalent catalysis to cut the peptide chain.","exampleCN":"这种蛋白酶通过共价催化切断肽链。","why":"the mechanism is named by the kind of bond it uses, an ordinary extension of the adjective into a technique.","whyCN":"这种机制以它所用的键型命名，是形容词向技术名称的普通延伸。"},{"no":"07","title":"Covalent cross-linking","titleCN":"共价交联","definition":"describing permanent links formed between polymer chains to fix a network in place","definitionCN":"指聚合物链之间形成的永久连接，使网络固定","example":"Covalent cross-linking makes the hydrogel keep its shape in water.","exampleCN":"共价交联使水凝胶在水中保持形状。","why":"materials science describes a network by the kind of links that hold it, so the adjective precedes the joining.","whyCN":"材料科学以维系网络的连接种类来描述网络，因此这个形容词放在「连接」之前。"},{"no":"08","title":"Covalent character in a bond","titleCN":"键中的共价成分","definition":"describing the degree to which a bond that is formally ionic still shares electrons","definitionCN":"指形式上是离子键、实际仍共享电子的程度","example":"The bond in hydrogen chloride has substantial covalent character.","exampleCN":"氯化氢中的键有相当大的共价成分。","why":"since real bonds fall between two extremes, the adjective became a measure of how far a bond leans toward sharing.","whyCN":"由于真实的键处在两个极端之间，这个形容词便成为衡量键偏向共享程度的量。"}],"etymology":{"intro":{"en":"Covalent is a modern compound of co-, from Latin com-, together, and valent, from Latin valens, being strong or being worth. It was coined in English in the early twentieth century. Dates are approximate.","cn":"covalent 是现代复合词，由 co-（出自拉丁 com-「共同」）与 valent（出自拉丁 valens「有力量、有价值」）构成。它在 20 世纪初由英语造出。年代均为约数。"},"items":[{"era":"LATIN VALERE","en":"Valere meant to be strong, to be well, to be worth; it also supplied value and valid. Its Indo-European connections are reconstructions.","cn":"valere 意为「有力量、健康、有价值」，还给出 value 与 valid。它的印欧语联系属于重构。"},{"era":"LATIN VALENS","en":"The present participle valens, strong or worth, produced English words in -valent and the noun valentia, strength or capacity.","cn":"现在分词 valens「有力量的、有价值的」产生了英语中以 -valent 结尾的词，以及名词 valentia「力量、容量」。"},{"era":"LATIN COM-","en":"Com-, together, assimilates to co- before vowels and to col-, cor- and con- before certain consonants, a pattern visible across the family.","cn":"com-「共同」在元音前同化为 co-，在某些辅音前同化为 col-、cor-、con-，这一模式在整个词族中可见。"},{"era":"ENGLISH VALENCE","en":"Nineteenth-century chemistry took valence from Latin valentia for the combining capacity of an atom, the quantity that covalent later qualified.","cn":"19 世纪的化学从拉丁 valentia 取来 valence，指原子的化合能力，也就是 covalent 后来所限定的那个量。"},{"era":"COINED COVALENT","en":"Covalent and covalence were coined in the early twentieth century, when chemists needed a word for bonds based on shared electrons; the term is recorded from 1919.","cn":"covalent 与 covalence 于 20 世纪初被造出，当时化学家需要一个词来指以共享电子为基础的键；该词自 1919 年有记录。"},{"era":"FIRST DATE","en":"First date uncertain: the coinage belongs to the early twentieth century, but the earliest printed use is not fully settled, so the date given is approximate.","cn":"首见年代不确定：这个新造词属于 20 世纪初，但最早的印刷用例尚无完全定论，因此给出的年代只是约数。"}]},"similar":{"note":{"en":"The first group shares the valere stem and is easily mixed up; the second group names the other bond types and the qualities used to contrast them.","cn":"第一组共享 valere 词干，极易混淆；第二组是其他键型以及用于对照的性质。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"covalence","ipa":"/ˌkəʊˈveɪləns/","tag":"same stem, noun","definition":"The noun for the sharing itself; covalent is the adjective that describes a bond of this kind.","definitionCN":"指「共享」这一性质的名词；covalent 是描述这类键的形容词。"},{"word":"valence","ipa":"/ˈveɪləns/","tag":"same stem, quantity","definition":"The combining capacity of an atom, a number; sharing electrons is one way of satisfying it, not the same thing.","definitionCN":"指原子的化合能力，是一个数；共享电子是满足它的一种方式，并不等同。"},{"word":"valency","ipa":"/ˈveɪlənsi/","tag":"same stem, British form","definition":"The British variant of valence; it is a count, while covalent describes the kind of link.","definitionCN":"valence 的英式变体；它是计数，而 covalent 描述连接种类。"},{"word":"valiant","ipa":"/ˈvæliənt/","tag":"same root, different sense","definition":"Also from valere, but it describes bravery rather than combining power; the shared root does not make it a chemistry word.","definitionCN":"同样出自 valere，但描述勇敢而非化合能力；共享词根并不使它成为化学词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ionic","ipa":"/aɪˈɒnɪk/","tag":"contrasting bond type","definition":"Describing bonds made by electron transfer and electrostatic attraction, the usual opposite of covalent in teaching.","definitionCN":"描述由电子转移与静电吸引形成的键，在教学中通常是 covalent 的对照项。"},{"word":"metallic","ipa":"/məˈtælɪk/","tag":"contrasting bond type","definition":"Describing the shared-electron sea of metals, a third arrangement beside covalent and ionic.","definitionCN":"描述金属共享电子海的结构，是与共价、离子并列的第三种安排。"},{"word":"polar","ipa":"/ˈpəʊlə/","tag":"unequal sharing","definition":"Describing a covalent bond whose electrons are shared unequally; it is a variety of covalent, not its opposite.","definitionCN":"描述电子共享不均的共价键；它是共价的一种，而非其反面。"},{"word":"molecular","ipa":"/məˈlekjələ/","tag":"resulting scale","definition":"Describing matter made of molecules, which covalent bonds commonly build; it names the product, not the link.","definitionCN":"描述由分子构成的物质，共价键常构成这类物质；它命名产物，而非连接。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin verb, the real prefix pattern and real laboratory phrases.","cn":"正常联想：真实的拉丁动词、真实的前缀同化模式与真实的实验室说法。"},"normal":[{"en":"Co- together plus valent strength: two atoms hold the bond jointly, each contributing an electron.","cn":"co-「共同」加 valent「力量」：两个原子共同持有这条键，各自出一个电子。"},{"en":"The family runs covalent, covalence, covalently, valence and valency.","cn":"同族词有 covalent、covalence、covalently、valence 与 valency。"},{"en":"Fixed phrases mark the applications: covalent bond, covalent crystal, covalent modification.","cn":"固定搭配标出应用：共价键、共价晶体、共价修饰。"},{"en":"Co- is the assimilated form of com-, the same prefix heard in cooperate and connect.","cn":"co- 是 com- 的同化形式，与 cooperate、connect 中的前缀相同。"},{"en":"Covalent and ionic are taught as a pair: sharing against transferring.","cn":"covalent 与 ionic 总成对教授：共享对转移。"}],"abstract":[{"en":"Picture two hands on one rope, neither letting go.","cn":"想象两只手握着同一根绳，谁都不松。"},{"en":"Picture a pair of dancers who own the same step between them.","cn":"想象一对舞者，彼此之间共有同一个舞步。"},{"en":"Picture a fence whose two owners both pay for the same post.","cn":"想象一道篱笆，两户人家都为同一根柱子出钱。"}]},"examples":[{"en":"Water molecules are held together by polar covalent bonds.","cn":"水分子由极性共价键维系在一起。"},{"en":"The two elements form a covalent compound rather than a salt.","cn":"这两种元素形成共价化合物，而不是盐。"},{"en":"Enzymes often make a temporary covalent intermediate.","cn":"酶常常形成暂时的共价中间体。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「co（共同）+ valent（力量）」——两边共同出力握住同一条键 → 共价的","word":"covalent"},"root":"拉丁 valere「有力量、有价值」→ valens「有力量的」→ valentia「力量、容量」→ 英语 valence「化合价」；加 com-（同化为 co-「共同」）→ 20 世纪初造出 covalent「共价的」。","sensesIntro":{"en":"Eight senses follow one arrangement: two atoms hold the same electrons between them. The arrangement then names a compound, a radius, a crystal, a biochemical attachment, a catalytic trick, a cross-link and finally the degree of sharing inside an ionic bond.","cn":"八个义项沿同一种安排展开：两个原子在彼此之间共同持有同一对电子。这种安排随后命名一种化合物、一种半径、一种晶体、一种生化连接、一种催化手法、一种交联，最后是离子键内部的共享程度。"},"semanticMap":{"core":{"en":"CORE IMAGE: two hands gripping the middle of one rope, so that neither holds it alone.","cn":"核心意象：两只手各握住一根绳的中段，谁也不是独自持有。"},"chain":["SHARE ELECTRONS","SHARED BOND","COVALENT COMPOUND","MEASURED RADIUS","CRYSTAL NETWORK","PARTIAL SHARING"],"branches":[{"senses":"01","en":"THE SHARING ITSELF: one pair of electrons belongs to two atoms at once.","cn":"共享本身：一对电子同时属于两个原子。"},{"senses":"02","en":"THE SUBSTANCE: a whole compound built by such sharing, with no ions.","cn":"物质：由这种共享构成、不含离子的整个化合物。"},{"senses":"03 · 04","en":"MEASURE AND REPEAT: half a bond length becomes a radius, and a repeated bond becomes a crystal.","cn":"测量与重复：半个键长成为半径，重复的键成为晶体。"},{"senses":"05 · 07","en":"PERMANENT ATTACHMENT: groups fixed onto molecules, and chains locked into a network.","cn":"永久连接：基团被固定到分子上，链被锁进网络。"},{"senses":"06 · 08","en":"MECHANISM AND DEGREE: a temporary bond used by an enzyme, and how much sharing an ionic bond really has.","cn":"机理与程度：酶所用的暂时键，以及离子键实际的共享程度。"}]},"affixes":{"intro":{"en":"Covalent is a textbook modern compound: a Latin prefix, a Latin participle stem and an English ending, all transparent.","cn":"covalent 是教科书式的现代复合词：拉丁前缀、拉丁分词词干与英语词尾，全都透明可读。"},"latinIntro":{"en":"Latin valere and valens supply the stem, and com- supplies the prefix; no single Latin word covalent exists, because the compound was made in English.","cn":"拉丁语 valere 与 valens 提供词干，com- 提供前缀；拉丁语中并不存在 covalent 这一单词，因为它是英语造的复合词。"},"items":[{"word":"co-","structure":"com- (Latin prefix, together), assimilated","meaning":"together; jointly","meaningCN":"共同；一起","example":"The prefix says the two atoms hold the link jointly.","exampleCN":"这个前缀说明两个原子共同持有这条键。"},{"word":"valere","structure":"valere, valui, valitum (Latin verb, second conjugation)","meaning":"to be strong, be worth","meaningCN":"有力量；有价值","example":"The verb supplies the idea of capacity or worth.","exampleCN":"这个动词提供「容量、价值」的意思。"},{"word":"valens","structure":"present participle of valere","meaning":"being strong; having capacity","meaningCN":"有力量的；有容量的","example":"The participle is the source of the -valent ending.","exampleCN":"这个分词是 -valent 词尾的来源。"},{"word":"valentia","structure":"valentia, valentiae (f., first declension)","meaning":"strength; capacity","meaningCN":"力量；容量","example":"The noun became the chemical term for combining capacity.","exampleCN":"这个名词成了表示化合能力的化学术语。"},{"word":"valence","structure":"valentia through French and German chemistry","meaning":"combining capacity of an atom","meaningCN":"原子的化合能力","example":"Carbon has a valence of four in most compounds.","exampleCN":"碳在多数化合物中化合价为四。"},{"word":"covalent","structure":"co- plus valent","meaning":"sharing electrons in a bond","meaningCN":"在键中共享电子","example":"A covalent bond holds the two hydrogen atoms together.","exampleCN":"一条共价键把两个氢原子结合在一起。"},{"word":"covalence","structure":"co- plus valence","meaning":"the state of sharing electrons","meaningCN":"共享电子的状态","example":"Covalence is the noun behind the adjective.","exampleCN":"covalence 是形容词背后的名词。"},{"word":"covalently","structure":"covalent plus -ly (adverb)","meaning":"by covalent bonding","meaningCN":"以共价键方式","example":"The drug is covalently attached to the protein.","exampleCN":"这种药以共价方式接到蛋白质上。"},{"word":"valency","structure":"valence plus -y (British variant)","meaning":"combining capacity","meaningCN":"化合价","example":"Valency is counted in bonds, not in electrons alone.","exampleCN":"化合价按键计数，而不只是按电子计数。"},{"word":"ionic","structure":"ion plus -ic, the contrasting type","meaning":"bonded by charged ions","meaningCN":"由带电离子成键的","example":"Ionic and covalent bonds are taught as two extremes.","exampleCN":"离子键与共价键被当作两个极端来教。"}],"latinEntries":[{"word":"valere","structure":"valere, valui, valitum (verb, second conjugation)","meaning":"to be strong, be worth","meaningCN":"有力量；有价值"},{"word":"valens","structure":"valens, valentis (present participle)","meaning":"strong; having capacity","meaningCN":"有力量的；有容量的"},{"word":"valentia","structure":"valentia, valentiae (f., first declension)","meaning":"strength; capacity","meaningCN":"力量；容量"}],"derivatives":[{"word":"covalence","pos":"n.","zh":"共价；共价性"},{"word":"covalently","pos":"adv.","zh":"以共价方式"},{"word":"valence","pos":"n.","zh":"化合价"},{"word":"valency","pos":"n.","zh":"化合价（英式）"},{"word":"ionic","pos":"adj.","zh":"离子的"}]}},{"word":"ionic","ipa_uk":"/aɪˈɒnɪk/","ipa_us":"/aɪˈɑːnɪk/","definition_zh":"离子的；离子键的；离子型的；（建筑）爱奥尼亚式的（同形异义）","definition_en":"relating to ions or to bonds formed by electrically charged atoms","core_image":"一正一负两个小球彼此吸住，中间隔着一段空隙","scene":"一正一负两个小球彼此吸住，中间隔着一段空隙。Sodium chloride dissolves because its ionic lattice breaks apart in water.","sceneCN":"这里 ionic 指由带电离子成键的（第 1 个义项：属于离子或离子键的）；句意：氯化钠能溶解，是因为它的离子晶格在水中散开。图中可辨识物件：带正号的小球、带负号的小球、之间的空隙、晶格示意图。","pos":[{"tag":"adj.","zh":"离子的；离子键的；离子型的；爱奥尼亚式的"}],"collocations":[{"phrase":"ionic bond","zh":"离子键"},{"phrase":"ionic compound","zh":"离子化合物"},{"phrase":"ionic liquid","zh":"离子液体"},{"phrase":"ionic radius","zh":"离子半径"},{"phrase":"ionic conduction","zh":"离子导电"},{"phrase":"ionic lattice","zh":"离子晶格"}],"forms":[{"label":"原级","form":"ionic"},{"label":"比较级（较少用）","form":"more ionic"},{"label":"最高级（较少用）","form":"most ionic"},{"label":"副词","form":"ionically"},{"label":"名词（离子）","form":"ion"}],"derivatives":[{"word":"ion","pos":"n.","zh":"离子"},{"word":"ionize","pos":"v.","zh":"电离；使成离子"},{"word":"ionization","pos":"n.","zh":"电离"},{"word":"ionically","pos":"adv.","zh":"以离子方式"},{"word":"anion","pos":"n.","zh":"阴离子"}],"senses":[{"no":"01","title":"Of ions or ionic bonds","titleCN":"属于离子或离子键的","definition":"relating to ions, or to bonds formed by the attraction of oppositely charged ions","definitionCN":"与离子有关，或与带相反电荷的离子相互吸引所形成的键有关","example":"Sodium chloride dissolves because its ionic lattice breaks apart in water.","exampleCN":"氯化钠能溶解，是因为它的离子晶格在水中散开。","why":"the adjective simply attaches the noun ion to whatever it describes, with no figurative shift.","whyCN":"这个形容词只是把名词「离子」接到所修饰之物上，没有比喻转移。"},{"no":"02","title":"Of an ionic compound","titleCN":"离子化合物的","definition":"describing a compound built from cations and anions rather than from molecules","definitionCN":"指由阳离子与阴离子、而非分子构成的化合物","example":"The ionic compound conducts electricity only when molten.","exampleCN":"这种离子化合物只在熔融时才导电。","why":"the adjective moved from the bond to the whole substance those bonds assemble.","whyCN":"这个形容词从键转移到由那些键拼成的整个物质。"},{"no":"03","title":"Of an ionic liquid or surfactant","titleCN":"离子液体或离子型表面活性剂的","definition":"describing materials that are themselves made of ions but behave as liquids or as charged detergents","definitionCN":"指本身由离子构成、却呈液体行为或带电荷去污作用的材料","example":"An ionic liquid can dissolve cellulose without boiling.","exampleCN":"一种离子液体能在不沸腾的情况下溶解纤维素。","why":"industrial chemistry named a new class of materials after their charged makeup, keeping the same adjective.","whyCN":"工业化学按带电构成给一类新材料命名，仍用同一个形容词。"},{"no":"04","title":"Ionic conduction","titleCN":"离子导电","definition":"describing movement of charge carried by ions rather than by electrons","definitionCN":"指由离子而非电子携带电荷的移动","example":"Ionic conduction in the membrane carries the signal along the nerve.","exampleCN":"膜中的离子导电把信号沿神经传下去。","why":"once the charge carriers are ions, the adjective marks that mode of conduction against the electronic one.","whyCN":"当载流子是离子时，这个形容词标记出这种导电方式，以区别于电子导电。"},{"no":"05","title":"Ionic radius","titleCN":"离子半径","definition":"describing the share of a distance assigned to one ion in a crystal","definitionCN":"指晶体中分配给单个离子的那部分距离","example":"The ionic radius of the cation decides how the crystal packs.","exampleCN":"阳离子的离子半径决定晶体如何堆积。","why":"like the covalent radius, this is a measurement convention that uses the adjective to label the species.","whyCN":"与共价半径一样，这是一种测量约定，用这个形容词标记物种。"},{"no":"06","title":"Ionic current in physiology","titleCN":"生理学中的离子流","definition":"describing the flow of ions across a membrane or through a channel","definitionCN":"指离子跨膜或穿过通道的流动","example":"The ionic current through the channel lasts a few milliseconds.","exampleCN":"通过通道的离子流持续几毫秒。","why":"physiology borrowed the adjective for the charged flow that excites nerve and muscle cells.","whyCN":"生理学借这个形容词指使神经与肌肉细胞兴奋的带电流动。"},{"no":"07","title":"The Ionic order in architecture","titleCN":"建筑中的爱奥尼亚柱式","definition":"belonging to the classical order named after Ionia, with scroll-shaped capitals","definitionCN":"属于以爱奥尼亚命名的古典柱式，柱头带涡卷","example":"The porch was built in the ionic style, with volutes on every capital.","exampleCN":"这座门廊按爱奥尼亚式建造，每个柱头都有涡卷。","why":"this is a different word that happens to share the spelling: it comes from Ionia, not from ion.","whyCN":"这是一个恰好拼写相同的另一个词：它出自地名「爱奥尼亚」，而非「离子」。"},{"no":"08","title":"Of Ionia or its dialect","titleCN":"爱奥尼亚及其方言的","definition":"relating to the Greek region of Ionia, its people or its dialect","definitionCN":"与希腊爱奥尼亚地区、其居民或方言有关的","example":"The scholar compared ionic Greek with the Attic dialect.","exampleCN":"这位学者把爱奥尼亚希腊语与阿提卡方言作比较。","why":"the oldest sense of this spelling is geographical, and it survives in histories of Greece and of architecture.","whyCN":"这一拼写最古老的义项是地理的，它存留在希腊史与建筑史中。"}],"etymology":{"intro":{"en":"Ionic has two separate origins behind one spelling: an adjective of ion, the charged particle named by Faraday, and an adjective of Ionia, the Greek region. Dates are approximate.","cn":"同一个拼写背后有两条独立来源：一是 ion（法拉第命名的带电粒子）的形容词，二是地名「爱奥尼亚」的形容词。年代均为约数。"},"items":[{"era":"GREEK IENAI","en":"Ienai meant to go or come; its neuter present participle ion meant a going thing. The deeper Indo-European connections are reconstructions.","cn":"ienai 意为「去、来」，其中性现在分词 ion 意为「正在走的东西」。更早的印欧语联系属于重构。"},{"era":"FARADAY 1834","en":"Michael Faraday coined ion for the charged particles that travel to the electrodes during electrolysis, taking the Greek participle literally.","cn":"法拉第在 1834 年为电解时游向电极的带电粒子造出 ion 一词，字面取用那个希腊分词。"},{"era":"-IC SUFFIX","en":"Greek -ikos, Latin -icus and English -ic form adjectives of relation, so ionic simply means of ions.","cn":"希腊 -ikos、拉丁 -icus 与英语 -ic 构成关系形容词，因此 ionic 就是「离子的」。"},{"era":"IONIA","en":"Ionia was the Greek region on the coast of Asia Minor; Ionic named its people, its dialect and later one of the classical architectural orders.","cn":"爱奥尼亚是小亚细亚沿岸的希腊地区；Ionic 指其居民、方言，后来也指一种古典建筑柱式。"},{"era":"TWO WORDS, ONE SPELLING","en":"The two adjectives are unrelated in origin but identical in English spelling, which is why chemistry and architecture use the same letters for different things.","cn":"这两个形容词来源无关，英语拼写却完全相同，所以化学与建筑用同样的字母表示不同的东西。"},{"era":"FIRST DATE","en":"First date uncertain: the chemical adjective follows Faraday's coinage of 1834, but its earliest printed use is not precisely dated, so the date is approximate.","cn":"首见年代不确定：化学义形容词紧随法拉第 1834 年的造词，但其最早的印刷用例没有确切年代，故年代只是约数。"}]},"similar":{"note":{"en":"The first group is the ion family; the second group is the bond types and charged species that ionic is contrasted with. Note that one look-alike belongs to a different word entirely.","cn":"第一组是 ion 词族；第二组是与 ionic 对照的键型与带电物种。注意其中一个形近词完全属于另一个词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ion","ipa":"/aɪˈɒn/","tag":"same stem, noun","definition":"The charged particle itself; the adjective describes anything made of or involving such particles.","definitionCN":"指带电粒子本身；形容词描述由这类粒子构成或涉及它们的事物。"},{"word":"ionize","ipa":"/ˈaɪənaɪz/","tag":"same stem, verb","definition":"To make an atom or molecule into an ion; it names the act, while ionic names the state or type.","definitionCN":"使原子或分子成为离子；它命名动作，ionic 命名状态或类型。"},{"word":"ionization","ipa":"/ˌaɪənaɪˈzeɪʃn/","tag":"same stem, process noun","definition":"The process of producing ions; it is a noun, and cannot modify bond or compound.","definitionCN":"产生离子的过程；它是名词，不能修饰 bond 或 compound。"},{"word":"Ionic","ipa":"/aɪˈɒnɪk/","tag":"different word, same spelling","definition":"The adjective of Ionia, used of a Greek dialect and an architectural order; it shares spelling with the chemistry word but not origin.","definitionCN":"地名爱奥尼亚的形容词，用于一种希腊方言与一种建筑柱式；它与化学词同拼写而不同源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"covalent","ipa":"/ˌkəʊˈveɪlənt/","tag":"contrasting bond type","definition":"Describing bonds made by shared electrons; ionic bonds are made by transfer and attraction instead.","definitionCN":"描述由共享电子形成的键；离子键则由电子转移与吸引形成。"},{"word":"anionic","ipa":"/ˌænaɪˈɒnɪk/","tag":"negative species","definition":"Describing the negatively charged ions, a subset of ionic species rather than a synonym for all of them.","definitionCN":"描述带负电的离子，是离子物种的一个子集，而不是全部离子的同义词。"},{"word":"cationic","ipa":"/ˌkætaɪˈɒnɪk/","tag":"positive species","definition":"Describing the positively charged ions, the other subset, often used of surfactants and polymers.","definitionCN":"描述带正电的离子，是另一个子集，常用于表面活性剂与聚合物。"},{"word":"electrolytic","ipa":"/ɪˌlektrəˈlɪtɪk/","tag":"process word","definition":"Describing conduction or decomposition by electric current through an electrolyte; it names the method, not the bond.","definitionCN":"描述电流通过电解质引起的导电或分解；命名方法，而非键型。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek participle, Faraday's coinage and the separate Ionia line.","cn":"正常联想：真实的希腊分词、法拉第的造词，以及独立的地名线。"},"normal":[{"en":"Ion is Greek for a going thing, and the adjective simply says of ions.","cn":"ion 在希腊语中是「正在走的东西」，形容词就是「离子的」。"},{"en":"The family runs ion, ionic, ionize, ionization, anion and cation.","cn":"同族词有 ion、ionic、ionize、ionization、anion 与 cation。"},{"en":"Fixed phrases mark the applications: ionic bond, ionic liquid, ionic conduction.","cn":"固定搭配标出应用：离子键、离子液体、离子导电。"},{"en":"Faraday coined ion in 1834, so the chemistry sense has a date, while the Ionia sense is ancient.","cn":"法拉第在 1834 年造出 ion，因此化学义有确切年代，而爱奥尼亚义则古老。"},{"en":"Ionic and covalent are the two taught extremes: transfer against sharing.","cn":"ionic 与 covalent 是教学中两个极端：转移对共享。"}],"abstract":[{"en":"Picture two magnets that click together across a gap.","cn":"想象两块磁铁隔着空隙咔一声吸在一起。"},{"en":"Picture a stone column whose top curls like a rolled paper.","cn":"想象一根石柱，柱顶像卷起的纸那样卷曲。"},{"en":"Picture two crowds leaving one square through opposite gates.","cn":"想象两群人从同一个广场经相反的两道门离开。"}]},"examples":[{"en":"The ionic bond breaks when water molecules pull the ions apart.","cn":"当水分子把离子拉开时，离子键就断了。"},{"en":"Ionic liquids stay liquid at room temperature.","cn":"离子液体在室温下仍保持液态。"},{"en":"The building mixes an ionic colonnade with a plain wall.","cn":"这座建筑把爱奥尼亚柱廊与素墙混在一起。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ion（离子）+ ic」——离子那一类的 → 离子的、离子键的；另有一个同形词指爱奥尼亚柱式","word":"ionic"},"root":"希腊 ienai「去」→ 现在分词 ion「正在走的东西」→ 法拉第 1834 年造 ion「离子」→ 加 -ic → ionic「离子的」；另有同形词出自地名 Ionia「爱奥尼亚」，与离子无关。","sensesIntro":{"en":"Eight senses follow one charged particle, then one look-alike word: ions and their bonds, compounds, liquids, conduction, radius, currents, and finally the Ionic order and the region of Ionia, which share spelling but not origin.","cn":"八个义项先沿一个带电粒子展开，随后转向一个形近词：离子及其键、化合物、液体、导电、半径、离子流，最后是爱奥尼亚柱式与爱奥尼亚地区，它们同拼写而不同源。"},"semanticMap":{"core":{"en":"CORE IMAGE: a positive and a negative bead held apart yet pulling at each other across a gap.","cn":"核心意象：一正一负两颗珠子隔开，却越过空隙相互拉扯。"},"chain":["CHARGED PARTICLE","IONIC BOND","IONIC COMPOUND","CHARGED LIQUID","IONIC CURRENT","IONIA"],"branches":[{"senses":"01","en":"THE CHARGED LINK: attraction between ions, which is the plainest chemical sense.","cn":"带电的连接：离子之间的吸引，是最直白的化学义。"},{"senses":"02 · 03","en":"WHAT THE LINK BUILDS: salts that conduct when molten, and liquids that are themselves ions.","cn":"连接所造之物：熔融时导电的盐，以及本身即由离子构成的液体。"},{"senses":"04 · 05","en":"MEASURED BEHAVIOUR: charge that moves through a membrane, and a radius taken in a crystal.","cn":"被测的行为：穿过膜的电荷，以及在晶体中读取的半径。"},{"senses":"06","en":"THE LIVING CURRENT: the flow that excites nerve and muscle.","cn":"活体中的电流：使神经与肌肉兴奋的流动。"},{"senses":"07 · 08","en":"THE OTHER WORD: a column style and a Greek region, related to neither ion nor charge.","cn":"另一个词：一种柱式与一个希腊地区，与离子和电荷都无关。"}]},"affixes":{"intro":{"en":"Ionic is a noun plus a Greek adjective ending, and the same ending also appears on the architectural word, which is why the two look identical.","cn":"ionic 是名词加希腊形容词词尾，同一个词尾也出现在建筑那个词上，因此两者看起来一模一样。"},"latinIntro":{"en":"Latin took Greek ion as a loanword and added -icus, so the Latin entries here are Greek borrowings rather than native Latin nouns.","cn":"拉丁语把希腊语 ion 作为借词接收，再加上 -icus，因此这里的拉丁词条是希腊借词，而非拉丁本土名词。"},"items":[{"word":"ienai","structure":"ienai (Greek verb, to go)","meaning":"to go, come","meaningCN":"去；来","example":"The verb underlies the participle that became ion.","exampleCN":"这个动词是后来成为 ion 的那个分词的基础。"},{"word":"ion","structure":"ion (Greek present participle, a going thing)","meaning":"a thing that goes","meaningCN":"正在走的东西","example":"Faraday applied the word to particles travelling to an electrode.","exampleCN":"法拉第把这个词用于游向电极的粒子。"},{"word":"-ic","structure":"-ikos through Latin -icus (adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending turns the particle into a describing word.","exampleCN":"这个词尾把粒子变成描述性的词。"},{"word":"ionic","structure":"ion plus -ic","meaning":"relating to ions","meaningCN":"与离子有关的","example":"An ionic bond joins charged atoms.","exampleCN":"离子键把带电原子连在一起。"},{"word":"ionize","structure":"ion plus -ize (to make)","meaning":"to make into ions","meaningCN":"使成为离子","example":"The flame ionizes the gas above the burner.","exampleCN":"火焰使燃烧器上方的气体电离。"},{"word":"ionization","structure":"ionize plus -ation (process)","meaning":"the making of ions","meaningCN":"产生离子的过程","example":"Ionization needs energy equal to the binding of an electron.","exampleCN":"电离需要与电子结合能相当的能量。"},{"word":"anion","structure":"ana- (up) plus ion","meaning":"a negatively charged ion","meaningCN":"带负电的离子","example":"An anion moves toward the anode.","exampleCN":"阴离子朝阳极移动。"},{"word":"cation","structure":"kata- (down) plus ion","meaning":"a positively charged ion","meaningCN":"带正电的离子","example":"A cation moves toward the cathode.","exampleCN":"阳离子朝阴极移动。"},{"word":"ionically","structure":"ionic plus -ally (adverb)","meaning":"by ionic means","meaningCN":"以离子方式","example":"The layers are ionically bonded.","exampleCN":"这些层以离子键结合。"},{"word":"Ionia","structure":"Ionia (Greek place name)","meaning":"the Greek region on the coast of Asia Minor","meaningCN":"小亚细亚沿岸的希腊地区","example":"The architectural sense comes from this place name.","exampleCN":"建筑义来自这个地名。"}],"latinEntries":[{"word":"ion","structure":"ion, iontis (n., Greek loan in Latin)","meaning":"a going thing; an ion","meaningCN":"正在走的东西；离子"},{"word":"ionicus","structure":"ionicus (adj., Greek loan in Latin)","meaning":"of Ionia; Ionian","meaningCN":"爱奥尼亚的"}],"derivatives":[{"word":"ion","pos":"n.","zh":"离子"},{"word":"ionize","pos":"v.","zh":"电离"},{"word":"ionization","pos":"n.","zh":"电离"},{"word":"ionically","pos":"adv.","zh":"以离子方式"},{"word":"anion","pos":"n.","zh":"阴离子"}]}},{"word":"ion","ipa_uk":"/aɪˈɒn/","ipa_us":"/ˈaɪɑːn/","definition_zh":"离子；带电荷的原子或原子团","definition_en":"an atom or group of atoms that carries an electric charge","core_image":"一个原子失去一个电子后，周围浮起加号，被另一侧的减号吸过去","scene":"一个原子失去一个电子后，周围浮起加号，被另一侧的减号吸过去。Each ion in the solution carries either a positive or a negative charge.","sceneCN":"这里 ion 指带电荷的原子或原子团（第 1 个义项：因得到或失去电子而带电的粒子）；句意：溶液中的每个离子都带正电或负电。图中可辨识物件：原子核、散去的电子、加号、另一侧的减号。","pos":[{"tag":"n.","zh":"离子"}],"collocations":[{"phrase":"positive ion","zh":"正离子"},{"phrase":"negative ion","zh":"负离子"},{"phrase":"ion channel","zh":"离子通道"},{"phrase":"ion beam","zh":"离子束"},{"phrase":"ion exchange","zh":"离子交换"},{"phrase":"ion implantation","zh":"离子注入"}],"forms":[{"label":"复数","form":"ions"},{"label":"形容词（离子的）","form":"ionic"},{"label":"动词（电离）","form":"ionize"},{"label":"名词（电离）","form":"ionization"},{"label":"名词（阴离子）","form":"anion"}],"derivatives":[{"word":"ionic","pos":"adj.","zh":"离子的"},{"word":"ionize","pos":"v.","zh":"电离"},{"word":"ionization","pos":"n.","zh":"电离"},{"word":"anion","pos":"n.","zh":"阴离子"},{"word":"cation","pos":"n.","zh":"阳离子"}],"senses":[{"no":"01","title":"A charged atom or group","titleCN":"带电荷的原子或原子团","definition":"an atom or group of atoms that has gained or lost electrons and therefore carries a charge","definitionCN":"因得到或失去电子而带有电荷的原子或原子团","example":"Each ion in the solution carries either a positive or a negative charge.","exampleCN":"溶液中的每个离子都带正电或负电。","why":"Faraday took a Greek participle meaning a going thing and applied it to the particles that travel through a solution to the electrodes.","whyCN":"法拉第取用一个意为「正在走的东西」的希腊分词，用来指在溶液中游向电极的粒子。"},{"no":"02","title":"A positive ion","titleCN":"正离子","definition":"an ion that has lost electrons and carries a net positive charge, also called a cation","definitionCN":"失去电子、带净正电荷的离子，也称阳离子","example":"A positive ion moves toward the negative electrode.","exampleCN":"正离子朝阳极移动。","why":"charge has two signs, so the general word splits at once into positive and negative cases.","whyCN":"电荷只有两种符号，因此通称立刻分成正、负两种情形。"},{"no":"03","title":"A negative ion","titleCN":"负离子","definition":"an ion that has gained electrons and carries a net negative charge, also called an anion","definitionCN":"得到电子、带净负电荷的离子，也称阴离子","example":"A negative ion is attracted to the positive plate.","exampleCN":"负离子被正极板吸引。","why":"the other sign of charge needs its own label, and English uses the same noun with an adjective.","whyCN":"另一种电荷符号需要自己的标签，英语就用同一个名词加形容词来表示。"},{"no":"04","title":"A freely moving ion in solution","titleCN":"溶液中自由移动的离子","definition":"an ion dissolved in a liquid, free to move and therefore able to carry current","definitionCN":"溶于液体、可自由移动、因而能载流的离子","example":"The ions in seawater let it conduct electricity.","exampleCN":"海水中的离子使它能够导电。","why":"the word's first sense was exactly this mobile particle, and solution chemistry kept it as the everyday meaning.","whyCN":"这个词最初的义项正是这种会移动的粒子，溶液化学把它保留为日常含义。"},{"no":"05","title":"An ion in a plasma","titleCN":"等离子体中的离子","definition":"a charged particle in a gas hot enough to be partly ionised","definitionCN":"在热到部分电离的气体中存在的带电粒子","example":"The ions and electrons in the plasma drift along the magnetic field.","exampleCN":"等离子体中的离子与电子沿磁场漂移。","why":"when a whole gas becomes charged, the same noun names its charged component beside the electrons.","whyCN":"当整团气体带电时，同一个名词指其带电成分，与电子并列。"},{"no":"06","title":"An ion in physiology","titleCN":"生理学语境中的离子","definition":"a charged atom such as sodium or potassium that carries signals across cell membranes","definitionCN":"如钠、钾等带电原子，跨细胞膜传递信号","example":"Calcium ions trigger the muscle to contract.","exampleCN":"钙离子触发肌肉收缩。","why":"biology speaks of ions whenever a charged atom, not an electron, does the work of signalling.","whyCN":"在生物学中，只要执行信号功能的是带电原子而非电子，就用「离子」这个词。"},{"no":"07","title":"An ion in beams and implantation","titleCN":"离子束与离子注入中的离子","definition":"a charged atom accelerated in a beam for analysis, etching or doping a material","definitionCN":"在束流中被加速，用于分析、刻蚀或掺杂材料的带电原子","example":"The instrument fires ions at the surface to measure its layers.","exampleCN":"仪器向表面发射离子，以测量其各层。","why":"industry and analysis turn the particle into a tool, and the noun survives unchanged in the fixed phrases.","whyCN":"工业与分析把这种粒子变成工具，名词在固定说法中原样保留。"},{"no":"08","title":"An ion in space propulsion","titleCN":"航天推进中的离子","definition":"a charged atom accelerated electrically to produce thrust in an ion engine","definitionCN":"在离子发动机中被电加速以产生推力的带电原子","example":"The probe's engine accelerates ions to very high speed.","exampleCN":"探测器的发动机把离子加速到极高速度。","why":"spacecraft engineering borrowed the noun for the exhaust of a thruster, since the exhaust really is a stream of ions.","whyCN":"航天工程借这个名词指推进器的尾流，因为尾流确实是一束离子。"}],"etymology":{"intro":{"en":"Ion was coined by Michael Faraday in 1834 from Greek ion, the neuter present participle of ienai, to go. It reached English through scientific Latin. Dates are approximate.","cn":"ion 由法拉第在 1834 年依据希腊语 ion 造出，后者是 ienai「去」的中性现在分词。这个词经科学拉丁语进入英语。年代均为约数。"},"items":[{"era":"GREEK IENAI","en":"Ienai meant to go or come, and its forms supplied several Greek words of motion. The deeper Indo-European connections are reconstructions.","cn":"ienai 意为「去、来」，其各种形式提供了若干表示运动的希腊词。更早的印欧语联系属于重构。"},{"era":"GREEK ION","en":"The neuter participle ion meant a going thing, used in Greek of that which moves or travels.","cn":"中性分词 ion 意为「正在走的东西」，在希腊语中用于指移动或行进之物。"},{"era":"FARADAY 1834","en":"Faraday needed a name for the particles that leave the electrodes during electrolysis, and chose the Greek participle, giving English ion.","cn":"法拉第需要给电解时离开电极的粒子一个名字，他选了那个希腊分词，于是有了英语 ion。"},{"era":"SCIENTIFIC LATIN","en":"Scientific Latin took the word as ion, iontis, and the derived adjective ionicus; the English adjective ionic followed.","cn":"科学拉丁语以 ion、iontis 的形式接收这个词，并造出形容词 ionicus；英语形容词 ionic 随后出现。"},{"era":"ANION AND CATION","en":"Faraday also coined anion and cation from Greek ana-, up, and kata-, down, because of the direction each kind travels.","cn":"法拉第还依据希腊语 ana-「向上」与 kata-「向下」，造出 anion 与 cation，因为两类离子的移动方向不同。"},{"era":"FIRST DATE","en":"First date uncertain: Faraday's coinage is dated 1834 in his published papers, but the first appearance in an English text is not exactly settled.","cn":"首见年代不确定：法拉第的造词在其发表论文中记为 1834 年，但它在英语文本中的首次出现没有完全定论。"}]},"similar":{"note":{"en":"The first group is the ion family and its charged subtypes; the second group is the neutral particles and the general word for charge carriers they are often compared with.","cn":"第一组是 ion 词族及其带电子类；第二组是中性粒子，以及常与之比较的载流子通称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ionic","ipa":"/aɪˈɒnɪk/","tag":"same stem, adjective","definition":"The adjective meaning of ions; it describes bonds and compounds, and cannot stand as the noun itself.","definitionCN":"意为「离子的」的形容词；描述键与化合物，不能充当名词本身。"},{"word":"ionize","ipa":"/ˈaɪənaɪz/","tag":"same stem, verb","definition":"To strip or add electrons so that a neutral particle becomes an ion.","definitionCN":"剥离或添加电子，使中性粒子成为离子。"},{"word":"ionization","ipa":"/ˌaɪənaɪˈzeɪʃn/","tag":"same stem, process","definition":"The process of producing ions; it is the event, not the particle.","definitionCN":"产生离子的过程；是事件，不是粒子。"},{"word":"anion","ipa":"/ˈænaɪən/","tag":"subtype, negative","definition":"The negative ion, built with ana-, up, because it rises toward the anode in early electrolysis setups.","definitionCN":"带负电的离子，由 ana-「向上」构成，因为它在早期电解装置中朝阳极上升。"},{"word":"cation","ipa":"/ˈkætaɪən/","tag":"subtype, positive","definition":"The positive ion, built with kata-, down, the counterpart of anion in the same naming scheme.","definitionCN":"带正电的离子，由 kata-「向下」构成，是同一命名体系中 anion 的对应项。"}]},{"heading":"NEAR MEANING","entries":[{"word":"atom","ipa":"/ˈætəm/","tag":"neutral unit","definition":"The neutral particle; an ion is an atom or group that has gained or lost electrons.","definitionCN":"指中性粒子；离子则是得到或失去电子的原子或原子团。"},{"word":"molecule","ipa":"/ˈmɒlɪkjuːl/","tag":"neutral group","definition":"A neutral group of bonded atoms; a charged group of atoms is a molecular ion, not simply a molecule.","definitionCN":"由键连接的中性原子团；带电的原子团是分子离子，而不只是分子。"},{"word":"radical","ipa":"/ˈrædɪkl/","tag":"unpaired electron","definition":"A species with an unpaired electron; it may be neutral or charged, so it overlaps with ion without matching it.","definitionCN":"带未成对电子的物种，可能中性也可能带电，因此与离子有交集但并不等同。"},{"word":"charge carrier","ipa":"/tʃɑːdʒ ˈkæriə/","tag":"general role","definition":"Any particle that carries current, electrons or ions alike; ion names one kind of carrier.","definitionCN":"任何载流粒子，电子或离子皆可；ion 只命名其中一种载流子。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek participle, Faraday's date and the real laboratory phrases.","cn":"正常联想：真实的希腊分词、法拉第的年份与真实的实验室说法。"},"normal":[{"en":"Ion is a going thing: the particle that walks to the electrode.","cn":"ion 是「正在走的东西」：走向电极的那个粒子。"},{"en":"The family runs ion, ionic, ionize, ionization, anion and cation.","cn":"同族词有 ion、ionic、ionize、ionization、anion 与 cation。"},{"en":"Fixed phrases mark the uses: ion channel, ion beam, ion exchange.","cn":"固定搭配标出用途：离子通道、离子束、离子交换。"},{"en":"Anion and cation are twins made in the same year by the same man: up and down.","cn":"anion 与 cation 是同年由同一人造出的一对：向上与向下。"},{"en":"An ion differs from an atom only by electrons, which is why the charge sign is the whole story.","cn":"离子与原子只差电子，所以电荷符号就是全部关键。"}],"abstract":[{"en":"Picture a traveller who has lost a bag and now walks faster toward the gate.","cn":"想象一位丢了包的旅客，如今更快地走向登机口。"},{"en":"Picture two queues moving in opposite directions between the same two doors.","cn":"想象两列人在同两扇门之间朝相反方向移动。"},{"en":"Picture a current in water that is made of particles, not of wire.","cn":"想象水里的一股电流，由粒子而不是导线构成。"}]},"examples":[{"en":"The salt splits into ions as soon as it enters the water.","cn":"盐一进入水中就分成离子。"},{"en":"A lithium ion battery stores charge by moving ions between layers.","cn":"锂离子电池靠离子在层间移动来储电。"},{"en":"The detector counts each ion that passes through the slit.","cn":"探测器统计每一个穿过狭缝的离子。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ion」听似「爱用」——爱用电的那颗粒子，带电的原子 → 离子","word":"ion"},"root":"希腊 ienai「去」→ 中性现在分词 ion「正在走的东西」→ 法拉第 1834 年用作 ion「离子」→ 加 -ic 成 ionic；anion、cation 同出这一命名体系。","sensesIntro":{"en":"Eight senses follow one particle: something charged is on the move. The particle then splits by sign, appears in solution and in plasma, signals inside a body, and finally becomes a tool in beams and in space propulsion.","cn":"八个义项沿同一个粒子展开：一个带电之物正在移动。这个粒子随后按符号分正负，出现在溶液与等离子体中，在体内传递信号，最后成为束流与航天推进中的工具。"},"semanticMap":{"core":{"en":"CORE IMAGE: an atom that has lost an electron, a plus sign floating where the electron was, pulled toward a minus sign across the gap.","cn":"核心意象：一个失去电子的原子，电子原处浮起加号，被对面的减号隔空吸过去。"},"chain":["A GOING THING","CHARGED ATOM","POSITIVE AND NEGATIVE","IN SOLUTION","IN A PLASMA","AS A TOOL"],"branches":[{"senses":"01","en":"THE PARTICLE: an atom or group that gained or lost electrons.","cn":"粒子：得到或失去电子的原子或原子团。"},{"senses":"02 · 03","en":"TWO SIGNS: the same noun with a plus or a minus attached.","cn":"两种符号：同一个名词配上加号或减号。"},{"senses":"04 · 05","en":"WHERE IT MOVES: dissolved in liquid, or drifting in an ionised gas.","cn":"在哪里移动：溶于液体，或在电离气体中漂移。"},{"senses":"06","en":"THE BODY'S SIGNAL: calcium and sodium ions doing the work of nerves.","cn":"体内的信号：钙与钠离子承担神经的工作。"},{"senses":"07 · 08","en":"THE TOOL: a beam aimed at a surface, or exhaust pushed out of an engine.","cn":"工具：射向表面的束流，或从发动机喷出的尾流。"}]},"affixes":{"intro":{"en":"Ion is one Greek participle that became a scientific noun; its family is built with Greek prefixes and English endings.","cn":"ion 是一个变成科学名词的希腊分词；它的词族由希腊前缀与英语词尾构成。"},"latinIntro":{"en":"Latin received ion as a Greek loan and added the adjective ionicus; the Latin entries below are borrowings, not native Latin words.","cn":"拉丁语把 ion 作为希腊借词接收，并加上形容词 ionicus；下面的拉丁词条是借词，而非拉丁本土词。"},"items":[{"word":"ienai","structure":"ienai (Greek verb, to go)","meaning":"to go, come","meaningCN":"去；来","example":"The verb is the source of the participle.","exampleCN":"这个动词是那个分词的来源。"},{"word":"ion","structure":"ion (Greek present participle, a going thing)","meaning":"a thing that goes","meaningCN":"正在走的东西","example":"Faraday gave the participle a chemical job.","exampleCN":"法拉第给这个分词一份化学职务。"},{"word":"ion","structure":"the English noun, from the Greek participle","meaning":"a charged particle","meaningCN":"带电粒子","example":"Every ion carries a charge.","exampleCN":"每个离子都带电荷。"},{"word":"ionic","structure":"ion plus -ic (relating to)","meaning":"of ions","meaningCN":"离子的","example":"Ionic bonds hold the crystal together.","exampleCN":"离子键把晶体维系在一起。"},{"word":"ionize","structure":"ion plus -ize (to make)","meaning":"to turn into ions","meaningCN":"使成为离子","example":"Radiation can ionize the gas.","exampleCN":"辐射能使气体电离。"},{"word":"ionization","structure":"ionize plus -ation (process)","meaning":"the production of ions","meaningCN":"产生离子的过程","example":"Ionization rises with temperature.","exampleCN":"电离随温度升高而增加。"},{"word":"anion","structure":"ana- (up) plus ion","meaning":"a negative ion","meaningCN":"负离子","example":"An anion climbs toward the anode.","exampleCN":"阴离子朝阳极上升。"},{"word":"cation","structure":"kata- (down) plus ion","meaning":"a positive ion","meaningCN":"正离子","example":"A cation sinks toward the cathode.","exampleCN":"阳离子朝阳极下沉。"},{"word":"ionosphere","structure":"ion plus -sphere (layer)","meaning":"the ion-rich upper atmosphere","meaningCN":"富含离子的高层大气","example":"Radio waves bounce off the ionosphere.","exampleCN":"无线电波从电离层反射。"},{"word":"ion beam","structure":"ion plus beam","meaning":"a stream of accelerated ions","meaningCN":"被加速的离子束","example":"An ion beam can etch a surface layer by layer.","exampleCN":"离子束能一层层刻蚀表面。"}],"latinEntries":[{"word":"ion","structure":"ion, iontis (n., Greek loan in Latin)","meaning":"a going thing; an ion","meaningCN":"正在走的东西；离子"},{"word":"ionicus","structure":"ionicus (adj., Greek loan in Latin)","meaning":"ionic; of ions","meaningCN":"离子的"}],"derivatives":[{"word":"ionic","pos":"adj.","zh":"离子的"},{"word":"ionize","pos":"v.","zh":"电离"},{"word":"ionization","pos":"n.","zh":"电离"},{"word":"anion","pos":"n.","zh":"阴离子"},{"word":"cation","pos":"n.","zh":"阳离子"}]}}]);
